function sectorIdForQuery(raw: string): string | null {
  const q = norm(raw);
  if (!q) return null;
  const aliases: [string, string][] = [["laboratorio", "laboratorio"], ["lab", "laboratorio"], ["clinica", "clinica"]];
  for (const [key, id] of aliases) if (q === key || q.includes(key)) return id;
  for (const s of SECTORS) { const name = norm(s.name); if (name.includes(q) || (q.length >= 3 && q.includes(name))) return s.id; }
  return null;
}
function isAllSectorsQuery(raw: string) { const q = norm(raw); return q === "setor" || q === "setores" || q === "todos os setores" || q === "todos setor" || q.includes("todos os setores") || q.includes("todos os setor"); }
function pickSuggestions(list: AiSuggestion[], cycle: number, count: number) { if (!list.length) return []; const start = ((cycle % list.length) + list.length) % list.length; return [...list.slice(start), ...list.slice(0, start)].slice(0, count); }

