    const a = byId(q.includes("laboratorio") ? "laboratorio" : "clinica"); a.diagnosis = "Provável acúmulo de chamados com espera de verificação ou calibração, pressionando o SLA no prazo."; a.steps = ["Listar os chamados em risco de SLA e ordenar por impacto no atendimento.", "Confirmar quais aguardam verificação e destravar a próxima janela.", "Agrupar as preventivas e verificações por turno para ganhar tempo.", "Revisar ao fim do dia os chamados reabertos para tratar a causa raiz."]; a.impact = "SLA mais próximo da meta, com menos chamados reabertos na semana."; return a;
