const GESTOR_KEYWORDS: Record<string, string[]> = {
  "gestor-foco": ["focar", "foco", "esforco", "priorizar", "prioridade", "retorno", "demanda"],
  "gestor-gargalos": ["gargalo", "gargalos", "funil", "fluxo", "recebimento", "analise", "validacao", "liberacao", "tempo", "atraso", "demora"],
  "gestor-redistribuicao": ["redistribuicao", "redistribuir", "carga", "bancada", "bancadas", "sobrecarga", "equilibrio"],
  "gestor-horarios": ["horario", "horarios", "coleta", "coletas", "pico", "ociosidade", "agenda", "manha", "tarde"],
  "gestor-estoque": ["estoque", "compra", "compras", "reagente", "reagentes", "lote", "lotes", "repor", "reposicao", "comprar"],
  "gestor-internalizar": ["internalizar", "terceirizar", "terceirizado", "interno", "externo", "apoio", "origem"],
  "gestor-investimentos": ["investimento", "investimentos", "investir", "alocar", "recurso", "analisador", "reforma", "tecnico", "tecnologia"],
  "gestor-comprar-alugar": ["comprar", "alugar", "aluguel", "locacao", "versus", "aluguel"],
  "gestor-renegociacao": ["renegociar", "renegociacao", "fornecedor", "fornecedores", "convenio", "convenios", "glosa", "volume"],
  "gestor-alertas": ["alerta", "alertas", "queda", "recoleta", "recoletas", "custo", "fila", "inteligente"],
  "gestor-comparativo": ["comparativo", "comparar", "comparacao", "areas", "equipamentos", "turnos", "periodos", "periodo"],
  "gestor-simulacao": ["simulacao", "simular", "cenario", "cenarios", "simulador"],
  "gestor-resumo": ["resumo", "mensal", "novembro", "mes"],
  "gestor-eficiencia": ["eficiencia", "indicador", "nota", "desempenho", "tat", "prazo", "satisfacao"],
};
function gestorScore(item: GestorSug, tokens: string[]) {
  const kws = GESTOR_KEYWORDS[item.id] || []; let score = 0;
  for (const token of tokens) for (const kw of kws) { let common = 0; while (common < Math.min(token.length, kw.length) && token[common] === kw[common]) common += 1; if (token === kw) score += 3; else if (common >= 4) score += 2; else if (token.includes(kw) || kw.includes(token)) score += 1; }
  return score;
}
function SugestoesGestorLaboratorioPanel({ prompt, onNotice }: { prompt: string; onNotice: (m: string) => void }) {
  const [applied, setApplied] = useState<Set<string>>(new Set());
  const [ignored, setIgnored] = useState<Set<string>>(new Set());
  const [showHidden, setShowHidden] = useState(false);
  const [showAll, setShowAll] = useState(false);
  const [compareMode, setCompareMode] = useState("Áreas");
  const [simScenario, setSimScenario] = useState("Novo analisador");
  const [simVolume, setSimVolume] = useState(1200);
  const [simValor, setSimValor] = useState(42);
  const [savedSims, setSavedSims] = useState<{ id: string; scenario: string; volume: number; valor: number; receita: number; custo: number; margem: number }[]>([]);
  const [savingSim, setSavingSim] = useState(false);
  const [summaryAt, setSummaryAt] = useState("");
  const [summaryCount, setSummaryCount] = useState(0);
  const [renegPrepared, setRenegPrepared] = useState<Set<string>>(new Set());
  const [alertDone, setAlertDone] = useState<Set<string>>(new Set());
  const [investChoice, setInvestChoice] = useState("");
  const inputCls = "w-full rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-sm outline-none";
  const labelCls = "block text-sm font-bold";
  useEffect(() => { setShowAll(false); }, [prompt]);
  useEffect(() => { let alive = true; (async () => { try { const d: any = await api("records.list", { collection: "gottcured_lab_sugestoes_gestor" }); if (!alive || !d?.records?.length) return; const ap = new Set<string>(); const ig = new Set<string>(); const sims: any[] = []; for (const r of d.records) { const v = r.value || {}; if (v.sugestaoId && v.status === "applied") ap.add(v.sugestaoId); if (v.sugestaoId && v.status === "ignored") ig.add(v.sugestaoId); if (v.kind === "simulacao") sims.push({ id: String(r.id), scenario: v.scenario, volume: v.volume, valor: v.valor, receita: v.receita, custo: v.custo, margem: v.margem }); } if (ap.size) setApplied(ap); if (ig.size) setIgnored(ig); if (sims.length) setSavedSims(sims); } catch { } })(); return () => { alive = false; }; }, []);
  async function persistGestor(sugestaoId: string, status: string) { try { await api("records.create", { collection: "gottcured_lab_sugestoes_gestor", value: { sugestaoId, status, createdAt: new Date().toISOString() }, idempotency_key: `gottcured-lab-gestor-${sugestaoId}-${status}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}` }); } catch { } }
  const promptNorm = norm(prompt || "");
  const tokens = promptNorm.split(/[^a-z0-9]+/).filter(t => t.length >= 3 && !["para", "qual", "como", "quando", "onde", "sera", "tem", "ter", "uma", "uns", "umas", "dos", "das", "com", "que", "pra", "por", "isso", "esta", "esse", "essa", "meu", "minha", "sobre", "ainda", "mais", "muito", "vai", "fazer", "pode", "poder"].includes(t));
  const hasPrompt = tokens.length > 0;
  const active = GESTOR_SUGS.filter(s => !ignored.has(s.id));
  const hidden = GESTOR_SUGS.filter(s => ignored.has(s.id));
  const scored = active.map((item, index) => ({ item, index, score: gestorScore(item, tokens) }));
  const matched = hasPrompt ? scored.filter(s => s.score > 0).sort((a, b) => b.score - a.score || a.index - b.index) : scored;
  const visible = (hasPrompt && matched.length === 0 && showAll ? scored : matched).map(s => s.item);
  function applyItem(s: GestorSug) {
    if (s.id === "gestor-simulacao") { saveSim(); return; }
    if (s.id === "gestor-resumo") { const now = new Date().toLocaleString("pt-BR"); setSummaryAt(now); setSummaryCount(c => c + 1); }
    setApplied(prev => new Set(prev).add(s.id)); persistGestor(s.id, "applied"); onNotice(s.applyMessage);
  }
  function ignoreItem(s: GestorSug) { setIgnored(prev => new Set(prev).add(s.id)); persistGestor(s.id, "ignored"); onNotice(s.ignoreMessage); }
  function reopen(s: GestorSug) { setIgnored(prev => { const n = new Set(prev); n.delete(s.id); return n; }); persistGestor(s.id, "open"); onNotice(`Sugestão reaberta: ${s.title}.`); }
  const simCfg = simScenario === "Novo analisador" ? { unit: 18, fixed: 14200, label: "Novo analisador" } : simScenario === "Novo turno" ? { unit: 22, fixed: 9800, label: "Novo turno" } : { unit: 31, fixed: 2400, label: "Terceirizar exame" };
  const simReceita = simVolume * simValor; const simCusto = simVolume * simCfg.unit + simCfg.fixed; const simMargem = simReceita - simCusto; const simPct = simReceita ? Math.round(simMargem / simReceita * 100) : 0;
  async function saveSim() {
    if (simVolume <= 0 || simValor <= 0) { onNotice("Informe volume por mês e valor médio maiores que zero para simular."); return; }
    setSavingSim(true);
    try {
      const created: any = await api("records.create", { collection: "gottcured_lab_sugestoes_gestor", value: { kind: "simulacao", sugestaoId: "gestor-simulacao", scenario: simScenario, volume: simVolume, valor: simValor, receita: simReceita, custo: simCusto, margem: simMargem, createdAt: new Date().toISOString() }, idempotency_key: `gottcured-lab-gestor-sim-${Date.now()}` });
      setSavedSims(prev => [{ id: String(created?.id || `sim-${Date.now()}`), scenario: simScenario, volume: simVolume, valor: simValor, receita: simReceita, custo: simCusto, margem: simMargem }, ...prev]);
      setApplied(prev => new Set(prev).add("gestor-simulacao"));
      onNotice(`Simulação salva: ${simScenario} — receita ${money(simReceita)}, custo ${money(simCusto)}, margem ${money(simMargem)} (${simPct}%).`);
    } catch { onNotice("Não foi possível salvar a simulação. Tente novamente — nenhuma simulação foi salva."); }
    setSavingSim(false);
  }
  const compareData = compareMode === "Áreas" ? [{ name: "Bioquímica", receita: 96000, custo: 54000 }, { name: "Hematologia", receita: 88000, custo: 48000 }, { name: "Hormonal", receita: 42000, custo: 31000 }, { name: "Microbiologia", receita: 21000, custo: 26000 }] : compareMode === "Equipamentos" ? [{ name: "Analisador L-01", receita: 68000, custo: 34000 }, { name: "Analisador L-02", receita: 54000, custo: 29000 }, { name: "Centrífuga C-05", receita: 18000, custo: 12000 }, { name: "Autoclave A-03", receita: 9000, custo: 8400 }] : compareMode === "Turnos" ? [{ name: "Manhã", receita: 142000, custo: 78000 }, { name: "Tarde", receita: 98000, custo: 62000 }, { name: "Noite", receita: 34000, custo: 28000 }] : [{ name: "Set", receita: 298000, custo: 186000 }, { name: "Out", receita: 312000, custo: 194000 }, { name: "Nov", receita: 326000, custo: 198000 }];
  const focoRows = [{ item: "Bioquímica", retorno: 96000, demanda: 6420, custo: 54000, score: 94, rec: "Focar" }, { item: "Hematologia", retorno: 88000, demanda: 7120, custo: 48000, score: 92, rec: "Focar" }, { item: "Hormonal", retorno: 42000, demanda: 1980, custo: 31000, score: 76, rec: "Manter" }, { item: "Imagem", retorno: 38000, demanda: 1420, custo: 24000, score: 72, rec: "Manter" }, { item: "Microbiologia", retorno: 21000, demanda: 1180, custo: 26000, score: 48, rec: "Revisar" }];
  const investimentos = [{ id: "analisador", title: "Analisador novo", custo: 185000, retorno: 22600, payback: "8 meses", detail: "Analisador de Bioquímica novo reduz terceirização e fila de análise." }, { id: "reforma", title: "Reforma — sala de Validação", custo: 42000, retorno: 8900, payback: "5 meses", detail: "Mais 2 postos de validação para destravar o gargalo do funil." }, { id: "tecnico", title: "Novo técnico", custo: 9800, retorno: 18400, payback: "1 mês", detail: "1 técnico para o pico da manhã (custo mensal × receita de exames)." }, { id: "tecnologia", title: "Tecnologia — validação automática", custo: 2400, retorno: 11200, payback: "1 mês", detail: "Regras automáticas de validação reduzem fila e retrabalho." }];
  const comprarAlugar = [{ item: "Analisador Bioquímica", tipo: "Equipamento", comprar: 3850, alugar: 4900, rec: "Comprar", just: "Volume alto dilui o custo de compra." }, { item: "Centrífuga C-05", tipo: "Equipamento", comprar: 1420, alugar: 1780, rec: "Comprar", just: "Uso frequente — compra mais barata por mês." }, { item: "Reagente Glicose", tipo: "Reagente", comprar: 12400, alugar: 14800, rec: "Comprar", just: "Compra em lote com desconto por volume +22%." }, { item: "Reagente PCR", tipo: "Reagente", comprar: 8600, alugar: 7900, rec: "Alugar", just: "Uso menor e lote com validade curta — aluguel evita perda." }];
  const alertas = [{ id: "al-queda", title: "Queda de volume", detail: "Volume caiu 6,2% vs. mês anterior (de 31.800 para 29.840 exames). Maior queda: Microbiologia nas tardes.", impact: "Cerca de R$ 12 mil/mês de receita a menos se a queda continuar." }, { id: "al-recoleta", title: "Aumento de recoletas", detail: "Recoletas subiram de 1,4% para 2,1% (de 445 para 627 recoletas). Concentração: coleta 7h–9h.", impact: "Cada recoleta custa cerca de R$ 38 em material + retrabalho." }, { id: "al-custo", title: "Custo acima do previsto", detail: "Custo de reagentes 12,6% acima do previsto no mês, puxado pelo reagente Glicose (+22% de consumo).", impact: "Cerca de R$ 9.400 acima do orçamento no mês." }, { id: "al-estoque", title: "Estoque baixo", detail: "Reagente Glicose: 6 dias de cobertura. Reagente TSH: 9 dias de cobertura.", impact: "Risco de ruptura e parada da bancada se não houver reposição." }, { id: "al-fila", title: "Fila de validação alta", detail: "34 exames aguardando validação, tempo médio 2h45 (meta 1h30).", impact: "TAT total sobe e o % no prazo cai de 91% para 89%." }];
  const eficiencia = [{ name: "TAT", v: 78 }, { name: "% no prazo", v: 89 }, { name: "Recoletas", v: 84 }, { name: "Ocupação", v: 86 }, { name: "Margem", v: 74 }, { name: "Satisfação", v: 92 }];
  function renderDetail(s: GestorSug) {
    if (s.id === "gestor-foco") return <div className="mt-3 overflow-x-auto"><table className="w-full min-w-[520px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Área / exame</th><th className="py-2 pr-3">Retorno</th><th className="py-2 pr-3">Demanda</th><th className="py-2 pr-3">Custo</th><th className="py-2 pr-3">Score</th><th className="py-2">Recomendação</th></tr></thead><tbody>{focoRows.map(r => <tr key={r.item} className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">{r.item}</td><td className="py-2 pr-3">{money(r.retorno)}</td><td className="py-2 pr-3">{r.demanda.toLocaleString("pt-BR")}</td><td className="py-2 pr-3">{money(r.custo)}</td><td className="py-2 pr-3 font-extrabold">{r.score}</td><td className="py-2"><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${r.rec === "Focar" ? "bg-[var(--primary-soft)] text-[var(--primary)]" : r.rec === "Manter" ? "bg-[#FFF0C5] text-[#7A5600]" : "bg-[#F8DEDC] text-[#8B2626]"}`}>{r.rec}</span></td></tr>)}</tbody></table></div>;
    if (s.id === "gestor-gargalos") return <div className="mt-3 space-y-2">{[{ e: "Coleta", t: "38 min", pct: 18, hot: false }, { e: "Recebimento", t: "22 min", pct: 10, hot: false }, { e: "Análise", t: "6h10", pct: 68, hot: false }, { e: "Validação", t: "2h45 — GARGALO", pct: 100, hot: true }, { e: "Liberação", t: "48 min", pct: 24, hot: false }].map(f => <div key={f.e}><div className="flex flex-wrap justify-between gap-2 text-sm"><span className="font-bold">{f.e}</span><span className={`font-extrabold ${f.hot ? "text-[#C83E3E]" : ""}`}>{f.t}</span></div><div className="mt-1 h-2.5 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full" style={{ width: `${f.pct}%`, background: f.hot ? "#C83E3E" : "var(--primary)" }} /></div></div>)}</div>;
    if (s.id === "gestor-redistribuicao") return <div className="mt-3 grid gap-2 sm:grid-cols-2">{[{ n: "Bancada 1", antes: 94, depois: 76, fila: "22 → 8 exames" }, { n: "Bancada 2", antes: 58, depois: 76, fila: "6 → 12 exames" }].map(b => <div key={b.n} className="rounded-xl bg-[var(--surface)] p-3"><p className="font-bold text-sm">{b.n}</p><p className="mt-1 text-sm">Ocupação: <strong>{b.antes}% → {b.depois}%</strong></p><p className="text-sm text-[var(--muted)]">Fila: {b.fila}</p><div className="mt-2 h-2 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{ width: `${applied.has(s.id) ? b.depois : b.antes}%` }} /></div></div>)}</div>;
    if (s.id === "gestor-horarios") return <div className="mt-3 overflow-x-auto"><table className="w-full min-w-[420px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Horário</th><th className="py-2 pr-3">Coletas</th><th className="py-2 pr-3">Espera média</th><th className="py-2">Situação</th></tr></thead><tbody><tr className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">7h–9h</td><td className="py-2 pr-3">342</td><td className="py-2 pr-3">38 min</td><td className="py-2 font-bold text-[#8B2626]">Pico — abrir mais coletas</td></tr><tr className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">9h–12h</td><td className="py-2 pr-3">418</td><td className="py-2 pr-3">24 min</td><td className="py-2">Estável</td></tr><tr className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">14h–15h</td><td className="py-2 pr-3">96</td><td className="py-2 pr-3">12 min</td><td className="py-2 font-bold text-[#7A5600]">Ociosidade 38% — reduzir</td></tr></tbody></table></div>;
    if (s.id === "gestor-estoque") return <div className="mt-3 space-y-2"><p className="rounded-xl bg-[var(--surface)] p-3 text-sm"><strong>Comprar — Reagente Glicose:</strong> 3 lotes · cobertura 6 dias · consumo +22% · ruptura prevista sem reposição.</p><p className="rounded-xl bg-[var(--surface)] p-3 text-sm"><strong>Reduzir — Reagente PCR:</strong> cobertura 42 dias · consumo estável · reduzir o próximo lote para liberar cerca de R$ 6.800.</p></div>;
    if (s.id === "gestor-internalizar") return <div className="mt-3 overflow-x-auto"><table className="w-full min-w-[520px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Exame</th><th className="py-2 pr-3">Interno</th><th className="py-2 pr-3">Terceirizado</th><th className="py-2 pr-3">Volume / mês</th><th className="py-2">Recomendação</th></tr></thead><tbody><tr className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">Hemoglobina glicada</td><td className="py-2 pr-3">R$ 34</td><td className="py-2 pr-3">R$ 52</td><td className="py-2 pr-3">1.240</td><td className="py-2 font-bold text-[var(--primary)]">Internalizar Exame A</td></tr><tr className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">Estradiol</td><td className="py-2 pr-3">R$ 78</td><td className="py-2 pr-3">R$ 48</td><td className="py-2 pr-3">96</td><td className="py-2 font-bold text-[#7A5600]">Terceirizar Exame B</td></tr><tr className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">Vitamina D</td><td className="py-2 pr-3">R$ 61</td><td className="py-2 pr-3">R$ 58</td><td className="py-2 pr-3">210</td><td className="py-2 font-bold">Manter terceirizado</td></tr></tbody></table></div>;
    if (s.id === "gestor-investimentos") return <div className="mt-3 grid gap-2 sm:grid-cols-2">{investimentos.map(inv => <div key={inv.id} className="rounded-xl bg-[var(--surface)] p-3"><div className="flex flex-wrap justify-between gap-2"><p className="font-bold text-sm">{inv.title}</p>{investChoice === inv.id && <span className="rounded-full bg-[var(--primary-soft)] px-2 py-0.5 text-[11px] font-bold text-[var(--primary)]">Escolhido</span>}</div><p className="mt-1 text-[13px] text-[var(--muted)]">{inv.detail}</p><p className="mt-2 text-sm">Custo: <strong>{money(inv.custo)}</strong> · Retorno: <strong>{money(inv.retorno)}/mês</strong> · Payback: <strong>{inv.payback}</strong></p><button onClick={() => { setInvestChoice(inv.id); onNotice(`Investimento escolhido para simulação: ${inv.title} — custo ${money(inv.custo)}, retorno ${money(inv.retorno)}/mês, payback ${inv.payback}.`); }} className="mt-2 pill px-3 py-1.5 text-xs font-bold">Escolher este investimento</button></div>)}</div>;
    if (s.id === "gestor-comprar-alugar") return <div className="mt-3 overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Item</th><th className="py-2 pr-3">Tipo</th><th className="py-2 pr-3">Comprar / mês</th><th className="py-2 pr-3">Alugar / mês</th><th className="py-2 pr-3">Recomendação</th><th className="py-2">Justificativa</th></tr></thead><tbody>{comprarAlugar.map(r => <tr key={r.item} className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">{r.item}</td><td className="py-2 pr-3">{r.tipo}</td><td className="py-2 pr-3">{money(r.comprar)}</td><td className="py-2 pr-3">{money(r.alugar)}</td><td className="py-2 pr-3"><span className="rounded-full bg-[var(--primary-soft)] px-2.5 py-1 text-[11px] font-bold text-[var(--primary)]">{r.rec}</span></td><td className="py-2 text-[13px] text-[var(--muted)]">{r.just}</td></tr>)}</tbody></table></div>;
    if (s.id === "gestor-renegociacao") return <div className="mt-3 space-y-2">{[{ id: "ren-glicose", t: "Renegociar reagente Glicose — volume subiu 22%", d: "De 4.100 para 5.002 testes/mês. Pedir desconto de 8% por volume." }, { id: "ren-convenio", t: "Renegociar convênio Y — glosa 8%", d: "R$ 9.600/mês glosados, maior parte por documentação. Revisar regras e checklist." }].map(r => <div key={r.id} className="rounded-xl bg-[var(--surface)] p-3"><p className="font-bold text-sm">{r.t}</p><p className="mt-1 text-sm text-[var(--muted)]">{r.d}</p>{renegPrepared.has(r.id) ? <p className="mt-2 text-[13px] font-bold text-[var(--ok)]">✓ Preparado para renegociação</p> : <button onClick={() => { setRenegPrepared(prev => new Set(prev).add(r.id)); onNotice(`Renegociação preparada: ${r.t}.`); }} className="mt-2 rounded-full bg-[var(--primary)] px-3 py-1.5 text-xs font-bold text-white">Preparar renegociação</button>}</div>)}</div>;
    if (s.id === "gestor-alertas") return <div className="mt-3 space-y-2">{alertas.map(a => <div key={a.id} className="rounded-xl bg-[var(--surface)] p-3"><div className="flex flex-wrap justify-between gap-2"><p className="font-bold text-sm">{a.title}</p>{alertDone.has(a.id) ? <span className="text-[12px] font-bold text-[var(--ok)]">✓ Aplicado</span> : <button onClick={() => { setAlertDone(prev => new Set(prev).add(a.id)); onNotice(`Alerta aplicado: ${a.title} — ${a.impact}`); }} className="pill px-3 py-1 text-xs font-bold">Aplicar alerta</button>}</div><p className="mt-1 text-sm text-[var(--muted)]">{a.detail}</p><p className="mt-1 text-[13px] font-bold">Impacto: {a.impact}</p></div>)}</div>;
    if (s.id === "gestor-comparativo") return <div className="mt-3"><label className={labelCls}>Comparar<select value={compareMode} onChange={e => setCompareMode(e.target.value)} className={`${inputCls} mt-1`}><option>Áreas</option><option>Equipamentos</option><option>Turnos</option><option>Períodos</option></select></label><div className="mt-3 h-[220px]"><ResponsiveContainer><BarChart data={compareData}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="name" tick={{ fill: "var(--muted)", fontSize: 11 }} /><YAxis tick={{ fill: "var(--muted)", fontSize: 11 }} /><Tooltip contentStyle={{ background: "var(--surface)", border: "1px solid var(--line)", borderRadius: 12 }} formatter={(v: any) => [money(Number(v)), "Valor"]} /><Bar dataKey="receita" fill="#0F5F5C" radius={[6, 6, 0, 0]} name="Receita" /><Bar dataKey="custo" fill="#E4A11B" radius={[6, 6, 0, 0]} name="Custo" /></BarChart></ResponsiveContainer></div><div className="mt-2 overflow-x-auto"><table className="w-full min-w-[420px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">{compareMode}</th><th className="py-2 pr-3">Receita</th><th className="py-2 pr-3">Custo</th><th className="py-2">Margem</th></tr></thead><tbody>{compareData.map(r => <tr key={r.name} className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">{r.name}</td><td className="py-2 pr-3">{money(r.receita)}</td><td className="py-2 pr-3">{money(r.custo)}</td><td className="py-2 font-bold">{money(r.receita - r.custo)}</td></tr>)}</tbody></table></div></div>;
    if (s.id === "gestor-simulacao") return <div className="mt-3"><div className="grid gap-2 sm:grid-cols-3"><label className={labelCls}>Cenário<select value={simScenario} onChange={e => setSimScenario(e.target.value)} className={`${inputCls} mt-1`}><option>Novo analisador</option><option>Novo turno</option><option>Terceirizar exame</option></select></label><label className={labelCls}>Volume / mês<input type="number" min={0} value={simVolume} onChange={e => setSimVolume(Number(e.target.value))} className={`${inputCls} mt-1`} /></label><label className={labelCls}>Valor médio (R$)<input type="number" min={0} value={simValor} onChange={e => setSimValor(Number(e.target.value))} className={`${inputCls} mt-1`} /></label></div><div className="mt-3 grid gap-2 sm:grid-cols-3"><div className="rounded-xl bg-[var(--surface)] p-3 text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">Receita simulada</p><p className="mt-1 text-[18px] font-extrabold">{money(simReceita)}</p></div><div className="rounded-xl bg-[var(--surface)] p-3 text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">Custo simulado</p><p className="mt-1 text-[18px] font-extrabold">{money(simCusto)}</p></div><div className="rounded-xl bg-[var(--surface)] p-3 text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">Margem simulada</p><p className="mt-1 text-[18px] font-extrabold">{money(simMargem)} · {simPct}%</p></div></div><p className="mt-2 text-xs text-[var(--muted)]">Simulação — não cria contratação, turno ou terceirização automaticamente.</p>{savedSims.length > 0 && <div className="mt-3 space-y-1"><p className="font-bold text-sm">Simulações salvas ({savedSims.length})</p>{savedSims.map(x => <p key={x.id} className="rounded-xl bg-[var(--surface)] p-2 text-sm"><strong>{x.scenario}</strong> · {x.volume}/mês × {money(x.valor)} · Receita {money(x.receita)} · Custo {money(x.custo)} · Margem {money(x.margem)}</p>)}</div>}</div>;
    if (s.id === "gestor-resumo") return <div className="mt-3"><div className="rounded-xl bg-[var(--surface)] p-4"><div className="flex flex-wrap justify-between gap-2"><h4 className="font-extrabold">Resumo de Novembro</h4>{summaryAt && <span className="rounded-full bg-[var(--primary-soft)] px-2.5 py-1 text-[11px] font-bold text-[var(--primary)]">Gerado em {summaryAt}</span>}</div><div className="mt-3 grid gap-2 sm:grid-cols-4"><div className="text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">Volume</p><p className="mt-1 text-[18px] font-extrabold">29.840</p></div><div className="text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">Receita</p><p className="mt-1 text-[18px] font-extrabold">R$ 326 mil</p></div><div className="text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">TAT médio</p><p className="mt-1 text-[18px] font-extrabold">11h20</p></div><div className="text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">Recoeltas</p><p className="mt-1 text-[18px] font-extrabold">2,1%</p></div></div><ul className="mt-3 list-disc space-y-1 pl-5 text-sm leading-6"><li>Validação é o gargalo: 2h45 de média, 34 exames aguardando.</li><li>Recoeltas subiram para 2,1% — concentradas na coleta 7h–9h.</li><li>Reagente Glicose com 6 dias de cobertura — comprar 3 lotes.</li><li>Margem pressionada pelo custo de reagentes (+12,6%) e glosa de 8% no convênio Y.</li></ul>{summaryCount > 0 && <p className="mt-2 text-[13px] text-[var(--muted)]">Resumo gerado {summaryCount} vez(es) nesta sessão.</p>}</div></div>;
    if (s.id === "gestor-eficiencia") return <div className="mt-3"><div className="flex flex-wrap justify-between gap-2"><p className="font-extrabold">Indicador geral de eficiência do laboratório</p><span className="text-[28px] font-extrabold leading-none text-[var(--primary)]">82 / 100</span></div><div className="mt-2 h-3 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{ width: "82%" }} /></div><div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{eficiencia.map(p => <div key={p.name} className="rounded-xl bg-[var(--surface)] p-3"><div className="flex justify-between"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">{p.name}</p><p className="font-extrabold">{p.v}</p></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{ width: `${p.v}%` }} /></div></div>)}</div></div>;
    return null;
  }
  return <div className="mt-4 rounded-2xl border border-[var(--line)] bg-[var(--surface-3)] p-4 sm:p-5">
    <div className="flex flex-wrap items-start justify-between gap-2"><div><h3 className="text-[16px] font-extrabold">Sugestões para o Gestor — IA · Laboratório</h3><p className="mt-1 text-[13px] leading-5 text-[var(--muted)]">14 sugestões dentro do Modo IA, ao lado do painel “Previsões da IA”. Digite a pergunta na caixa acima para filtrar — ex.: “onde focar?”, “gargalos?”, “comprar ou alugar?”.</p></div><span className="rounded-full bg-[var(--primary-soft)] px-3 py-1.5 text-[12px] font-bold text-[var(--primary)]">{visible.length} de {active.length} sugestões</span></div>
    <div className="mt-3 rounded-2xl bg-[#FFF7D6] px-4 py-3 text-sm font-bold text-[#7A5600]">IA — sugestões são APOIO. A decisão é do gestor. Nenhuma sugestão cria compra, contratação, turno ou terceirização automaticamente.</div>
    {hasPrompt && matched.length > 0 && <p role="status" className="mt-3 rounded-xl bg-[var(--primary-soft)] px-3 py-2 text-[13px] font-bold text-[var(--primary)]">IA: encontrei {matched.length} sugestão(ões) para “{prompt.trim()}”. Apague a pergunta para ver as 14 sugestões.</p>}
    {hasPrompt && matched.length === 0 && !showAll && <div className="mt-3 rounded-xl bg-[var(--surface)] p-3"><p className="text-sm font-bold">Nenhuma sugestão correspondente a “{prompt.trim()}”.</p><button onClick={() => setShowAll(true)} className="mt-2 rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Mostrar as 14 sugestões</button></div>}
    <div className="mt-3 flex flex-wrap gap-2"><button onClick={() => setShowHidden(v => !v)} className="pill px-3.5 py-2 text-[13px] font-semibold">{showHidden ? "Ocultar ignoradas" : `Ver ignoradas (${hidden.length})`}</button></div>
    <div className="mt-4 grid gap-3 lg:grid-cols-2">{visible.map(s => <article key={s.id} className="soft p-4"><div className="flex flex-wrap items-center justify-between gap-2"><span className="rounded-full bg-[var(--primary)] px-2.5 py-1 text-[11px] font-bold text-white">{s.n} / 14</span>{applied.has(s.id) && <span className="rounded-full bg-[var(--primary-soft)] px-2.5 py-1 text-[11px] font-bold text-[var(--primary)]">✓ Aplicada</span>}</div><h4 className="mt-2 text-[15px] font-extrabold leading-snug">{s.title}</h4><p className="mt-1 text-sm leading-6"><strong>Motivo / dado:</strong> {s.reason}</p><p className="mt-1 text-sm leading-6"><strong>Impacto estimado:</strong> {s.impact}</p>{renderDetail(s)}<div className="mt-3 flex flex-wrap gap-2"><button onClick={() => applyItem(s)} disabled={s.id === "gestor-simulacao" && savingSim} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white disabled:opacity-50">{s.id === "gestor-simulacao" ? (savingSim ? "Salvando…" : "Salvar simulação") : s.applyLabel}</button><button onClick={() => ignoreItem(s)} className="pill px-4 py-2 text-[13px] font-bold">Ignorar</button></div></article>)}</div>
    {visible.length === 0 && <p className="mt-4 text-sm text-[var(--muted)]">Nenhuma sugestão com esses filtros. Reabra uma sugestão ignorada abaixo.</p>}
    {showHidden && hidden.length > 0 && <div className="mt-5"><h4 className="font-extrabold">Ignoradas ({hidden.length})</h4><div className="mt-2 space-y-2">{hidden.map(s => <div key={s.id} className="soft flex flex-wrap items-center justify-between gap-2 p-3"><span className="text-sm"><strong>{s.n}. {s.title}</strong> · Ignorada</span><button onClick={() => reopen(s)} className="pill px-3 py-1.5 text-xs font-bold">Reabrir</button></div>)}</div></div>}
  </div>;
}
function AiMode({ suggestions, alerts, onViewAlerts, onOpenSector, onNotice, sectorId }: { suggestions: AiSuggestion[]; alerts: AlertItem[]; onViewAlerts: () => void; onOpenSector: (id: string) => void; onNotice: (msg: string) => void; sectorId?: string }) {
  const [prompt, setPrompt] = useState("");
  const [answer, setAnswer] = useState<AiAnswer | null>(null);
  const [asked, setAsked] = useState("");
  const [hint, setHint] = useState("");
  function submit() {
    const value = prompt.trim();
    if (!value) { setHint("Escreva o problema antes de pedir a sugestão — por exemplo, um equipamento, um setor ou um sintoma."); return; }
    setHint(""); setAsked(value); setAnswer(buildAiAnswer(value, alerts));
  }
  return <section aria-label="IA" className="card mt-4 w-full overflow-hidden p-4 text-left sm:p-5">
    <div className="flex flex-wrap items-start justify-between gap-3"><div className="flex items-start gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[var(--primary)] text-white"><Sparkles size={19} /></span><div><h2 className="text-[16px] font-extrabold leading-tight">IA</h2></div></div><span className="flex items-center gap-1.5 rounded-full bg-[var(--primary-soft)] px-2.5 py-1 text-[11px] font-bold text-[var(--primary)]"><span className="h-1.5 w-1.5 rounded-full bg-[#177E4B]" />Pronto</span></div>
    <textarea id="ai-problem" value={prompt} onChange={(e) => { setPrompt(e.target.value); if (hint) setHint(""); }} placeholder="Descreva o problema..." rows={4} className="mt-4 w-full resize-y rounded-2xl border border-[var(--line)] bg-[var(--surface)] px-4 py-3 text-[15px] leading-6 outline-none focus:border-[var(--primary)] placeholder:text-[var(--muted-2)]" />
    {hint && <p role="alert" className="mt-2 text-[13px] font-semibold text-[var(--danger)]">{hint}</p>}
    {sectorId === "laboratorio" && <PrevisoesIALaboratorioPanel prompt={prompt} onNotice={onNotice} />}
    {sectorId === "laboratorio" && <SugestoesGestorLaboratorioPanel prompt={prompt} onNotice={onNotice} />}
    <div className="mt-4 flex flex-wrap gap-2"><button onClick={submit} className="rounded-full bg-[var(--primary)] px-5 py-2.5 text-[13px] font-bold text-white">Enviar</button></div>
    {answer && <div className="soft mt-5 p-4 sm:p-5"><p className="text-[12px] font-bold uppercase tracking-wide text-[var(--muted)]">Resposta para: “{asked}”</p><h3 className="mt-3 text-[16px] font-extrabold leading-snug">Diagnóstico provável</h3><p className="mt-1 text-[14px] leading-6">{answer.diagnosis}</p><h3 className="mt-4 text-[16px] font-extrabold leading-snug">Sugestão de solução</h3><ol className="mt-2 list-decimal space-y-2 pl-5 text-[14px] leading-6">{answer.steps.map((step, i) => <li key={i}>{step}</li>)}</ol><h3 className="mt-4 text-[16px] font-extrabold leading-snug">Impacto esperado</h3><p className="mt-1 text-[14px] leading-6">{answer.impact}</p><div className="mt-4 flex flex-wrap gap-2"><button onClick={() => onNotice(`Chamado criado com a solução sugerida para ${answer.sectorName}. A equipe foi notificada.`)} className="rounded-full bg-[var(--primary)] px-4 py-2.5 text-[13px] font-bold text-white">Abrir chamado com essa solução</button><button onClick={() => onOpenSector(answer.sectorId)} className="pill px-4 py-2.5 text-[13px] font-bold">Ver setor relacionado</button><button onClick={() => { setAnswer(null); setAsked(""); }} className="pill px-4 py-2.5 text-[13px] font-bold">Fazer outra pergunta</button></div></div>}
  </section>;
}
function SectorSearchResults({ mode, onOpen, sectorAi, onAiSuggestion }: { mode: { type: "all" } | { type: "single"; id: string }; onOpen: (id: string) => void; sectorAi: AiSuggestion[]; onAiSuggestion: (s: AiSuggestion) => void }) {
  if (mode.type === "all") {
    const atencao = SECTORS.filter((s) => SECTOR_DETAILS[s.id]?.status === "Atenção").length;
    const critico = SECTORS.filter((s) => SECTOR_DETAILS[s.id]?.status === "Crítico").length;
    return <div><div className="card mt-4 flex items-start gap-3 p-4 sm:p-5"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]"><Sparkles size={19} /></span><div><h2 className="text-[17px] font-extrabold leading-snug">Setores contratados pela sua instituição</h2><p className="mt-1 text-[15px] leading-6">Estes são os setores contratados pela instituição de Mariana Ribeiro. Você tem 2 setores{atencao ? `, ${atencao} com atenção` : ""}{critico ? ` e ${critico} em estado crítico` : ""}. Comece pelo setor com atenção e depois revise o outro setor.</p></div></div><p className="mt-5 text-sm font-bold">Setores contratados pela sua instituição · 2 setores</p><div className="mt-3 grid gap-3 sm:grid-cols-2">{SECTORS.map((s) => { const d = SECTOR_DETAILS[s.id]; return <article key={s.id} className="card flex flex-col p-4"><div className="flex items-start justify-between gap-2"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]">{sectorIcon(s.id)}</span><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${d.status === "Crítico" ? "bg-[#F8DEDC] text-[#8B2626]" : d.status === "Atenção" ? "bg-[#FFF0C5] text-[#7A5600]" : "bg-[var(--primary-soft)] text-[var(--primary)]"}`}>{d.status}</span></div><h3 className="mt-3 text-[17px] font-extrabold leading-snug">{s.name}</h3><p className="mt-1 text-[13px] leading-5 text-[var(--muted)]">{s.desc}</p>{(() => { const get = (label: string) => d.general.find((g) => g.label === label)?.value || "—"; const metrics: [string, string][] = [["Chamados abertos", get("Chamados abertos")], ["SLA no prazo", get("SLA no prazo")], ["Alertas ativos", get("Alertas ativos (críticos)")]]; return <div className="mt-3 grid grid-cols-3 gap-2">{metrics.map(([label, value]) => <div key={label} className="soft p-2.5"><p className="text-[11px] leading-4 text-[var(--muted)]">{label}</p><p className="mt-1 text-[14px] font-extrabold leading-tight">{value}</p></div>)}</div>; })()}<button onClick={() => onOpen(s.id)} className="mt-4 inline-flex w-fit items-center gap-1.5 rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Abrir setor <ArrowUpRight size={15} /></button></article>; })}</div></div>;
  }
  const s = SECTORS.find((x) => x.id === mode.id)!; const d = SECTOR_DETAILS[mode.id];
  return <div><article className="card mt-4 flex flex-col gap-4 p-4 sm:flex-row sm:items-center sm:p-5"><div className="flex flex-1 items-start gap-3"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]">{sectorIcon(s.id)}</span><div><p className="text-[12px] font-bold uppercase tracking-wide text-[var(--muted)]">Setor · {d.status}</p><h2 className="mt-1 text-[20px] font-extrabold leading-tight">{s.name}</h2><p className="mt-1 text-sm leading-5 text-[var(--muted)]">{s.desc}</p></div></div><button onClick={() => onOpen(s.id)} className="inline-flex w-fit shrink-0 items-center gap-1.5 rounded-full bg-[var(--primary)] px-4 py-2.5 text-sm font-bold text-white">Abrir setor <ArrowUpRight size={16} /></button></article><h3 className="mt-6 text-[17px] font-extrabold">Métricas gerais do setor</h3><div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{d.general.map((m) => <div key={m.label} className="card p-4"><p className="text-[12px] font-bold uppercase tracking-wide text-[var(--muted)]">{m.label}</p><p className="kpi-num mt-2">{m.value}</p><p className="mt-2 text-[13px] leading-5 text-[var(--muted)]">{m.note}</p></div>)}</div><p className="mt-5 text-sm text-[var(--muted)]">Use a IA acima para descrever um problema deste setor e receber uma sugestão de solução.</p></div>;
}

function ProfileMenu({ onNotice, historySaving, onSaveProfile, onSearchQuery }: any) {
  const [open, setOpen] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const [saving, setSaving] = useState(false);
  const ref = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    if (!open) return;
    function onDown(e: MouseEvent) { if (ref.current && !ref.current.contains(e.target as Node)) { setOpen(false); } }
    function onKey(e: KeyboardEvent) { if (e.key === "Escape") setOpen(false); }
    document.addEventListener("mousedown", onDown);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("mousedown", onDown); document.removeEventListener("keydown", onKey); };
  }, [open]);
  async function toggleHistory() { setSaving(true); await onSaveProfile({ historySaving: !historySaving }); setSaving(false); }
  return <div ref={ref} className="relative shrink-0">
    <button onClick={() => setOpen((v) => !v)} className="grid h-10 w-10 place-items-center rounded-full text-[13px] font-extrabold text-white shadow-sm" style={{ background: "#C07A8A" }} aria-label="Conta de Mariana Ribeiro — abrir menu" aria-expanded={open} aria-haspopup="menu" title="Mariana Ribeiro">MR</button>
    {open && <div role="menu" aria-label="Menu da conta de Mariana Ribeiro" className="card absolute right-0 top-[calc(100%+10px)] z-[70] max-h-[calc(100vh-var(--safe-area-inset-top)-24px)] w-[min(92vw,400px)] overflow-y-auto p-3 shadow-[var(--shadow)]">
      <div className="flex items-center justify-between px-1 pb-1"><span className="text-[12px] font-bold uppercase tracking-wide text-[var(--muted)]">Conta GottCured</span><button onClick={() => setOpen(false)} className="grid h-8 w-8 place-items-center rounded-full border border-[var(--line)] bg-[var(--surface)]" aria-label="Fechar menu da conta"><X size={16} /></button></div>
      <div className="rounded-2xl p-2">
        <div className="flex items-start gap-3">
          <div className="relative shrink-0">
            <span className="grid h-16 w-16 place-items-center rounded-full text-[19px] font-extrabold text-white" style={{ background: "#C07A8A" }}>MR</span>
            <button onClick={() => onNotice("Edição da foto de perfil ainda não está disponível nesta demonstração.")} className="absolute -bottom-1 -right-1 grid h-6 w-6 place-items-center rounded-full border border-[var(--line)] bg-[var(--surface)] text-[var(--ink)]" aria-label="Editar foto do perfil"><Pencil size={11} /></button>
          </div>
          <div className="min-w-0 flex-1 pt-1">
            <p className="truncate text-[17px] font-extrabold leading-tight">Mariana Ribeiro</p>
            <p className="break-all text-[13px] leading-5 text-[var(--muted)]">mariana.ribeiro@gottcured.com.br</p>
          </div>
          <button onClick={() => setExpanded((v) => !v)} className="grid h-8 w-8 shrink-0 place-items-center rounded-full border border-[var(--line)]" aria-label={expanded ? "Recolher informações do usuário" : "Expandir informações do usuário"} aria-expanded={expanded}>{expanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}</button>
        </div>
        {expanded && <div className="mt-3 rounded-2xl border border-[var(--line)] bg-[var(--surface-3)] p-3">
          <dl className="space-y-2 text-[13px] leading-5"><div className="flex justify-between gap-3"><dt className="shrink-0 text-[var(--muted)]">Cargo</dt><dd className="text-right font-bold">Gestora da Clínica e do Laboratório</dd></div></dl>
        </div>}
      </div>
      <button onClick={() => { setOpen(false); onNotice("Gerenciamento da Conta GottCured: nome, e-mail e preferências da conta de Mariana Ribeiro."); }} className="mt-1 flex w-full items-center justify-center gap-2 rounded-full border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-[13px] font-bold"><span className="grid h-5 w-5 place-items-center rounded-full bg-[var(--primary)] text-[12px] font-extrabold text-white">G</span>Gerenciar sua Conta GottCured</button>
      <button onClick={() => { setOpen(false); onNotice("Planos da IA GottCured: compare os planos disponíveis para a sua equipe."); }} className="mt-3 flex w-full items-center gap-2 rounded-full border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-left text-[13px] font-bold"><Sparkles size={16} className="text-[var(--primary)]" />Assine um plano da IA</button>
      <div className="mt-4 px-1">
        <div className="flex items-center justify-between gap-2"><p className="flex items-center gap-2 text-[13px] font-extrabold"><History size={15} />Histórico de pesquisa</p><button onClick={toggleHistory} disabled={saving} role="switch" aria-checked={historySaving !== false} aria-label="Salvar histórico de pesquisa" className="flex shrink-0 items-center gap-2 disabled:opacity-50"><span className="text-[11px] font-bold text-[var(--primary)]">{historySaving === false ? "Pausado" : "Salvando"}</span><span className={`relative h-6 w-11 rounded-full transition-colors ${historySaving === false ? "bg-[var(--surface-2)]" : "bg-[var(--primary)]"}`}><span className={`absolute top-0.5 h-5 w-5 rounded-full bg-white shadow transition-all ${historySaving === false ? "left-0.5" : "left-[22px]"}`} /></span></button></div>
      </div>
    </div>}
  </div>;
}

