const FIN_ORCAMENTO = [{ categoria: "Receita", previsto: 652000, realizado: 688300 }, { categoria: "Pessoal", previsto: 126000, realizado: 118800 }, { categoria: "Insumos", previsto: 28400, realizado: 25740 }, { categoria: "Equipamentos", previsto: 21200, realizado: 17820 }];
const FIN_INVESTIMENTOS = [
  { nome: "Ultrassom U-02", tipo: "Equipamento", investido: 184000, depreciacao: 73600 },
  { nome: "Reforma das salas da Clínica", tipo: "Reforma", investido: 245000, depreciacao: 49000 },
  { nome: "Sistema de gestão e tecnologia", tipo: "Tecnologia", investido: 96000, depreciacao: 38400 },
  { nome: "Monitor da Clínica M-09", tipo: "Equipamento", investido: 42800, depreciacao: 21400 },
  { nome: "Eletrocardiógrafo E-03", tipo: "Equipamento", investido: 36500, depreciacao: 18250 },
];
const FIN_EQUIP_PARADO = [
  { nome: "Ultrassom U-02", horas: 18, custoHora: 420, canceladas: 12, remarcadas: 8 },
  { nome: "Sala 4 — Clínica", horas: 12, custoHora: 260, canceladas: 6, remarcadas: 7 },
  { nome: "Monitor da Clínica M-09", horas: 9, custoHora: 180, canceladas: 3, remarcadas: 5 },
  { nome: "Eletrocardiógrafo E-03", horas: 6, custoHora: 150, canceladas: 2, remarcadas: 3 },
];
const FIN_PREVISTO_REALIZADO = [{ m: "Jan", previsto: 612, realizado: 598 }, { m: "Fev", previsto: 624, realizado: 631 }, { m: "Mar", previsto: 640, realizado: 652 }, { m: "Abr", previsto: 648, realizado: 641 }, { m: "Mai", previsto: 660, realizado: 672 }, { m: "Jun", previsto: 652, realizado: 688 }];

function FinancasClinicaModule({ onNotice }: { onNotice: (m: string) => void }) {
  const [tab, setTab] = useState("Receita");
  const [glosas, setGlosas] = useState<GlosaItem[]>(SEED_GLOSAS);
  const [pacotes, setPacotes] = useState<PacoteItem[]>(SEED_PACOTES);
  const [contas] = useState<ContaItem[]>(SEED_CONTAS);
  const [payAmt, setPayAmt] = useState<Record<string, string>>({});
  const [cobradas, setCobradas] = useState<Record<string, string>>({});
  const [recordIds, setRecordIds] = useState<Record<string, string>>({});
  const [savingId, setSavingId] = useState<string | null>(null);
  const tabs = ["Receita", "Custo e Margem", "Convênios e Glosas", "Pacotes e Receber", "Prevista e Perdida", "Orçamento e Patrimônio", "ROI e Equip. parado"];
  useEffect(() => { let alive = true; (async () => { try {
    const [g, p, c] = await Promise.all([api("records.list", { collection: "gottcured_financas_glosas" }), api("records.list", { collection: "gottcured_financas_pacotes" }), api("records.list", { collection: "gottcured_financas_cobrancas" })]);
    if (!alive) return;
    const ids: Record<string, string> = {};
    for (const r of (g as any)?.records || []) { const v = r.value || {}; if (v.glosaId && v.status) { setGlosas(prev => prev.map(x => x.id === v.glosaId ? { ...x, status: v.status } : x)); ids[`glosa-${v.glosaId}`] = r.id; } }
    for (const r of (p as any)?.records || []) { const v = r.value || {}; if (v.pacoteId) { setPacotes(prev => prev.map(x => x.id === v.pacoteId ? { ...x, pago: v.pago ?? x.pago, parcelasPagas: v.parcelasPagas ?? x.parcelasPagas, status: v.status ?? x.status } : x)); ids[`pacote-${v.pacoteId}`] = r.id; } }
    for (const r of (c as any)?.records || []) { const v = r.value || {}; if (v.contaId && v.cobradoEm) setCobradas(prev => ({ ...prev, [v.contaId]: v.cobradoEm })); }
    if (Object.keys(ids).length) setRecordIds(prev => ({ ...prev, ...ids }));
  } catch { /* mantém os valores iniciais se a API não estiver disponível */ } })(); return () => { alive = false; }; }, []);
  async function persistItem(collection: string, key: string, value: Record<string, unknown>) {
    const existing = recordIds[key];
    if (existing) { await api("records.replace", { collection, id: existing, value }); return existing; }
    const created: any = await api("records.create", { collection, value, idempotency_key: `gottcured-financas-${key}` });
    if (created?.id) setRecordIds(prev => ({ ...prev, [key]: created.id }));
    return created?.id;
  }
  async function recorrer(glosa: GlosaItem) {
    if (glosa.status === "Em recurso") return;
    setSavingId(glosa.id);
    try { await persistItem("gottcured_financas_glosas", `glosa-${glosa.id}`, { glosaId: glosa.id, status: "Em recurso", updatedAt: new Date().toISOString() }); setGlosas(prev => prev.map(x => x.id === glosa.id ? { ...x, status: "Em recurso" } : x)); onNotice(`Recurso registrado para a glosa de ${money(glosa.valor)} — ${glosa.convenio} (${glosa.motivo}). Status: Em recurso.`); }
    catch { onNotice("Não foi possível salvar o recurso. Tente novamente."); }
    setSavingId(null);
  }
  async function registrarPagamento(p: PacoteItem) {
    const saldo = p.total - p.pago; if (saldo <= 0) { onNotice("Este pacote já está quitado."); return; }
    const parcela = Math.round(p.total / p.parcelas);
    const valor = payAmt[p.id] ? Number(payAmt[p.id]) : parcela;
    if (!valor || valor <= 0) { onNotice("Informe um valor de pagamento maior que zero."); return; }
    if (valor > saldo) { onNotice(`O valor não pode ser maior que o saldo de ${money(saldo)}.`); return; }
    const novoPago = p.pago + valor; const novasParcelas = Math.min(p.parcelas, p.parcelasPagas + (valor >= parcela ? 1 : 0)); const novoStatus: PacoteItem["status"] = novoPago >= p.total ? "Quitado" : p.status;
    setSavingId(p.id);
    try { await persistItem("gottcured_financas_pacotes", `pacote-${p.id}`, { pacoteId: p.id, pago: novoPago, parcelasPagas: novasParcelas, status: novoStatus, updatedAt: new Date().toISOString() }); setPacotes(prev => prev.map(x => x.id === p.id ? { ...x, pago: novoPago, parcelasPagas: novasParcelas, status: novoStatus } : x)); setPayAmt(prev => ({ ...prev, [p.id]: "" })); onNotice(`Pagamento de ${money(valor)} registrado — ${p.nome} (${p.paciente}). Novo saldo: ${money(p.total - novoPago)}.`); }
    catch { onNotice("Não foi possível salvar o pagamento. Tente novamente."); }
    setSavingId(null);
  }
  async function cobrar(conta: ContaItem) {
    setSavingId(conta.id);
    try { const agora = new Date().toLocaleString("pt-BR"); await api("records.create", { collection: "gottcured_financas_cobrancas", value: { contaId: conta.id, cobradoEm: agora, canal: "WhatsApp" }, idempotency_key: `gottcured-financas-cobranca-${conta.id}-${Date.now()}` }); setCobradas(prev => ({ ...prev, [conta.id]: agora })); onNotice(`Cobrança simulada por WhatsApp para ${conta.paciente} — ${money(conta.valor)}, vencimento ${fmtDate(conta.vencimento)}. Nenhuma mensagem foi enviada para fora do app.`); }
    catch { onNotice("Não foi possível registrar a cobrança. Tente novamente."); }
    setSavingId(null);
  }
  const receitaTotal = FIN_RECEITA_ESPECIALIDADE.reduce((s, x) => s + x.receita, 0);
  const custoTotal = FIN_CUSTO_DETALHE.reduce((s, x) => s + x.valor, 0);
  const lucroTotal = receitaTotal - custoTotal;
  const consultasMes = 6240; const pacientesUnicos = 4180;
  const ticketConsulta = receitaTotal / consultasMes; const ticketPaciente = receitaTotal / pacientesUnicos;
  const margem = (r: number, c: number) => ({ valor: r - c, pct: ((r - c) / r) * 100 });
  const rankingProc = [...FIN_RECEITA_PROCEDIMENTO].map(x => ({ ...x, ...margem(x.receita, x.custo) })).sort((a, b) => b.valor - a.valor);
  const rankingEsp = [...FIN_RECEITA_ESPECIALIDADE].map(x => ({ ...x, ...margem(x.receita, x.custo) })).sort((a, b) => b.valor - a.valor);
  const totalFaturado = FIN_FATURAMENTO.reduce((s, x) => s + x.faturado, 0); const totalGlosado = FIN_FATURAMENTO.reduce((s, x) => s + x.glosado, 0);
  const totalPacotes = pacotes.reduce((s, x) => s + x.total, 0); const totalPagoPacotes = pacotes.reduce((s, x) => s + x.pago, 0);
  const totalContas = contas.reduce((s, x) => s + x.valor, 0); const totalVencidas = contas.filter(x => x.status === "Vencida").reduce((s, x) => s + x.valor, 0);
  const vencidas30 = contas.filter(x => (x.diasVencida || 0) > 30);
  const taxaInadimplencia = (totalVencidas / totalContas) * 100;
  const receitaPrevista = 739800; const previstaAgenda = 655600; const previstaTratamentos = 84200;
  const perdaFaltas = 22400; const perdaCancel = 15600; const perdaOcioso = 19800; const perdaTotal = perdaFaltas + perdaCancel + perdaOcioso;
  const investidoTotal = FIN_INVESTIMENTOS.reduce((s, x) => s + x.investido, 0); const deprTotal = FIN_INVESTIMENTOS.reduce((s, x) => s + x.depreciacao, 0); const patrimonio = investidoTotal - deprTotal;
  const custoParadoTotal = FIN_EQUIP_PARADO.reduce((s, x) => s + x.horas * x.custoHora, 0);
  const inputCls = "w-full rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2 text-sm outline-none";
  const statusPacote = (s: string) => s === "Quitado" ? "bg-[var(--primary-soft)] text-[var(--primary)]" : s === "Atrasado" ? "bg-[#F8DEDC] text-[#8B2626]" : "bg-[#FFF0C5] text-[#7A5600]";
  return <div>
    <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">{tabs.map(t => <button key={t} onClick={() => setTab(t)} className={`pill shrink-0 px-3.5 py-2 text-[13px] font-semibold ${tab === t ? "chip-active" : ""}`}>{t}</button>)}</div>
    {tab === "Receita" && <div className="mt-4 space-y-4">
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Kpi label="Receita do mês" value={money(receitaTotal)} note="Consultas + procedimentos da Clínica no mês." icon={<DollarSign size={15} />} /><Kpi label="Ticket médio por consulta" value={money(ticketConsulta)} note={`Mês anterior: ${money(104.80)} · +5,2% · ${consultasMes.toLocaleString("pt-BR")} consultas.`} icon={<TrendingUp size={15} />} /><Kpi label="Ticket médio por paciente" value={money(ticketPaciente)} note={`Mês anterior: ${money(158.90)} · +3,6% · ${pacientesUnicos.toLocaleString("pt-BR")} pacientes únicos.`} icon={<Users size={15} />} /><Kpi label="Custo do mês" value={money(custoTotal)} note={`Custo por atendimento: ${money(custoTotal / consultasMes)}.`} icon={<Clock3 size={15} />} /></div>
      <div className="grid gap-4 lg:grid-cols-2"><ChartCard title="Receita por especialidade"><div className="h-[240px]"><ResponsiveContainer><BarChart data={FIN_RECEITA_ESPECIALIDADE}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="nome" tick={{ fill: "var(--muted)", fontSize: 11 }} interval={0} angle={-18} textAnchor="end" height={52} /><YAxis tick={{ fill: "var(--muted)", fontSize: 11 }} tickFormatter={(v: any) => `R$ ${Math.round(v / 1000)}k`} /><Tooltip contentStyle={tipStyle} formatter={(v: any) => [money(Number(v)), "Receita"]} /><Bar dataKey="receita" fill="#0F5F5C" radius={[7, 7, 0, 0]} /></BarChart></ResponsiveContainer></div></ChartCard><ChartCard title="Receita por tipo de pagador"><div className="h-[240px]"><ResponsiveContainer><PieChart><Pie data={FIN_PAGADOR} dataKey="valor" nameKey="nome" innerRadius={56} outerRadius={92} paddingAngle={2}>{FIN_PAGADOR.map((p, i) => <Cell key={p.nome} fill={p.cor} />)}</Pie><Tooltip contentStyle={tipStyle} formatter={(v: any) => [money(Number(v)), "Receita"]} /></PieChart></ResponsiveContainer></div><div className="mt-2 space-y-1.5 text-sm">{FIN_PAGADOR.map(p => <p key={p.nome} className="flex justify-between gap-2"><span><i className="mr-1.5 inline-block h-2 w-2 rounded-full" style={{ background: p.cor }} />{p.nome} · {((p.valor / receitaTotal) * 100).toFixed(1)}%</span><strong>{money(p.valor)}</strong></p>)}</div></ChartCard></div>
      <div className="soft p-4"><h3 className="font-bold">Receita por consulta e por procedimento</h3><div className="mt-3 grid gap-2 sm:grid-cols-2"><div className="rounded-xl bg-[var(--surface)] p-3"><p className="text-[12px] text-[var(--muted)]">Consultas</p><p className="mt-1 text-[20px] font-extrabold">{money(412800)}</p><p className="text-[13px] text-[var(--muted)]">60,0% da receita · {consultasMes.toLocaleString("pt-BR")} consultas</p></div><div className="rounded-xl bg-[var(--surface)] p-3"><p className="text-[12px] text-[var(--muted)]">Procedimentos</p><p className="mt-1 text-[20px] font-extrabold">{money(275500)}</p><p className="text-[13px] text-[var(--muted)]">40,0% da receita · procedimentos da Clínica</p></div></div></div>
      <div className="overflow-x-auto"><table className="w-full min-w-[640px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Profissional</th><th className="py-2 pr-3">Receita</th><th className="py-2 pr-3">Custo</th><th className="py-2">Margem</th></tr></thead><tbody>{FIN_RECEITA_PROFISSIONAL.map(p => { const m = margem(p.receita, p.custo); return <tr key={p.nome} className="border-t border-[var(--line)]"><td className="py-3 pr-3 font-bold">{p.nome}</td><td className="py-3 pr-3">{money(p.receita)}</td><td className="py-3 pr-3">{money(p.custo)}</td><td className={`py-3 font-bold ${m.pct >= 0 ? "text-[var(--ok)]" : "text-[var(--danger)]"}`}>{money(m.valor)} · {m.pct.toFixed(1)}%</td></tr>; })}</tbody></table></div>
    </div>}
    {tab === "Custo e Margem" && <div className="mt-4 space-y-4">
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Kpi label="Custo por atendimento" value={money(custoTotal / consultasMes)} note={`${consultasMes.toLocaleString("pt-BR")} atendimentos no mês.`} icon={<DollarSign size={15} />} /><Kpi label="Margem total" value={money(lucroTotal)} note={`${((lucroTotal / receitaTotal) * 100).toFixed(1)}% sobre a receita do mês.`} icon={<TrendingUp size={15} />} /><Kpi label="Maior margem — valor" value="Clínica Geral" note={`${money(130200)} · 71,4% de margem.`} icon={<TrendingUp size={15} />} /><Kpi label="Menor margem — procedimento" value="Retirada de pontos" note={`${money(2200)} · 26,2% de margem.`} icon={<AlertTriangle size={15} />} /></div>
      <div className="soft p-4"><h3 className="font-bold">Custo por atendimento — detalhado</h3><div className="mt-3 space-y-3">{FIN_CUSTO_DETALHE.map(c => <div key={c.nome}><div className="flex justify-between text-sm"><span className="font-bold">{c.nome} · {c.pct}%</span><span>{money(c.valor)} · {money(c.valor / consultasMes)} por atendimento</span></div><div className="mt-1 h-2.5 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{ width: `${c.pct}%` }} /></div></div>)}</div><p className="mt-3 text-[13px] text-[var(--muted)]">Pessoal inclui equipe assistencial e recepção; estrutura inclui salas, energia e limpeza; insumos inclui material de procedimento; equipamentos inclui depreciação e manutenção.</p></div>
      <div className="overflow-x-auto"><table className="w-full min-w-[640px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Especialidade</th><th className="py-2 pr-3">Receita</th><th className="py-2 pr-3">Custo</th><th className="py-2">Margem</th></tr></thead><tbody>{FIN_RECEITA_ESPECIALIDADE.map(s => { const m = margem(s.receita, s.custo); return <tr key={s.nome} className="border-t border-[var(--line)]"><td className="py-3 pr-3 font-bold">{s.nome}</td><td className="py-3 pr-3">{money(s.receita)}</td><td className="py-3 pr-3">{money(s.custo)}</td><td className={`py-3 font-bold ${m.pct >= 0 ? "text-[var(--ok)]" : "text-[var(--danger)]"}`}>{money(m.valor)} · {m.pct.toFixed(1)}%</td></tr>; })}</tbody></table></div>
      <div className="overflow-x-auto"><table className="w-full min-w-[640px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Procedimento</th><th className="py-2 pr-3">Receita</th><th className="py-2 pr-3">Custo</th><th className="py-2">Margem</th></tr></thead><tbody>{rankingProc.map(p => <tr key={p.nome} className="border-t border-[var(--line)]"><td className="py-3 pr-3 font-bold">{p.nome}</td><td className="py-3 pr-3">{money(p.receita)}</td><td className="py-3 pr-3">{money(p.custo)}</td><td className={`py-3 font-bold ${p.pct >= 0 ? "text-[var(--ok)]" : "text-[var(--danger)]"}`}>{money(p.valor)} · {p.pct.toFixed(1)}%</td></tr>)}</tbody></table></div>
      <div className="grid gap-4 md:grid-cols-2"><div className="soft p-4"><h3 className="font-bold">Maior retorno</h3><ol className="mt-3 space-y-2 text-sm">{rankingProc.slice(0, 3).map((p, i) => <li key={p.nome} className="flex justify-between gap-2"><span><strong>{i + 1}º</strong> {p.nome}</span><strong className="text-[var(--ok)]">{money(p.valor)} · {p.pct.toFixed(1)}%</strong></li>)}{rankingEsp.slice(0, 2).map((s, i) => <li key={s.nome} className="flex justify-between gap-2"><span><strong>{i + 1}º</strong> {s.nome} (especialidade)</span><strong className="text-[var(--ok)]">{money(s.valor)} · {s.pct.toFixed(1)}%</strong></li>)}</ol></div><div className="soft p-4"><h3 className="font-bold">Menor retorno</h3><ol className="mt-3 space-y-2 text-sm">{[...rankingProc].reverse().slice(0, 3).map((p, i) => <li key={p.nome} className="flex justify-between gap-2"><span><strong>{i + 1}º</strong> {p.nome}</span><strong className="text-[var(--danger)]">{money(p.valor)} · {p.pct.toFixed(1)}%</strong></li>)}{[...rankingEsp].reverse().slice(0, 2).map((s, i) => <li key={s.nome} className="flex justify-between gap-2"><span><strong>{i + 1}º</strong> {s.nome} (especialidade)</span><strong className="text-[var(--danger)]">{money(s.valor)} · {s.pct.toFixed(1)}%</strong></li>)}</ol><p className="mt-3 text-[13px] text-[var(--muted)]">Menor retorno não significa prejuízo: todos os itens acima têm margem positiva, mas com menor valor absoluto.</p></div></div>
    </div>}
    {tab === "Convênios e Glosas" && <div className="mt-4 space-y-4">
      <div className="grid gap-3 sm:grid-cols-3"><Kpi label="Faturamento — convênios + SUS" value={money(totalFaturado)} note="Unimed + Amil + Bradesco + SUS." icon={<DollarSign size={15} />} /><Kpi label="Valor glosado" value={money(totalGlosado)} note={`${((totalGlosado / totalFaturado) * 100).toFixed(1)}% do faturado.`} icon={<AlertTriangle size={15} />} /><Kpi label="Faturamento líquido" value={money(totalFaturado - totalGlosado)} note="Faturado menos glosado no mês." icon={<TrendingUp size={15} />} /></div>
      <div className="overflow-x-auto"><table className="w-full min-w-[600px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Convênio</th><th className="py-2 pr-3">Faturado</th><th className="py-2 pr-3">Glosado</th><th className="py-2 pr-3">% glosa</th><th className="py-2">Líquido</th></tr></thead><tbody>{FIN_FATURAMENTO.map(f => <tr key={f.convenio} className="border-t border-[var(--line)]"><td className="py-3 pr-3 font-bold">{f.convenio}</td><td className="py-3 pr-3">{money(f.faturado)}</td><td className="py-3 pr-3 text-[var(--danger)]">{money(f.glosado)}</td><td className="py-3 pr-3">{((f.glosado / f.faturado) * 100).toFixed(1)}%</td><td className="py-3 font-bold">{money(f.faturado - f.glosado)}</td></tr>)}</tbody></table></div>
      <h3 className="font-extrabold">Glosas — principais motivos</h3>
      <div className="flex flex-wrap gap-2 text-[13px]">{[["Documentação", 6070], ["Autorização", 4870], ["Código", 5900]].map(([motivo, valor]) => <span key={motivo as string} className="pill px-3 py-1.5 font-bold">{motivo} · {money(Number(valor))}</span>)}</div>
      <div className="space-y-2">{glosas.map(g => <article key={g.id} className="soft flex flex-wrap items-center justify-between gap-3 p-3"><div><p className="font-bold text-sm">{g.descricao}</p><p className="text-[13px] text-[var(--muted)]">{g.convenio} · Motivo: {g.motivo} · {g.data} · Valor glosado: <strong className="text-[var(--danger)]">{money(g.valor)}</strong></p></div><div className="flex items-center gap-2"><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${g.status === "Em recurso" ? "bg-[#FFF0C5] text-[#7A5600]" : "bg-[#F8DEDC] text-[#8B2626]"}`}>{g.status}</span>{g.status === "Glosada" ? <button disabled={savingId === g.id} onClick={() => recorrer(g)} className="rounded-full bg-[var(--primary)] px-3 py-1.5 text-[12px] font-bold text-white disabled:opacity-50">{savingId === g.id ? "Salvando…" : "Recorrer"}</button> : <span className="text-[12px] font-bold text-[#7A5600]">Em recurso</span>}</div></article>)}</div>
    </div>}
    {tab === "Pacotes e Receber" && <div className="mt-4 space-y-4">
      <div className="grid gap-3 sm:grid-cols-3"><Kpi label="Pacotes e planos — valor total" value={money(totalPacotes)} note={`${pacotes.length} pacotes/planos em acompanhamento.`} icon={<Package size={15} />} /><Kpi label="Valor pago" value={money(totalPagoPacotes)} note={`Saldo a receber: ${money(totalPacotes - totalPagoPacotes)}.`} icon={<DollarSign size={15} />} /><Kpi label="Taxa de inadimplência" value={`${taxaInadimplencia.toFixed(1)}%`} note={`${money(totalVencidas)} vencidos de ${money(totalContas)} a receber.`} icon={<AlertTriangle size={15} />} /></div>
      {vencidas30.length > 0 && <div role="alert" className="rounded-2xl bg-[#F8DEDC] px-4 py-3 text-sm font-bold text-[#8B2626]">Atenção: {vencidas30.length} conta(s) vencida(s) há mais de 30 dias — {vencidas30.map(c => c.paciente).join(", ")} · {money(vencidas30.reduce((s, c) => s + c.valor, 0))}. Priorize a cobrança.</div>}
      <h3 className="font-extrabold">Pacotes e planos de tratamento</h3>
      <div className="space-y-2">{pacotes.map(p => { const saldo = p.total - p.pago; const parcela = Math.round(p.total / p.parcelas); return <article key={p.id} className="soft p-4"><div className="flex flex-wrap justify-between gap-2"><div><p className="font-bold">{p.nome}</p><p className="text-[13px] text-[var(--muted)]">{p.paciente} · {p.parcelasPagas}/{p.parcelas} parcelas pagas · Parcela: {money(parcela)}</p></div><span className={`h-fit rounded-full px-2.5 py-1 text-[11px] font-bold ${statusPacote(p.status)}`}>{p.status}</span></div><div className="mt-3 flex flex-wrap justify-between gap-2 text-sm"><span>Total: <strong>{money(p.total)}</strong></span><span>Pago: <strong className="text-[var(--ok)]">{money(p.pago)}</strong></span><span>Saldo: <strong className={saldo > 0 ? "text-[var(--danger)]" : "text-[var(--ok)]"}>{money(saldo)}</strong></span></div><div className="mt-2 h-2.5 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{ width: `${Math.min(100, (p.pago / p.total) * 100)}%` }} /></div>{saldo > 0 && <div className="mt-3 flex flex-wrap gap-2"><label className="flex items-center gap-2 text-sm font-bold">Valor do pagamento <input type="number" min={1} max={saldo} value={payAmt[p.id] || ""} onChange={e => setPayAmt(prev => ({ ...prev, [p.id]: e.target.value }))} placeholder={String(parcela)} className="w-28 rounded-full border border-[var(--line)] bg-[var(--surface)] px-3 py-1.5 text-sm outline-none" aria-label={`Valor do pagamento — ${p.nome}`} /></label><button disabled={savingId === p.id} onClick={() => registrarPagamento(p)} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white disabled:opacity-50">{savingId === p.id ? "Salvando…" : "Registrar pagamento"}</button></div>}</article>; })}</div>
      <h3 className="font-extrabold">Contas a receber</h3>
      <div className="space-y-2">{contas.map(c => <article key={c.id} className="soft flex flex-wrap items-center justify-between gap-3 p-3"><div><p className="font-bold text-sm">{c.paciente} — {c.descricao}</p><p className="text-[13px] text-[var(--muted)]">Vencimento: {fmtDate(c.vencimento)}{c.diasVencida ? ` · Vencida há ${c.diasVencida} dias` : ""}{cobradas[c.id] ? ` · Cobrança registrada: ${cobradas[c.id]}` : ""}</p></div><div className="flex items-center gap-2"><strong>{money(c.valor)}</strong><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${c.status === "Vencida" ? "bg-[#F8DEDC] text-[#8B2626]" : c.status === "Paga" ? "bg-[var(--primary-soft)] text-[var(--primary)]" : "bg-[#FFF0C5] text-[#7A5600]"}`}>{c.status}</span>{c.status !== "Paga" && <button disabled={savingId === c.id} onClick={() => cobrar(c)} className="rounded-full bg-[#177E4B] px-3 py-1.5 text-[12px] font-bold text-white disabled:opacity-50">{savingId === c.id ? "Salvando…" : "Cobrar (WhatsApp)"}</button>}</div></article>)}</div>
    </div>}
    {tab === "Prevista e Perdida" && <div className="mt-4 space-y-4">
      <div className="grid gap-3 sm:grid-cols-3"><Kpi label="Receita prevista — próximos 30 dias" value={money(receitaPrevista)} note={`Agenda: ${money(previstaAgenda)} + tratamentos em curso: ${money(previstaTratamentos)}.`} icon={<TrendingUp size={15} />} /><Kpi label="Receita perdida — total" value={money(perdaTotal)} note={`${((perdaTotal / receitaTotal) * 100).toFixed(1)}% da receita do mês.`} icon={<AlertTriangle size={15} />} /><Kpi label="Horários ociosos" value={money(perdaOcioso)} note="Horários sem agendamento na agenda da Clínica." icon={<Clock3 size={15} />} /></div>
      <ChartCard title="Previsto vs. realizado (R$ mil)"><div className="h-[240px]"><ResponsiveContainer><LineChart data={FIN_PREVISTO_REALIZADO}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="m" tick={{ fill: "var(--muted)", fontSize: 12 }} /><YAxis tick={{ fill: "var(--muted)", fontSize: 12 }} /><Tooltip contentStyle={tipStyle} formatter={(v: any) => [`R$ ${v} mil`, ""]} /><Line type="monotone" dataKey="previsto" stroke="#8BA9AB" strokeWidth={2.5} name="Previsto" /><Line type="monotone" dataKey="realizado" stroke="#0F5F5C" strokeWidth={2.5} name="Realizado" /></LineChart></ResponsiveContainer></div></ChartCard>
      <div className="grid gap-3 sm:grid-cols-3"><div className="soft p-4"><p className="text-[12px] text-[var(--muted)]">Perdida por faltas</p><p className="mt-1 text-[22px] font-extrabold text-[var(--danger)]">{money(perdaFaltas)}</p><p className="mt-1 text-[13px] text-[var(--muted)]">182 faltas no mês · sem aviso.</p></div><div className="soft p-4"><p className="text-[12px] text-[var(--muted)]">Perdida por cancelamentos</p><p className="mt-1 text-[22px] font-extrabold text-[var(--danger)]">{money(perdaCancel)}</p><p className="mt-1 text-[13px] text-[var(--muted)]">Cancelamentos no dia / sem reagendamento.</p></div><div className="soft p-4"><p className="text-[12px] text-[var(--muted)]">Perdida por horários ociosos</p><p className="mt-1 text-[22px] font-extrabold text-[var(--danger)]">{money(perdaOcioso)}</p><p className="mt-1 text-[13px] text-[var(--muted)]">Horários vagos na agenda.</p></div></div>
      <h3 className="font-extrabold">Faltas e cancelamentos com valor perdido</h3>
      <div className="space-y-2">{FIN_PERDIDAS.map(f => <article key={f.id} className="soft flex flex-wrap justify-between gap-2 p-3"><div><p className="font-bold text-sm">{f.paciente} · {f.motivo}</p><p className="text-[13px] text-[var(--muted)]">{f.data} · {f.detalhe}</p></div><strong className="text-[var(--danger)]">− {money(f.valor)}</strong></article>)}</div>
      <p className="text-[13px] text-[var(--muted)]">A lista acima mostra os casos mais recentes. O total do mês inclui todos os registros de faltas e cancelamentos.</p>
    </div>}
    {tab === "Orçamento e Patrimônio" && <div className="mt-4 space-y-4">
      <div className="grid gap-3 sm:grid-cols-3"><Kpi label="Total investido" value={money(investidoTotal)} note="Equipamentos + reformas + tecnologia." icon={<Landmark size={15} />} /><Kpi label="Patrimônio (valor atual)" value={money(patrimonio)} note={`Depreciação acumulada: ${money(deprTotal)}.`} icon={<TrendingUp size={15} />} /><Kpi label="Orçamento — receita" value={money(688300)} note={`Previsto: ${money(652000)} · +5,6% acima do previsto.`} icon={<DollarSign size={15} />} /></div>
      <h3 className="font-extrabold">Orçamento — previsto vs. realizado</h3>
      <div className="space-y-3">{FIN_ORCAMENTO.map(o => { const variacao = ((o.realizado - o.previsto) / o.previsto) * 100; const pct = Math.min(100, (o.realizado / Math.max(o.previsto, o.realizado)) * 100); const bom = o.categoria === "Receita" ? variacao >= 0 : variacao <= 0; return <div key={o.categoria} className="soft p-4"><div className="flex flex-wrap justify-between gap-2 text-sm"><span className="font-bold">{o.categoria}</span><span>Previsto: {money(o.previsto)} · Realizado: <strong>{money(o.realizado)}</strong> · Variação: <strong className={bom ? "text-[var(--ok)]" : "text-[var(--danger)]"}>{variacao >= 0 ? "+" : ""}{variacao.toFixed(1)}%</strong></span></div><div className="mt-2 h-2.5 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className={`h-full rounded-full ${bom ? "bg-[var(--ok)]" : "bg-[var(--danger)]"}`} style={{ width: `${pct}%` }} /></div></div>; })}</div>
      <h3 className="font-extrabold">Investimentos e patrimônio</h3>
      <div className="overflow-x-auto"><table className="w-full min-w-[640px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Investimento</th><th className="py-2 pr-3">Tipo</th><th className="py-2 pr-3">Valor investido</th><th className="py-2 pr-3">Depreciação acumulada</th><th className="py-2">Valor atual</th></tr></thead><tbody>{FIN_INVESTIMENTOS.map(inv => <tr key={inv.nome} className="border-t border-[var(--line)]"><td className="py-3 pr-3 font-bold">{inv.nome}</td><td className="py-3 pr-3">{inv.tipo}</td><td className="py-3 pr-3">{money(inv.investido)}</td><td className="py-3 pr-3">{money(inv.depreciacao)}</td><td className="py-3 font-bold">{money(inv.investido - inv.depreciacao)}</td></tr>)}</tbody></table></div>
    </div>}
    {tab === "ROI e Equip. parado" && <div className="mt-4 space-y-4">
      <div className="grid gap-3 sm:grid-cols-2"><div className="card p-4"><p className="text-[12px] font-bold uppercase tracking-wide text-[var(--muted)]">ROI da Clínica (mensal)</p><p className="kpi-num mt-2">81,1%</p><p className="mt-2 text-sm leading-6">Cálculo visível: (Receita {money(receitaTotal)} − Custo {money(custoTotal)}) ÷ Investimento total {money(investidoTotal)} = {money(lucroTotal)} ÷ {money(investidoTotal)} = <strong>81,1%</strong>.</p></div><div className="card p-4"><p className="text-[12px] font-bold uppercase tracking-wide text-[var(--muted)]">ROI dos equipamentos (mensal)</p><p className="kpi-num mt-2">64,8%</p><p className="mt-2 text-sm leading-6">Cálculo visível: (Receita atribuída a equipamentos {money(312400)} − Custo de equipamentos {money(17820)} − Manutenção {money(124000)}) ÷ Investimento em equipamentos {money(263300)} = {money(170580)} ÷ {money(263300)} = <strong>64,8%</strong> — valores do mês, com manutenção e depreciação incluídas no custo.</p></div></div>
      <div className="soft p-4"><h3 className="font-bold">Valor agregado da Clínica ao hospital</h3><div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div className="rounded-xl bg-[var(--surface)] p-3"><p className="text-[12px] text-[var(--muted)]">Receita gerada</p><p className="mt-1 text-[20px] font-extrabold">{money(receitaTotal)}</p></div><div className="rounded-xl bg-[var(--surface)] p-3"><p className="text-[12px] text-[var(--muted)]">Encaminhamentos gerados</p><p className="mt-1 text-[20px] font-extrabold">342</p><p className="text-[13px] text-[var(--muted)]">Para especialidades e serviços do hospital.</p></div><div className="rounded-xl bg-[var(--surface)] p-3"><p className="text-[12px] text-[var(--muted)]">Exames solicitados — Laboratório</p><p className="mt-1 text-[20px] font-extrabold">1.842</p><p className="text-[13px] text-[var(--muted)]">Pedidos da Clínica para o Laboratório.</p></div><div className="rounded-xl bg-[var(--surface)] p-3"><p className="text-[12px] text-[var(--muted)]">Procedimentos solicitados</p><p className="mt-1 text-[20px] font-extrabold">486</p><p className="text-[13px] text-[var(--muted)]">Procedimentos gerados pela Clínica.</p></div></div></div>
      <div className="grid gap-3 sm:grid-cols-3"><Kpi label="Custo total — equipamento parado" value={money(custoParadoTotal)} note={`${FIN_EQUIP_PARADO.reduce((s, x) => s + x.horas, 0)} h paradas no mês.`} icon={<Wrench size={15} />} /><Kpi label="Consultas canceladas" value={String(FIN_EQUIP_PARADO.reduce((s, x) => s + x.canceladas, 0))} note="Canceladas por equipamento parado." icon={<AlertTriangle size={15} />} /><Kpi label="Consultas remarcadas" value={String(FIN_EQUIP_PARADO.reduce((s, x) => s + x.remarcadas, 0))} note="Remarcadas por equipamento parado." icon={<CalendarClock size={15} />} /></div>
      <h3 className="font-extrabold">Custo de equipamento parado</h3>
      <div className="overflow-x-auto"><table className="w-full min-w-[640px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Equipamento</th><th className="py-2 pr-3">Horas paradas</th><th className="py-2 pr-3">Custo / hora</th><th className="py-2 pr-3">Custo total</th><th className="py-2">Impacto nas consultas</th></tr></thead><tbody>{FIN_EQUIP_PARADO.map(e => <tr key={e.nome} className="border-t border-[var(--line)]"><td className="py-3 pr-3 font-bold">{e.nome}</td><td className="py-3 pr-3">{e.horas} h</td><td className="py-3 pr-3">{money(e.custoHora)}</td><td className="py-3 pr-3 font-bold text-[var(--danger)]">{money(e.horas * e.custoHora)}</td><td className="py-3">{e.canceladas} canceladas · {e.remarcadas} remarcadas</td></tr>)}</tbody></table></div>
    </div>}
  </div>;
}

