  const priorityShare: Record<string, number> = { "Rotina": 0.58, "Prioritário": 0.22, "Urgente": 0.15, "Emergência": 0.05 };
  const scale = (periodTotals[periodo] / 1284) * (area === "Todas" ? 1 : (areaShare[area] || 0.1)) * (prioridade === "Todas" ? 1 : (priorityShare[prioridade] || 0.2));
