  const areasVolume = [{ area: "Hematologia", value: 362 }, { area: "Bioquímica", value: 298 }, { area: "Hormonal", value: 142 }, { area: "Imunologia", value: 118 }, { area: "Microbiologia", value: 96 }, { area: "Urinálise", value: 128 }, { area: "Parasitologia", value: 64 }, { area: "Imagem", value: 76 }].filter(a => area === "Todas" || a.area === area).map(a => ({ ...a, value: Math.max(1, Math.round(a.value * scale)) }));
  const perHour = [{ h: "7h", v: 68 }, { h: "8h", v: 112 }, { h: "9h", v: 158 }, { h: "10h", v: 182 }, { h: "11h", v: 164 }, { h: "12h", v: 138 }, { h: "13h", v: 124 }, { h: "14h", v: 148 }, { h: "15h", v: 132 }, { h: "16h", v: 96 }, { h: "17h", v: 74 }, { h: "18h", v: 58 }, { h: "19h", v: 42 }].map(x => ({ ...x, v: Math.max(1, Math.round(x.v * scale)) }));
