  async function prioritize(q: QueueItem) { if (prioritized.has(q.id)) { onNotice(`${q.numero} já está priorizado no topo da fila.`); return; } setSavingAction(q.id); const next = new Set(prioritized); next.add(q.id); setPrioritized(next); await persistTempo("priorizado", { queueId: q.id, numero: q.numero, exam: q.exam, patient: q.patient }, `gottcured-tempo-priorizado-${q.id}`); setSavingAction(""); onNotice(`${q.numero} priorizado — ${q.exam} de ${q.patient} subiu para o topo da fila.`); }
