  async function upsert(collection: string, entity: any) { try { if (entity.recordId) await api("records.replace", { collection, id: entity.recordId, value: { ...entity, recordId: undefined } }); else { const c: any = await api("records.create", { collection, value: { ...entity, recordId: undefined }, idempotency_key: `${collection}-${entity.id}` }); return c?.id; } } catch { } return entity.recordId; }
  useEffect(() => { let alive = true; (async () => { try { const d: any = await api("records.list", { collection: "gottcured_lab_insumos_reagentes" }); if (alive && d?.records?.length) setReagentes(prev => { const m = new Map(prev.map(x => [x.id, x])); for (const r of d.records) if (r.value?.id) m.set(r.value.id, { ...r.value, recordId: r.id }); return Array.from(m.values()); }); } catch { } try { const d: any = await api("records.list", { collection: "gottcured_lab_insumos_lotes" }); if (alive && d?.records?.length) setLotes(prev => { const m = new Map(prev.map(x => [x.id, x])); for (const r of d.records) if (r.value?.id) m.set(r.value.id, { ...r.value, recordId: r.id }); return Array.from(m.values()); }); } catch { } try { const d: any = await api("records.list", { collection: "gottcured_lab_insumos_movimentos" }); if (alive && d?.records?.length) setMovs(prev => { const m = new Map(prev.map(x => [x.id, x])); for (const r of d.records) if (r.value?.id) m.set(r.value.id, { ...r.value, recordId: r.id }); return Array.from(m.values()); }); } catch { } try { const d: any = await api("records.list", { collection: "gottcured_lab_insumos_compras" }); if (alive && d?.records?.length) setCompras(d.records.map((r: any) => ({ ...r.value, recordId: r.id })).filter((x: any) => x.id)); } catch { } })(); return () => { alive = false; }; }, []);
  async function criarReagente() { if (!rgForm.nome.trim() || !rgForm.fabricante.trim() || !rgForm.custoUnit || !rgForm.estoqueMin || !rgForm.pontoReposicao) { onNotice("Preencha reagente, fabricante, custo unitário, estoque mínimo e ponto de reposição."); return; } const r: LabReagente = { id: `rg-${Date.now()}`, nome: rgForm.nome.trim(), fabricante: rgForm.fabricante.trim(), area: rgForm.area, unidade: rgForm.unidade, custoUnit: Number(rgForm.custoUnit), estoqueMin: Number(rgForm.estoqueMin), pontoReposicao: Number(rgForm.pontoReposicao), condicao: rgForm.condicao, teoricoPorExame: Number(rgForm.teorico) || 1 }; setReagentes(p => [r, ...p]); setSaving(true); const rid = await upsert("gottcured_lab_insumos_reagentes", r); if (rid) setReagentes(p => p.map(x => x.id === r.id ? { ...x, recordId: rid } : x)); setSaving(false); setRgForm({ nome: "", fabricante: "", area: "Bioquímica", unidade: "mL", custoUnit: "", estoqueMin: "", pontoReposicao: "", condicao: "2–8°C", teorico: "1" }); onNotice(`Reagente ${r.nome} cadastrado.`); }
