  async function darBaixa() { const lote = lotes.find(l => l.id === saiForm.loteId); const qty = Number(saiForm.qty); if (!lote) { onNotice("Selecione um lote."); return; } if (!saiForm.responsavel.trim()) { onNotice("Baixa bloqueada: informe o responsável."); return; } if (!qty || qty <= 0) { onNotice("Informe uma quantidade maior que zero."); return; } if (lote.bloqueado) { onNotice(`Baixa bloqueada: lote ${lote.codigo} está BLOQUEADO — ${lote.motivoBloqueio}.`); return; } if (daysUntil(lote.validade) < 0) { onNotice(`Baixa bloqueada: lote ${lote.codigo} está vencido.`); return; } if (qty > lote.qty) { onNotice(`Saldo insuficiente no lote ${lote.codigo}: disponível ${lote.qty} ${reag(lote.reagenteId)?.unidade}.`); return; } const paciente = patients.find(p => p.id === saiForm.pacienteId); const mv: LabMov = { id: `mv-${Date.now()}`, tipo: "saida", reagenteId: lote.reagenteId, loteId: lote.id, qty, data: new Date().toLocaleDateString("pt-BR"), exame: saiForm.exame, equipamento: saiForm.equipamento, bancada: saiForm.bancada, pacienteId: saiForm.pacienteId, pacienteNome: paciente?.name || "—", responsavel: saiForm.responsavel.trim(), motivo: "Consumo em exame", valor: Math.round(qty * (reag(lote.reagenteId)?.custoUnit || 0) * 100) / 100 }; const nextLote = { ...lote, qty: lote.qty - qty }; setLotes(p => p.map(x => x.id === lote.id ? nextLote : x)); setMovs(p => [mv, ...p]); setSaving(true); await upsert("gottcured_lab_insumos_lotes", nextLote); await upsert("gottcured_lab_insumos_movimentos", mv); setSaving(false); onNotice(`Baixa registrada: ${qty} ${reag(lote.reagenteId)?.unidade} de ${reag(lote.reagenteId)?.nome} — lote ${lote.codigo} · ${saiForm.exame} · ${saiForm.equipamento} · ${saiForm.bancada}${paciente ? ` · ${paciente.name}` : ""}.`); }
  async function registrarPerda() { const lote = lotes.find(l => l.id === perdaForm.loteId); const qty = Number(perdaForm.qty); if (!lote || !qty || qty <= 0 || qty > lote.qty) { onNotice("Informe lote, quantidade válida e dentro do saldo do lote."); return; } if (!perdaForm.responsavel.trim()) { onNotice("Informe o responsável pela perda/descarte."); return; } const mv: LabMov = { id: `mv-${Date.now()}`, tipo: "perda", reagenteId: lote.reagenteId, loteId: lote.id, qty, data: new Date().toLocaleDateString("pt-BR"), exame: "—", equipamento: "—", bancada: "—", pacienteId: "", pacienteNome: "—", responsavel: perdaForm.responsavel.trim(), motivo: perdaForm.motivo, valor: Math.round(qty * (reag(lote.reagenteId)?.custoUnit || 0) * 100) / 100 }; const nextLote = { ...lote, qty: lote.qty - qty }; setLotes(p => p.map(x => x.id === lote.id ? nextLote : x)); setMovs(p => [mv, ...p]); await upsert("gottcured_lab_insumos_lotes", nextLote); await upsert("gottcured_lab_insumos_movimentos", mv); setPerdaForm({ ...perdaForm, qty: "" }); onNotice(`Perda/descarte registrado: ${qty} ${reag(lote.reagenteId)?.unidade} — ${perdaForm.motivo} — ${money(mv.valor)}.`); }
  async function alternarBloqueio(lote: LabLote) { const next = { ...lote, bloqueado: !lote.bloqueado, motivoBloqueio: !lote.bloqueado ? "Bloqueio manual / Recall — registrado pela equipe" : "" }; setLotes(p => p.map(x => x.id === lote.id ? next : x)); await upsert("gottcured_lab_insumos_lotes", next); onNotice(next.bloqueado ? `Lote ${lote.codigo} BLOQUEADO — baixa desabilitada.` : `Lote ${lote.codigo} desbloqueado.`); }
  async function solicitarCompra(r: LabReagente, qtySugerida?: number) { const qty = qtySugerida || Math.max(r.pontoReposicao * 2 - estoque(r.id), r.pontoReposicao); const c: LabCompra = { id: `cp-${Date.now()}`, reagenteId: r.id, qty, motivo: "Ponto de reposição / estoque mínimo", data: new Date().toLocaleDateString("pt-BR"), status: "Solicitada" }; setCompras(p => [c, ...p]); await upsert("gottcured_lab_insumos_compras", c); onNotice(`Compra solicitada: ${r.nome} — ${qty} ${r.unidade}.`); }
  function registrarTemperatura() { const t = Number(tempForm.temp); if (!tempForm.temp || !tempForm.responsavel.trim()) { onNotice("Informe a temperatura e o responsável."); return; } setTemps(p => ({ ...p, [tempForm.local]: t })); setTempForm({ ...tempForm, temp: "" }); onNotice(`Temperatura registrada: ${tempForm.local} — ${t}°C por ${tempForm.responsavel.trim()}.`); }
