  const diasAteAcabar = (id: string) => { const media = consumoMedioDia(id); return media > 0 ? Math.floor(estoque(id) / media) : null; };
  const alertasEstoque = reagentes.map(r => ({ r, est: estoque(r.id), dias: diasAteAcabar(r.id) })).filter(x => x.est <= x.r.estoqueMin);
