  const semRegistro = INSUMO_EXAMES.filter(e => !movs.some(m => m.exame === e.exame && m.tipo === "saida"));
  const custoPorExame = INSUMO_EXAMES.map(e => { const ms = movs.filter(m => m.exame === e.exame && m.tipo === "saida"); return { exame: e.exame, qty: ms.reduce((s, m) => s + m.qty, 0), custo: ms.reduce((s, m) => s + m.valor, 0), media: ms.length ? ms.reduce((s, m) => s + m.valor, 0) / ms.length : 0, reagente: reag(e.reagenteId)?.nome || "" }; });
