const LAB_INTEL_VOLUME7 = [{ dia: "Hoje", exames: 264 }, { dia: "Amanhã", exames: 312 }, { dia: "Qua", exames: 298 }, { dia: "Qui", exames: 286 }, { dia: "Sex", exames: 304 }, { dia: "Sáb", exames: 198 }, { dia: "Dom", exames: 162 }];
function PrevisoesIALaboratorioPanel({ prompt, onNotice, onOpenPatient }: { prompt: string; onNotice: (m: string) => void; onOpenPatient?: (id: string) => void }) {
  const [ignored, setIgnored] = useState<Set<string>>(new Set());
  const [resolved, setResolved] = useState<Set<string>>(new Set());
  const [done, setDone] = useState<Set<string>>(new Set());
  const [choice, setChoice] = useState<Record<string, string>>({});
  const [showHidden, setShowHidden] = useState(false);
  const [showAll, setShowAll] = useState(false);
  useEffect(() => { setShowAll(false); }, [prompt]);
  const inputCls = "w-full rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-sm outline-none";
  useEffect(() => { let alive = true; (async () => { try { const d: any = await api("records.list", { collection: "gottcured_lab_inteligencia_previsao" }); if (!alive || !d?.records?.length) return; const ig = new Set<string>(); const rs = new Set<string>(); const dn = new Set<string>(); for (const r of d.records || []) { const v = r.value || {}; if (!v.alertId) continue; if (v.status === "ignored") ig.add(v.alertId); if (v.status === "resolved") rs.add(v.alertId); if (v.status === "done") dn.add(v.alertId); } setIgnored(ig); setResolved(rs); setDone(dn); } catch { } })(); return () => { alive = false; }; }, []);
  async function persistIntel(alertId: string, status: string) { try { await api("records.create", { collection: "gottcured_lab_inteligencia_previsao", value: { alertId, status, updatedAt: new Date().toISOString() }, idempotency_key: `gottcured-lab-intel-${alertId}-${status}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}` }); } catch { } }
  const modoIaIds = ["lab-int-volume", "lab-int-pico-1", "lab-int-ruptura", "lab-int-tat", "lab-int-falha", "lab-int-falta-1", "lab-int-pessoal-1", "lab-int-receita", "lab-int-atipico", "lab-int-qualidade", "lab-int-tendencia-1"];
  const modoIaItems = modoIaIds.map(id => LAB_INTEL_ITEMS.find(i => i.id === id)!).filter(Boolean);
  const active = modoIaItems.filter(i => !ignored.has(i.id) && !resolved.has(i.id));
  const hidden = modoIaItems.filter(i => ignored.has(i.id) || resolved.has(i.id));
  const promptNorm = norm(prompt || "");
  const promptTokens = promptNorm.split(/[^a-z0-9]+/).filter(t => t.length >= 3 && !["para", "qual", "como", "quando", "onde", "sera", "tem", "ter", "uma", "uns", "umas", "dos", "das", "com", "que", "pra", "por", "isso", "esta", "esse", "essa", "meu", "minha", "sobre", "ainda", "mais", "muito", "vai", "fazer", "pode", "poder"].includes(t));
  const scored = active.map((item, index) => ({ item, index, score: labIntelScore(item, promptTokens) }));
  const hasPrompt = promptTokens.length > 0;
  const matched = hasPrompt ? scored.filter(s => s.score > 0).sort((a, b) => b.score - a.score || a.index - b.index) : scored;
  const visible = (hasPrompt && matched.length === 0 && showAll ? scored : matched).map(s => s.item);
  const urgentCount = active.filter(i => i.level === "Alto" || i.probability >= 80).length;
  function doPrimary(item: LabIntelItem) { const c = choice[item.id] || item.actionOptions?.[0]; setDone(s => new Set(s).add(item.id)); persistIntel(item.id, "done"); onNotice(item.doneMessage(c)); }
  function doSecondary(item: LabIntelItem) { setDone(s => new Set(s).add(item.id)); persistIntel(item.id, "done"); onNotice(item.secondaryMessage || item.doneMessage()); }
  function ignore(item: LabIntelItem) { setIgnored(s => new Set(s).add(item.id)); persistIntel(item.id, "ignored"); onNotice(`Previsão ignorada: ${item.title}. Ela sai da lista ativa.`); }
  function resolve(item: LabIntelItem) { setResolved(s => new Set(s).add(item.id)); persistIntel(item.id, "resolved"); onNotice(`Previsão marcada como resolvida: ${item.title}.`); }
  function reopen(item: LabIntelItem) { setIgnored(s => { const n = new Set(s); n.delete(item.id); return n; }); setResolved(s => { const n = new Set(s); n.delete(item.id); return n; }); persistIntel(item.id, "open"); onNotice(`Previsão reaberta: ${item.title}.`); }
  return <div className="mt-4 rounded-2xl border border-[var(--line)] bg-[var(--surface-3)] p-4 sm:p-5">
    <div className="flex flex-wrap items-start justify-between gap-2"><div><h3 className="text-[16px] font-extrabold">Previsões da IA — Laboratório</h3><p className="mt-1 text-[13px] leading-5 text-[var(--muted)]">11 previsões dentro do Modo IA. Digite a pergunta na caixa acima para filtrar — ex.: “vai faltar reagente?”, “risco de falha?”, “previsão de volume?”.</p></div><span className="rounded-full bg-[var(--primary-soft)] px-3 py-1.5 text-[12px] font-bold text-[var(--primary)]">{visible.length} de {active.length} previsões · {urgentCount} urgentes</span></div>
    <div className="mt-3 rounded-2xl bg-[#FFF7D6] px-4 py-3 text-sm font-bold text-[#7A5600]">IA — previsões são APOIO. Nenhuma previsão substitui a avaliação do profissional do Laboratório. Confirme amostra, lote e paciente antes de liberar ou bloquear.</div>
    {hasPrompt && matched.length > 0 && <p role="status" className="mt-3 rounded-xl bg-[var(--primary-soft)] px-3 py-2 text-[13px] font-bold text-[var(--primary)]">IA: encontrei {matched.length} previsão(ões) para “{prompt.trim()}”. Apague a pergunta para ver as 11 previsões.</p>}
    {hasPrompt && matched.length === 0 && !showAll && <div className="mt-3 rounded-xl bg-[var(--surface)] p-3"><p className="text-sm font-bold">Nenhuma previsão correspondente a “{prompt.trim()}”.</p><button onClick={() => setShowAll(true)} className="mt-2 rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Mostrar as 11 previsões</button></div>}
    <div className="mt-3 flex flex-wrap gap-2"><button onClick={() => setShowHidden(v => !v)} className="pill px-3.5 py-2 text-[13px] font-semibold">{showHidden ? "Ocultar resolvidas / ignoradas" : `Ver resolvidas / ignoradas (${hidden.length})`}</button></div>
    <div className="mt-4 grid gap-3 lg:grid-cols-2">{visible.map(item => <article key={item.id} className="soft p-4"><div className="flex flex-wrap items-center justify-between gap-2"><span className="rounded-full bg-[var(--primary-soft)] px-2.5 py-1 text-[11px] font-bold text-[var(--primary)]">{item.group}</span><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${item.level === "Alto" ? "bg-[#F8DEDC] text-[#8B2626]" : item.level === "Médio" ? "bg-[#FFF0C5] text-[#7A5600]" : "bg-[var(--primary-soft)] text-[var(--primary)]"}`}>Nível {item.level} · {item.probability}%</span></div><h3 className="mt-2 text-[15px] font-extrabold leading-snug">{item.title}</h3><p className="mt-1 text-sm leading-6 text-[var(--muted)]">{item.detail}</p><p className="mt-1 text-sm leading-6"><strong>Motivo:</strong> {item.reason}</p><div className="mt-2 h-2 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{ width: `${item.probability}%` }} /></div>{item.id === "lab-int-volume" && <div className="mt-3"><p className="text-[13px] font-bold">Próximos 7 dias — exames previstos</p><div className="mt-1 h-[180px]"><ResponsiveContainer><BarChart data={LAB_INTEL_VOLUME7}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="dia" tick={{ fill: "var(--muted)", fontSize: 11 }} /><YAxis tick={{ fill: "var(--muted)", fontSize: 11 }} /><Tooltip contentStyle={{ background: "var(--surface)", border: "1px solid var(--line)", borderRadius: 12 }} formatter={(v: any) => [`${v} exames`, "Volume previsto"]} /><Bar dataKey="exames" fill="#0F5F5C" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer></div><p className="mt-1 text-[13px] text-[var(--muted)]">Sugestão: reforçar a bancada amanhã e na 2ª-feira de manhã, quando o pico se concentra.</p></div>}{done.has(item.id) && <p className="mt-2 text-[13px] font-bold text-[var(--ok)]">✓ Ação feita — revise o resultado antes de considerar o item encerrado.</p>}{item.actionOptions && <label className="mt-3 block text-[12px] font-bold">Ação<select value={choice[item.id] || item.actionOptions[0]} onChange={e => setChoice(p => ({ ...p, [item.id]: e.target.value }))} className="mt-1 w-full rounded-full border border-[var(--line)] bg-[var(--surface)] px-3 py-2 text-[13px]">{item.actionOptions.map(o => <option key={o}>{o}</option>)}</select></label>}<div className="mt-3 flex flex-wrap gap-2"><button onClick={() => doPrimary(item)} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Aplicar sugestão</button>{item.secondaryLabel && <button onClick={() => doSecondary(item)} className="rounded-full bg-[#8B2626] px-4 py-2 text-[13px] font-bold text-white">{item.secondaryLabel}</button>}{item.patientId && onOpenPatient && <button onClick={() => onOpenPatient(item.patientId!)} className="pill px-4 py-2 text-[13px] font-bold">Ver paciente</button>}<button onClick={() => ignore(item)} className="pill px-4 py-2 text-[13px] font-bold">Ignorar</button><button onClick={() => resolve(item)} className="pill px-4 py-2 text-[13px] font-bold">Resolver</button></div></article>)}</div>
    {visible.length === 0 && <p className="mt-4 text-sm text-[var(--muted)]">Nenhuma previsão com esses filtros. Ajuste o filtro ou reabra uma previsão resolvida / ignorada.</p>}
    {showHidden && hidden.length > 0 && <div className="mt-5"><h4 className="font-extrabold">Resolvidas / ignoradas ({hidden.length})</h4><div className="mt-2 space-y-2">{hidden.map(item => <div key={item.id} className="soft flex flex-wrap items-center justify-between gap-2 p-3"><span className="text-sm"><strong>{item.title}</strong> · {ignored.has(item.id) ? "Ignorada" : "Resolvida"}</span><button onClick={() => reopen(item)} className="pill px-3 py-1.5 text-xs font-bold">Reabrir</button></div>)}</div></div>}
  </div>;
}
/* ---------- WHATSAPP E COMUNICAÇÃO — LABORATÓRIO ---------- */
type WaOverride = { status?: string; stage?: string; date?: string; time?: string; cancelMotive?: string; confirmation?: string; called?: boolean; positionNotified?: boolean; reminderSent?: boolean; resultNotified?: boolean; recoletaNotified?: boolean; postSent?: boolean; surveySent?: boolean; rescheduleReason?: string };
type WaConsent = { date: string; channel: string; text: string };
type WaMsg = { at: string; from: "paciente" | "laboratorio" | "sistema"; text: string; kind: string };
type WaSurvey = { patientId: string; patientName: string; nota: number; comentario: string; at: string };
type WaState = { overrides: Record<string, WaOverride>; consents: Record<string, WaConsent>; history: Record<string, WaMsg[]>; surveys: WaSurvey[]; transferred: Record<string, { status: string; atendente: string }>; recoletaDone: Record<string, boolean> };
const WA_DEFAULT_SURVEYS: WaSurvey[] = [
  { patientId: "p1", patientName: "Maria Aparecida Silva", nota: 5, comentario: "Atendimento rápido e explicado.", at: "12/06/2026, 10:20" },
  { patientId: "p5", patientName: "Fernanda Lima Almeida", nota: 4, comentario: "Boa coleta, espera um pouco longa.", at: "12/06/2026, 11:05" },
  { patientId: "p4", patientName: "Carlos Eduardo Oliveira", nota: 5, comentario: "Tudo certo.", at: "11/06/2026, 09:40" },
];
const WA_CONSENT_TEXT = "Autorizo o Laboratório GottCured a me contatar por WhatsApp para agendamento, lembrete de coleta, confirmação de presença, posição na fila, etapas do exame, resultado, recoleta, orientações pós-coleta e pesquisa de satisfação. Posso revogar este consentimento a qualquer momento (LGPD).";
function waPrepFor(exam: string) {
  const e = exam.toLowerCase();
  if (e.includes("glicemia")) return "Jejum de 8 horas. Não ingerir bebida alcoólica 24 h antes. Manter a medicação habitual, salvo orientação médica. Levar documento com foto e carteirinha.";
  if (e.includes("hemoglobina")) return "Jejum não obrigatório. Informar uso de suplementos de ferro. Levar documento com foto e carteirinha.";
  if (e.includes("hemograma")) return "Jejum não obrigatório. Evitar exercício intenso 2 h antes da coleta. Levar documento com foto.";
  if (e.includes("urina") || e.includes("eas") || e.includes("urocultura")) return "Coletar a primeira urina da manhã em frasco estéril, após higiene íntima. Não coletar durante o uso de antibiótico, salvo orientação médica.";
  if (e.includes("colesterol")) return "Jejum de 8 a 12 horas. Evitar bebida alcoólica 24 h antes da coleta.";
  if (e.includes("ultrassom") || e.includes("tomografia") || e.includes("ressonância") || e.includes("raio")) return "Chegar 15 min antes. Seguir o jejum indicado para o exame de imagem. Informar alergia a contraste, possível gestação, marca-passo ou próteses.";
  if (e.includes("tsh") || e.includes("estradiol") || e.includes("vitamina")) return "Jejum não obrigatório. Coletar preferencialmente pela manhã. Informar uso de suplementos e fase do ciclo, quando aplicável.";
  return "Seguir o preparo informado no pedido. Levar documento com foto e carteirinha. Em dúvida, responder a esta conversa.";
}
function waPostFor(exam: string) {
  const e = exam.toLowerCase();
  if (e.includes("urina") || e.includes("eas")) return "Após a coleta de urina: manter higiene íntima, beber água normalmente e observar o curativo, se houver. Procurar o Laboratório se houver febre, dor ao urinar ou sangramento.";
  if (e.includes("ultrassom") || e.includes("tomografia") || e.includes("ressonância") || e.includes("raio")) return "Após o exame de imagem: repouso leve, beber bastante água (principalmente se houve contraste) e observar o local do exame. Procurar atendimento se houver reação, falta de ar ou inchaço.";
  return "Após a coleta de sangue: manter o curativo por 2 horas, não carregar peso com o braço da coleta, beber bastante água e fazer repouso leve. Se o local inchar, sangrar ou doer muito, responder a esta conversa ou procurar o Laboratório.";
}
function WhatsAppLabModule({ patients, onUpdatePatient, onNotice }: { patients: Patient[]; onUpdatePatient: (p: Patient) => Promise<void>; onNotice: (m: string) => void }) {
  const [tab, setTab] = useState("Conversa");
  const [wa, setWa] = useState<WaState>({ overrides: {}, consents: { p1: { date: "2026-06-10", channel: "WhatsApp", text: WA_CONSENT_TEXT }, p5: { date: "2026-06-10", channel: "WhatsApp", text: WA_CONSENT_TEXT }, p4: { date: "2026-06-09", channel: "WhatsApp", text: WA_CONSENT_TEXT } }, history: {}, surveys: WA_DEFAULT_SURVEYS, transferred: {}, recoletaDone: {} });
  const [recordId, setRecordId] = useState<string | null>(null);
  const [loaded, setLoaded] = useState(false);
  const [selectedId, setSelectedId] = useState("");
  const [chatMode, setChatMode] = useState<"none" | "agendar" | "remarcar" | "cancelar">("none");
  const [chatDate, setChatDate] = useState(new Date(Date.now() + 86400000).toISOString().slice(0, 10));
  const [chatTime, setChatTime] = useState("08:00");
  const [cancelMotive, setCancelMotive] = useState("Paciente solicitou");
  const [cancelDetail, setCancelDetail] = useState("");
  const [preview, setPreview] = useState<{ orderId: string; kind: string; text: string; after: string } | null>(null);
  const [consentForm, setConsentForm] = useState<{ patientId: string; date: string; channel: string; text: string } | null>(null);
  const [attendant, setAttendant] = useState("Atendente — Recepção do Laboratório");
  const [surveyDraft, setSurveyDraft] = useState<Record<string, { nota: number; comentario: string }>>({});
  const [recoletaDate, setRecoletaDate] = useState(new Date(Date.now() + 86400000).toISOString().slice(0, 10));
  const [recoletaTime, setRecoletaTime] = useState("08:30");
  const [stageDraft, setStageDraft] = useState<Record<string, string>>({});
  const inputCls = "w-full rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-sm outline-none";
  const labelCls = "block text-sm font-bold";
  const todayStr = new Date().toISOString().slice(0, 10);
  const tomorrowStr = new Date(Date.now() + 86400000).toISOString().slice(0, 10);
  const baseOrders = useMemo(() => {
    const list: { id: string; patientId: string; patientName: string; exam: string; date: string; time: string }[] = [];
    patients.forEach(p => (p.orders || []).filter(o => o.kind === "Exame laboratorial" || o.kind === "Exame de imagem").forEach(o => list.push({ id: o.id, patientId: p.id, patientName: p.name, exam: o.name, date: "", time: "" })));
    if (list.length < 3) patients.slice(0, 5).forEach((p, i) => { if (!list.some(x => x.patientId === p.id)) list.push({ id: `wa-fallback-${p.id}`, patientId: p.id, patientName: p.name, exam: ["Glicemia em jejum", "Hemograma completo", "Colesterol total e frações", "Urina tipo I (EAS)", "TSH"][i % 5], date: "", time: "" }); });
    return list.slice(0, 8).map((o, i) => ({ ...o, date: i < 3 ? tomorrowStr : i < 6 ? todayStr : tomorrowStr, time: ["08:00", "08:30", "09:00", "09:30", "10:00", "10:30", "11:00", "11:30"][i % 8] }));
  }, [patients, todayStr, tomorrowStr]);
  const orders = baseOrders.map(o => { const ov = wa.overrides[o.id] || {}; return { ...o, status: ov.status || "Agendado", stage: ov.stage || "Aguardando coleta", date: ov.date || o.date, time: ov.time || o.time, confirmation: ov.confirmation || "Aguardando confirmação", cancelMotive: ov.cancelMotive || "" }; });
  const selected = orders.find(o => o.id === selectedId) || orders[0];
  useEffect(() => { if (selected && !selectedId) setSelectedId(selected.id); }, [selected, selectedId]);
  async function persistWa(next: WaState) {
    try {
      if (recordId) await api("records.replace", { collection: "gottcured_lab_whatsapp", id: recordId, value: next });
      else { const created: any = await api("records.create", { collection: "gottcured_lab_whatsapp", value: next, idempotency_key: "gottcured-lab-whatsapp-main" }); if (created?.id) setRecordId(created.id); }
    } catch { }
  }
  useEffect(() => { let alive = true; (async () => { try { const d: any = await api("records.list", { collection: "gottcured_lab_whatsapp" }); if (!alive || !d?.records?.length) return; const v = d.records[0].value || {}; setRecordId(d.records[0].id); setWa(prev => ({ overrides: v.overrides || prev.overrides, consents: v.consents || prev.consents, history: v.history || prev.history, surveys: Array.isArray(v.surveys) && v.surveys.length ? v.surveys : prev.surveys, transferred: v.transferred || prev.transferred, recoletaDone: v.recoletaDone || prev.recoletaDone })); } catch { } finally { if (alive) setLoaded(true); } })(); return () => { alive = false; }; }, []);
  function updateWa(mut: (prev: WaState) => WaState) { setWa(prev => { const next = mut(prev); if (loaded) persistWa(next); else persistWa(next); return next; }); }
  function consentFor(patientId: string) { return wa.consents[patientId]; }
  function addHistory(patientId: string, msg: WaMsg) { updateWa(prev => ({ ...prev, history: { ...prev.history, [patientId]: [...(prev.history[patientId] || []), msg].slice(-40) } })); }
  function syncPatient(order: { patientId: string; patientName: string }, label: string) { const p = patients.find(x => x.id === order.patientId); if (!p) return; const today = new Date().toLocaleDateString("pt-BR"); onUpdatePatient({ ...p, history: [{ date: today, type: "WhatsApp — Laboratório", professional: "Laboratório — WhatsApp", result: label, detail: label }, ...p.history], timeline: [{ date: today, type: "WhatsApp — Laboratório", title: label, detail: `Paciente: ${order.patientName}` }, ...p.timeline] }); }
  function sendWa(order: { id: string; patientId: string; patientName: string }, kind: string, text: string) {
    if (!consentFor(order.patientId)) { onNotice(`Envio bloqueado: ${order.patientName} está “Sem consentimento”. Registre o consentimento antes de enviar.`); return false; }
    addHistory(order.patientId, { at: new Date().toLocaleString("pt-BR"), from: "laboratorio", text, kind });
    onNotice(`Mensagem enviada por WhatsApp para ${order.patientName} (simulação).`);
    return true;
  }
  function applyOrder(order: { id: string; patientId: string; patientName: string; exam: string }, patch: WaOverride, label: string, note: string) {
    updateWa(prev => ({ ...prev, overrides: { ...prev.overrides, [order.id]: { ...prev.overrides[order.id], ...patch } } }));
    syncPatient(order, label); onNotice(note);
  }
  const chatMsgs: WaMsg[] = selected ? (wa.history[selected.patientId] || [
    { at: "Hoje, 08:02", from: "paciente", text: "Quero agendar coleta", kind: "agendamento" },
    { at: "Hoje, 08:02", from: "laboratorio", text: `Olá, ${selected.patientName}! Temos coleta amanhã às 08:00, 08:30 e 09:00 para ${selected.exam}. Qual horário você prefere?`, kind: "agendamento" },
  ]) : [];
  const tomorrowOrders = orders.filter(o => o.date === tomorrowStr && o.status !== "Cancelado");
  const todayQueue = orders.filter(o => o.date === todayStr && o.status !== "Cancelado").sort((a, b) => a.time.localeCompare(b.time));
  const avg = wa.surveys.length ? (wa.surveys.reduce((s, x) => s + x.nota, 0) / wa.surveys.length) : 0;
  const recoletaList = [
    { id: "rec-1", patientId: orders[0]?.patientId || "p1", patientName: orders[0]?.patientName || "Maria Aparecida Silva", exam: orders[0]?.exam || "Glicemia em jejum", problem: "Amostra hemolisada", detail: "A amostra chegou com hemólise e não permite resultado confiável. É preciso coletar novamente." },
    { id: "rec-2", patientId: orders[1]?.patientId || "p5", patientName: orders[1]?.patientName || "Fernanda Lima Almeida", exam: orders[1]?.exam || "Hemograma completo", problem: "Volume insuficiente", detail: "O volume coletado foi insuficiente para todos os testes do pedido. É preciso coletar novamente." },
  ];
  function confirmPreview() { if (!preview) return; const order = orders.find(o => o.id === preview.orderId); if (!order) { setPreview(null); return; } const after = preview.after; const text = preview.text; setPreview(null); if (sendWa(order, preview.kind, text)) {
    if (after === "lembrete") updateWa(prev => ({ ...prev, overrides: { ...prev.overrides, [order.id]: { ...prev.overrides[order.id], reminderSent: true } } }));
    if (after === "resultado") updateWa(prev => ({ ...prev, overrides: { ...prev.overrides, [order.id]: { ...prev.overrides[order.id], resultNotified: true } } }));
    if (after === "recoleta") updateWa(prev => ({ ...prev, recoletaDone: { ...prev.recoletaDone, [order.id]: true } }));
    if (after === "pos") updateWa(prev => ({ ...prev, overrides: { ...prev.overrides, [order.id]: { ...prev.overrides[order.id], postSent: true } } }));
    if (after === "pesquisa") updateWa(prev => ({ ...prev, overrides: { ...prev.overrides, [order.id]: { ...prev.overrides[order.id], surveySent: true } } }));
  } }
  const TABS = ["Conversa", "Lembretes", "Confirmação", "Fila de coleta", "Etapas", "Resultado", "Recoleta", "Pós-coleta", "Pesquisa", "Humano", "Consentimento"];
  return <div>
    <div className="rounded-2xl bg-[#FFF7D6] px-4 py-3 text-sm font-bold text-[#7A5600]">Simulação dentro do app — nenhuma mensagem sai do GottCured. Antes de qualquer envio, o app verifica o consentimento do paciente.</div>
    <div className="mt-3 flex flex-wrap gap-2 text-sm"><span className="pill px-3 py-1.5 font-bold">Nota média do Laboratório: {avg.toFixed(1)} / 5 · {wa.surveys.length} respostas</span><span className="pill px-3 py-1.5 font-bold">Coletas amanhã: {tomorrowOrders.length}</span><span className="pill px-3 py-1.5 font-bold">Fila hoje: {todayQueue.length}</span></div>
    <div className="mt-4 flex gap-2 overflow-x-auto pb-1 no-scrollbar">{TABS.map(t => <button key={t} onClick={() => setTab(t)} className={`pill shrink-0 px-3.5 py-2 text-[13px] font-semibold ${tab === t ? "chip-active" : ""}`}>{t}</button>)}</div>
    <label className={`${labelCls} mt-4`}>Pedido / paciente em análise<select value={selected?.id || ""} onChange={e => setSelectedId(e.target.value)} className={`${inputCls} mt-1`}>{orders.map(o => <option key={o.id} value={o.id}>{o.patientName} · {o.exam} · {fmtDate(o.date)} às {o.time} · {o.status}</option>)}</select></label>
    {selected && <div className="mt-2 flex flex-wrap gap-2">{consentFor(selected.patientId) ? <span className="rounded-full bg-[#D9EEDD] px-3 py-1.5 text-[12px] font-bold text-[#1E5B2A]">✓ Consentiu contato WhatsApp · {fmtDate(consentFor(selected.patientId)!.date)} · {consentFor(selected.patientId)!.channel}</span> : <span className="rounded-full bg-[#F8DEDC] px-3 py-1.5 text-[12px] font-bold text-[#8B2626]">Sem consentimento — envio bloqueado</span>}<span className="rounded-full bg-[var(--primary-soft)] px-3 py-1.5 text-[12px] font-bold text-[var(--primary)]">Status: {selected.status}</span><span className="rounded-full bg-[var(--surface-2)] px-3 py-1.5 text-[12px] font-bold">Etapa: {selected.stage}</span><span className="rounded-full bg-[var(--surface-2)] px-3 py-1.5 text-[12px] font-bold">Confirmação: {selected.confirmation}</span></div>}

    {tab === "Conversa" && selected && <div className="mt-4 grid gap-4 lg:grid-cols-[1.2fr_.8fr]">
      <div className="overflow-hidden rounded-3xl bg-[#E7F0E9] shadow-sm"><div className="bg-[#0F5F5C] px-4 py-3 text-white"><p className="font-extrabold">WhatsApp — {selected.patientName}</p><p className="text-xs opacity-80">{selected.exam} · {fmtDate(selected.date)} às {selected.time} · conversa simulada</p></div><div className="max-h-[320px] space-y-2 overflow-y-auto p-4">{chatMsgs.map((m, i) => <div key={i} className={`max-w-[85%] rounded-2xl p-3 text-sm leading-6 shadow ${m.from === "paciente" ? "bg-white" : m.from === "laboratorio" ? "ml-auto bg-[#D9FDD3]" : "mx-auto bg-[#FFF0C5] text-center"}`}><p>{m.text}</p><p className="mt-1 text-right text-[11px] text-[var(--muted)]">{m.at} · {m.kind}</p></div>)}</div><div className="bg-white p-3"><p className="text-[12px] font-bold">Simular mensagem do paciente</p><div className="mt-2 flex flex-wrap gap-2"><button onClick={() => addHistory(selected.patientId, { at: new Date().toLocaleString("pt-BR"), from: "paciente", text: "Quero agendar coleta", kind: "agendamento" })} className="pill px-3 py-1.5 text-xs font-bold">“Quero agendar coleta”</button><button onClick={() => addHistory(selected.patientId, { at: new Date().toLocaleString("pt-BR"), from: "paciente", text: "Preciso remarcar minha coleta", kind: "remarcacao" })} className="pill px-3 py-1.5 text-xs font-bold">“Preciso remarcar”</button><button onClick={() => addHistory(selected.patientId, { at: new Date().toLocaleString("pt-BR"), from: "paciente", text: "Preciso cancelar minha coleta", kind: "cancelamento" })} className="pill px-3 py-1.5 text-xs font-bold">“Preciso cancelar”</button></div></div></div>
      <div className="soft p-4"><h3 className="font-extrabold">Ações da conversa</h3><p className="mt-1 text-sm text-[var(--muted)]">Agendar, Remarcar e Cancelar atualizam o pedido real e registram o motivo quando houver cancelamento.</p><div className="mt-3 flex flex-wrap gap-2"><button onClick={() => { setChatMode("agendar"); setChatDate(tomorrowStr); }} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Agendar</button><button onClick={() => setChatMode("remarcar")} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Remarcar</button><button onClick={() => setChatMode("cancelar")} className="rounded-full bg-[#C83E3E] px-4 py-2 text-[13px] font-bold text-white">Cancelar coleta</button></div>
        {chatMode !== "none" && <div className="mt-4 space-y-2"><p className="font-bold text-sm">{chatMode === "agendar" ? "Agendar coleta" : chatMode === "remarcar" ? "Remarcar coleta" : "Cancelar coleta"}</p><label className={labelCls}>Data<input type="date" value={chatDate} onChange={e => setChatDate(e.target.value)} className={`${inputCls} mt-1`} disabled={chatMode === "cancelar"} /></label><label className={labelCls}>Horário<input type="time" value={chatTime} onChange={e => setChatTime(e.target.value)} className={`${inputCls} mt-1`} disabled={chatMode === "cancelar"} /></label>{chatMode === "cancelar" && <><label className={labelCls}>Motivo do cancelamento<select value={cancelMotive} onChange={e => setCancelMotive(e.target.value)} className={`${inputCls} mt-1`}><option>Paciente solicitou</option><option>Jejum inadequado</option><option>Problema na coleta</option><option>Exame duplicado</option><option>Convênio não autorizou</option><option>Paciente não compareceu</option><option>Outro motivo</option></select></label><label className={labelCls}>Detalhe do motivo<textarea value={cancelDetail} onChange={e => setCancelDetail(e.target.value)} rows={2} className={`${inputCls} mt-1`} placeholder="Detalhe do motivo do cancelamento…" /></label></>}
          <button onClick={() => { if (chatMode === "cancelar") { if (!cancelDetail.trim() && cancelMotive === "Outro motivo") { onNotice("Informe o detalhe do motivo do cancelamento."); return; } applyOrder(selected, { status: "Cancelado", cancelMotive: `${cancelMotive}${cancelDetail.trim() ? ` — ${cancelDetail.trim()}` : ""}` }, `Coleta cancelada — motivo: ${cancelMotive}${cancelDetail.trim() ? ` — ${cancelDetail.trim()}` : ""}`, `Coleta cancelada. Motivo registrado: ${cancelMotive}.`); addHistory(selected.patientId, { at: new Date().toLocaleString("pt-BR"), from: "laboratorio", text: `Coleta cancelada. Motivo registrado: ${cancelMotive}${cancelDetail.trim() ? ` — ${cancelDetail.trim()}` : ""}. Para reagendar, responda a esta conversa.`, kind: "cancelamento" }); } else { applyOrder(selected, { status: chatMode === "remarcar" ? "Remarcado" : "Agendado", date: chatDate, time: chatTime }, `${chatMode === "remarcar" ? "Coleta remarcada" : "Coleta agendada"} para ${fmtDate(chatDate)} às ${chatTime}`, `Coleta ${chatMode === "remarcar" ? "remarcada" : "agendada"} para ${fmtDate(chatDate)} às ${chatTime}.`); addHistory(selected.patientId, { at: new Date().toLocaleString("pt-BR"), from: "laboratorio", text: `Confirmado! Coleta ${chatMode === "remarcar" ? "remarcada" : "agendada"} para ${fmtDate(chatDate)} às ${chatTime} — ${selected.exam}. ${waPrepFor(selected.exam)}`, kind: "agendamento" }); } setChatMode("none"); }} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Confirmar {chatMode === "cancelar" ? "cancelamento" : chatMode === "remarcar" ? "remarcação" : "agendamento"}</button></div>}
        {selected.status === "Cancelado" && <p className="mt-3 rounded-xl bg-[#F8DEDC] px-3 py-2 text-sm font-bold text-[#8B2626]">Cancelado — motivo: {selected.cancelMotive}</p>}
        <div className="mt-4 border-t border-[var(--line)] pt-3"><p className="font-bold text-sm">Transferência para atendente humano</p>{wa.transferred[selected.patientId] ? <p className="mt-2 rounded-xl bg-[#FFF0C5] px-3 py-2 text-sm font-bold text-[#7A5600]">{wa.transferred[selected.patientId].status}{wa.transferred[selected.patientId].atendente ? ` · ${wa.transferred[selected.patientId].atendente}` : ""}</p> : <p className="mt-1 text-sm text-[var(--muted)]">Conversa em atendimento automático (IA).</p>}<label className={`${labelCls} mt-2`}>Atendente<input value={attendant} onChange={e => setAttendant(e.target.value)} className={`${inputCls} mt-1`} /></label><div className="mt-2 flex flex-wrap gap-2"><button onClick={() => { updateWa(prev => ({ ...prev, transferred: { ...prev.transferred, [selected.patientId]: { status: "Transferida - aguardando atendente", atendente: "" } } })); addHistory(selected.patientId, { at: new Date().toLocaleString("pt-BR"), from: "sistema", text: "Conversa transferida para atendente humano — aguardando atendente.", kind: "transferencia" }); onNotice("Conversa transferida — aguardando atendente humano."); }} className="rounded-full bg-[#7A5600] px-4 py-2 text-[13px] font-bold text-white">Transferir para atendente humano</button>{wa.transferred[selected.patientId] && <button onClick={() => { if (!attendant.trim()) { onNotice("Informe o nome do atendente que vai assumir."); return; } updateWa(prev => ({ ...prev, transferred: { ...prev.transferred, [selected.patientId]: { status: "Em atendimento humano", atendente: attendant.trim() } } })); addHistory(selected.patientId, { at: new Date().toLocaleString("pt-BR"), from: "sistema", text: `Atendente assumiu a conversa: ${attendant.trim()}.`, kind: "transferencia" }); onNotice(`${attendant.trim()} assumiu a conversa.`); }} className="pill px-4 py-2 text-[13px] font-bold">Atendente assumir</button>}</div></div>
      </div>
    </div>}

    {tab === "Lembretes" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Coletas de amanhã ({fmtDate(tomorrowStr)}). O preview mostra o preparo do exame antes de enviar.</p><div className="mt-3 space-y-3">{tomorrowOrders.map(o => <article key={o.id} className="soft p-4"><div className="flex flex-wrap justify-between gap-2"><div><p className="font-bold">{o.patientName} · {o.exam}</p><p className="mt-1 text-sm text-[var(--muted)]">{fmtDate(o.date)} às {o.time} · {o.status} · {consentFor(o.patientId) ? "Consentiu contato WhatsApp" : "Sem consentimento"}</p></div>{(wa.overrides[o.id]?.reminderSent) && <span className="h-fit rounded-full bg-[#D9EEDD] px-2.5 py-1 text-[11px] font-bold text-[#1E5B2A]">✓ Lembrete enviado</span>}</div><button onClick={() => setPreview({ orderId: o.id, kind: "lembrete", text: `Olá, ${o.patientName}! Lembrete da GottCured: sua coleta de ${o.exam} é amanhã, ${fmtDate(o.date)}, às ${o.time}. Preparo: ${waPrepFor(o.exam)} Responda SIM para confirmar.`, after: "lembrete" })} className="mt-3 rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Enviar lembrete</button></article>)}{!tomorrowOrders.length && <p className="text-sm text-[var(--muted)]">Nenhuma coleta para amanhã.</p>}</div></div>}

    {tab === "Confirmação" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Peça a confirmação e registre a resposta simulada do paciente — Sim, Não ou Precisa remarcar.</p><div className="mt-3 space-y-3">{tomorrowOrders.map(o => <article key={o.id} className="soft p-4"><div className="flex flex-wrap justify-between gap-2"><p className="font-bold">{o.patientName} · {o.exam} · {fmtDate(o.date)} às {o.time}</p><span className={`h-fit rounded-full px-2.5 py-1 text-[11px] font-bold ${o.confirmation === "Confirmado" ? "bg-[#D9EEDD] text-[#1E5B2A]" : o.confirmation === "Não confirmado" ? "bg-[#F8DEDC] text-[#8B2626]" : o.confirmation === "Precisa remarcar" ? "bg-[#FFF0C5] text-[#7A5600]" : "bg-[var(--surface-2)] text-[var(--muted)]"}`}>{o.confirmation}</span></div><div className="mt-3 flex flex-wrap gap-2"><button onClick={() => setPreview({ orderId: o.id, kind: "confirmacao", text: `Olá, ${o.patientName}! Você confirma sua coleta amanhã às ${o.time} para ${o.exam}? Responda SIM para confirmar, NÃO para cancelar ou REMARCAR para escolher outro horário.`, after: "confirmacao" })} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Pedir confirmação</button><button onClick={() => { applyOrder(o, { confirmation: "Confirmado", status: "Agendado" }, "Presença confirmada pelo paciente", `${o.patientName} confirmou presença.`); addHistory(o.patientId, { at: new Date().toLocaleString("pt-BR"), from: "paciente", text: "Sim, confirmo minha coleta.", kind: "confirmacao" }); }} className="pill px-3 py-2 text-[13px] font-bold">Simular resposta: Sim</button><button onClick={() => { applyOrder(o, { confirmation: "Não confirmado" }, "Paciente não confirmou presença", `${o.patientName} não confirmou presença.`); addHistory(o.patientId, { at: new Date().toLocaleString("pt-BR"), from: "paciente", text: "Não, não vou conseguir ir.", kind: "confirmacao" }); }} className="pill px-3 py-2 text-[13px] font-bold">Simular resposta: Não</button><button onClick={() => { applyOrder(o, { confirmation: "Precisa remarcar", status: "Remarcado" }, "Paciente pediu remarcação da coleta", `${o.patientName} precisa remarcar a coleta.`); addHistory(o.patientId, { at: new Date().toLocaleString("pt-BR"), from: "paciente", text: "Preciso remarcar, pode ser outro dia?", kind: "confirmacao" }); }} className="pill px-3 py-2 text-[13px] font-bold">Simular resposta: Precisa remarcar</button></div></article>)}</div></div>}

    {tab === "Fila de coleta" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Fila de coleta do dia ({fmtDate(todayStr)}), ordenada pelo horário marcado.</p><div className="mt-3 space-y-3">{todayQueue.map((o, i) => { const pos = i + 1; const est = (pos - 1) * 10; return <article key={o.id} className="soft p-4"><div className="flex flex-wrap justify-between gap-2"><div><p className="font-bold"><span className="mr-2 rounded-full bg-[var(--primary)] px-2.5 py-1 text-[12px] font-bold text-white">{pos}º da fila</span>{o.patientName} · {o.exam}</p><p className="mt-2 text-sm text-[var(--muted)]">Horário: {o.time} · Tempo estimado: {est} min · {o.status}{wa.overrides[o.id]?.called ? " · Chamado" : ""}</p></div></div><div className="mt-3 flex flex-wrap gap-2"><button onClick={() => setPreview({ orderId: o.id, kind: "fila", text: `Olá, ${o.patientName}! Você é o ${pos}º da fila de coleta, tempo estimado ${est} min. Aguarde a chamada — avisaremos quando for a sua vez.`, after: "fila" })} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Avisar posição</button><button onClick={() => { if (!sendWa(o, "chamada", `Olá, ${o.patientName}! É a sua vez! Dirija-se ao Box 2 para a coleta de ${o.exam}.`)) return; updateWa(prev => ({ ...prev, overrides: { ...prev.overrides, [o.id]: { ...prev.overrides[o.id], called: true } } })); syncPatient(o, "Paciente chamado para a coleta — Box 2"); }} className="rounded-full bg-[#177E4B] px-4 py-2 text-[13px] font-bold text-white">Chamar paciente</button></div></article>; })}{!todayQueue.length && <p className="text-sm text-[var(--muted)]">Nenhum paciente na fila de hoje.</p>}</div></div>}

    {tab === "Etapas" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Mude a etapa da amostra e notifique o paciente. O histórico de notificações fica por paciente abaixo.</p><div className="mt-3 space-y-3">{orders.map(o => <article key={o.id} className="soft p-4"><div className="flex flex-wrap justify-between gap-2"><p className="font-bold">{o.patientName} · {o.exam}</p><span className="rounded-full bg-[var(--primary-soft)] px-2.5 py-1 text-[11px] font-bold text-[var(--primary)]">{o.stage}</span></div><div className="mt-3 flex flex-wrap gap-2"><select value={stageDraft[o.id] || o.stage} onChange={e => setStageDraft(prev => ({ ...prev, [o.id]: e.target.value }))} className="rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-sm" aria-label={`Etapa de ${o.exam}`}><option>Aguardando coleta</option><option>Coletada</option><option>Em análise</option><option>Resultado disponível</option></select><button onClick={() => { const st = stageDraft[o.id] || o.stage; applyOrder(o, { stage: st }, `Etapa atualizada: ${st} — ${o.exam}`, `Etapa de ${o.exam} atualizada para ${st}.`); }} className="pill px-4 py-2 text-[13px] font-bold">Atualizar etapa</button><button onClick={() => setPreview({ orderId: o.id, kind: "etapa", text: `Olá, ${o.patientName}! Atualização do seu exame ${o.exam}: etapa atual — ${o.stage}. Avisaremos quando o resultado estiver disponível.`, after: "etapa" })} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Notificar etapa</button></div>{(wa.history[o.patientId] || []).filter(m => m.kind === "etapa").length > 0 && <div className="mt-3 rounded-xl bg-[var(--surface)] p-3 text-sm"><p className="font-bold">Histórico de notificações — {o.patientName}</p><ul className="mt-1 space-y-1">{(wa.history[o.patientId] || []).filter(m => m.kind === "etapa").map((m, i) => <li key={i}>• {m.at} — {m.text}</li>)}</ul></div>}</article>)}</div></div>}

    {tab === "Resultado" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Ao liberar o resultado, avise o paciente com o link do portal.</p><div className="mt-3 space-y-3">{orders.map(o => <article key={o.id} className="soft p-4"><div className="flex flex-wrap justify-between gap-2"><p className="font-bold">{o.patientName} · {o.exam} · {o.stage}</p>{wa.overrides[o.id]?.resultNotified && <span className="rounded-full bg-[#D9EEDD] px-2.5 py-1 text-[11px] font-bold text-[#1E5B2A]">✓ Aviso de resultado enviado</span>}</div><button onClick={() => setPreview({ orderId: o.id, kind: "resultado", text: `Olá, ${o.patientName}! O resultado do seu exame ${o.exam} já está disponível. Acesse o portal do paciente em portal.gottcured.com.br/resultados com seu documento e carteirinha. Em caso de dúvida, responda a esta conversa.`, after: "resultado" })} className="mt-3 rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Avisar resultado disponível</button></article>)}</div></div>}

    {tab === "Recoleta" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Amostras com problema — avise o motivo e ofereça reagendamento.</p><div className="mt-3 space-y-3">{recoletaList.map(r => { const order = orders.find(o => o.patientId === r.patientId) || orders[0]; return <article key={r.id} className="soft p-4"><p className="font-bold">{r.patientName} · {r.exam}</p><p className="mt-1 text-sm text-[var(--muted)]"><strong className="text-[#8B2626]">{r.problem}:</strong> {r.detail}</p>{wa.recoletaDone[order.id] && <p className="mt-2 text-sm font-bold text-[var(--ok)]">✓ Aviso de recoleta enviado.</p>}<div className="mt-3 flex flex-wrap gap-2"><button onClick={() => setPreview({ orderId: order.id, kind: "recoleta", text: `Olá, ${r.patientName}! Precisamos coletar novamente o exame ${r.exam}: ${r.detail} Sem custo adicional. Podemos reagendar — responda a esta conversa ou use o botão de reagendamento.`, after: "recoleta" })} className="rounded-full bg-[#C83E3E] px-4 py-2 text-[13px] font-bold text-white">Avisar necessidade de recoleta</button><label className="text-sm font-bold">Nova data<input type="date" value={recoletaDate} onChange={e => setRecoletaDate(e.target.value)} className="ml-2 rounded-xl border border-[var(--line)] bg-[var(--surface)] px-2 py-2 text-sm" /></label><label className="text-sm font-bold">Horário<input type="time" value={recoletaTime} onChange={e => setRecoletaTime(e.target.value)} className="ml-2 rounded-xl border border-[var(--line)] bg-[var(--surface)] px-2 py-2 text-sm" /></label><button onClick={() => { applyOrder(order, { status: "Agendado", date: recoletaDate, time: recoletaTime }, `Recoleta reagendada para ${fmtDate(recoletaDate)} às ${recoletaTime}`, `Recoleta reagendada para ${fmtDate(recoletaDate)} às ${recoletaTime}.`); addHistory(order.patientId, { at: new Date().toLocaleString("pt-BR"), from: "laboratorio", text: `Recoleta reagendada para ${fmtDate(recoletaDate)} às ${recoletaTime} — ${r.exam}.`, kind: "recoleta" }); }} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Reagendar coleta</button></div></article>; })}</div></div>}

    {tab === "Pós-coleta" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Orientações pós-coleta por tipo de exame.</p><div className="mt-3 space-y-3">{orders.map(o => <article key={o.id} className="soft p-4"><p className="font-bold">{o.patientName} · {o.exam}</p><p className="mt-1 text-sm text-[var(--muted)]">{waPostFor(o.exam)}</p>{wa.overrides[o.id]?.postSent && <p className="mt-2 text-sm font-bold text-[var(--ok)]">✓ Orientações pós-coleta enviadas.</p>}<button onClick={() => setPreview({ orderId: o.id, kind: "pos", text: `Olá, ${o.patientName}! Orientações pós-coleta — ${o.exam}: ${waPostFor(o.exam)}`, after: "pos" })} className="mt-3 rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Enviar orientações pós-coleta</button></article>)}</div></div>}

    {tab === "Pesquisa" && <div className="mt-4"><div className="soft p-4"><p className="font-extrabold">Nota média do Laboratório: {avg.toFixed(1)} / 5</p><p className="mt-1 text-sm text-[var(--muted)]">{wa.surveys.length} respostas registradas. Cada resposta simulada atualiza a média.</p><div className="mt-3 space-y-1 text-sm">{wa.surveys.map((s, i) => <p key={i}>• {s.patientName} — nota {s.nota} / 5 · {s.comentario} · {s.at}</p>)}</div></div><div className="mt-3 space-y-3">{orders.map(o => <article key={o.id} className="soft p-4"><p className="font-bold">{o.patientName} · {o.exam}</p><button onClick={() => setPreview({ orderId: o.id, kind: "pesquisa", text: `Olá, ${o.patientName}! Como foi sua experiência no Laboratório? Responda com uma nota de 0 a 5 e um comentário. Sua resposta ajuda a melhorar o atendimento.`, after: "pesquisa" })} className="mt-3 rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Enviar pesquisa</button>{wa.overrides[o.id]?.surveySent && <div className="mt-3 flex flex-wrap gap-2"><label className="text-sm font-bold">Nota do paciente<select value={surveyDraft[o.id]?.nota ?? 5} onChange={e => setSurveyDraft(prev => ({ ...prev, [o.id]: { nota: Number(e.target.value), comentario: prev[o.id]?.comentario || "" } }))} className="ml-2 rounded-xl border border-[var(--line)] bg-[var(--surface)] px-2 py-2 text-sm">{[0, 1, 2, 3, 4, 5].map(n => <option key={n}>{n}</option>)}</select></label><input value={surveyDraft[o.id]?.comentario || ""} onChange={e => setSurveyDraft(prev => ({ ...prev, [o.id]: { nota: prev[o.id]?.nota ?? 5, comentario: e.target.value } }))} placeholder="Comentário do paciente…" className={`${inputCls} min-w-[200px] flex-1`} aria-label="Comentário da pesquisa" /><button onClick={() => { const d = surveyDraft[o.id] || { nota: 5, comentario: "" }; updateWa(prev => ({ ...prev, surveys: [{ patientId: o.patientId, patientName: o.patientName, nota: d.nota, comentario: d.comentario.trim() || "Sem comentário.", at: new Date().toLocaleString("pt-BR") }, ...prev.surveys] })); addHistory(o.patientId, { at: new Date().toLocaleString("pt-BR"), from: "paciente", text: `Pesquisa respondida: nota ${d.nota} / 5. ${d.comentario.trim()}`, kind: "pesquisa" }); onNotice(`Resposta registrada: nota ${d.nota} / 5. Nova média atualizada.`); }} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Simular resposta do paciente</button></div>}</article>)}</div></div>}

    {tab === "Humano" && selected && <div className="mt-4 soft p-4"><p className="font-extrabold">Transferência para atendente humano — {selected.patientName}</p><p className="mt-1 text-sm text-[var(--muted)]">Use também o botão “Transferir para atendente humano” dentro da aba Conversa.</p>{wa.transferred[selected.patientId] ? <p className="mt-3 rounded-xl bg-[#FFF0C5] px-3 py-2 text-sm font-bold text-[#7A5600]">{wa.transferred[selected.patientId].status}{wa.transferred[selected.patientId].atendente ? ` · ${wa.transferred[selected.patientId].atendente}` : ""}</p> : <p className="mt-3 text-sm">Conversa em atendimento automático (IA).</p>}<label className={`${labelCls} mt-3`}>Atendente<input value={attendant} onChange={e => setAttendant(e.target.value)} className={`${inputCls} mt-1`} /></label><div className="mt-3 flex flex-wrap gap-2"><button onClick={() => { updateWa(prev => ({ ...prev, transferred: { ...prev.transferred, [selected.patientId]: { status: "Transferida - aguardando atendente", atendente: "" } } })); onNotice("Conversa transferida — aguardando atendente humano."); }} className="rounded-full bg-[#7A5600] px-4 py-2 text-[13px] font-bold text-white">Transferir para atendente humano</button>{wa.transferred[selected.patientId] && <button onClick={() => { if (!attendant.trim()) { onNotice("Informe o nome do atendente que vai assumir."); return; } updateWa(prev => ({ ...prev, transferred: { ...prev.transferred, [selected.patientId]: { status: "Em atendimento humano", atendente: attendant.trim() } } })); onNotice(`${attendant.trim()} assumiu a conversa.`); }} className="pill px-4 py-2 text-[13px] font-bold">Atendente assumir</button>}</div></div>}

    {tab === "Consentimento" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Sem consentimento, o envio é bloqueado. O registro guarda data, canal e o texto aceito (LGPD).</p><div className="mt-3 space-y-3">{patients.map(p => <article key={p.id} className="soft p-4"><div className="flex flex-wrap justify-between gap-2"><p className="font-bold">{p.name} · {p.phone}</p>{consentFor(p.id) ? <span className="rounded-full bg-[#D9EEDD] px-2.5 py-1 text-[11px] font-bold text-[#1E5B2A]">Consentiu contato WhatsApp · {fmtDate(consentFor(p.id)!.date)} · {consentFor(p.id)!.channel}</span> : <span className="rounded-full bg-[#F8DEDC] px-2.5 py-1 text-[11px] font-bold text-[#8B2626]">Sem consentimento — envio bloqueado</span>}</div>{consentFor(p.id) && <p className="mt-2 text-[13px] text-[var(--muted)]">{consentFor(p.id)!.text}</p>}<button onClick={() => setConsentForm({ patientId: p.id, date: new Date().toISOString().slice(0, 10), channel: "WhatsApp", text: WA_CONSENT_TEXT })} className="mt-3 rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Registrar consentimento</button>{consentForm?.patientId === p.id && <div className="mt-3 space-y-2"><label className={labelCls}>Data do consentimento<input type="date" value={consentForm.date} onChange={e => setConsentForm({ ...consentForm, date: e.target.value })} className={`${inputCls} mt-1`} /></label><label className={labelCls}>Canal<select value={consentForm.channel} onChange={e => setConsentForm({ ...consentForm, channel: e.target.value })} className={`${inputCls} mt-1`}><option>WhatsApp</option><option>SMS</option><option>Ligação</option><option>Presencial</option></select></label><label className={labelCls}>Texto do consentimento (LGPD)<textarea value={consentForm.text} onChange={e => setConsentForm({ ...consentForm, text: e.target.value })} rows={3} className={`${inputCls} mt-1`} /></label><button onClick={() => { if (!consentForm.text.trim() || !consentForm.date) { onNotice("Informe a data e o texto do consentimento."); return; } updateWa(prev => ({ ...prev, consents: { ...prev.consents, [p.id]: { date: consentForm.date, channel: consentForm.channel, text: consentForm.text.trim() } } })); setConsentForm(null); onNotice(`Consentimento registrado para ${p.name} — envio por WhatsApp liberado.`); }} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Salvar consentimento</button></div>}</article>)}</div></div>}

    {preview && <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/40 p-4" onClick={() => setPreview(null)}><div className="w-full max-w-[440px] overflow-hidden rounded-3xl bg-[#E7F0E9] shadow-2xl" onClick={e => e.stopPropagation()}><div className="bg-[#0F5F5C] px-4 py-3 text-white"><p className="font-extrabold">WhatsApp — prévia</p><p className="text-xs opacity-80">Janela simulada · nada é enviado para fora do app até confirmar</p></div><div className="p-4"><div className="rounded-2xl bg-white p-3 text-sm leading-6 whitespace-pre-wrap shadow">{preview.text}</div><p className="mt-2 text-[13px] text-[var(--muted)]">Verifique o consentimento do paciente antes de enviar.</p></div><div className="flex gap-2 bg-white px-4 py-3"><button onClick={confirmPreview} className="flex-1 rounded-full bg-[#177E4B] px-4 py-2.5 text-sm font-bold text-white">Enviar</button><button onClick={() => setPreview(null)} className="pill px-4 py-2.5 text-sm font-bold">Cancelar</button></div></div></div>}
  </div>;
}
/* ---------- INTEGRAÇÃO COM OUTROS MÓDULOS — LABORATÓRIO ---------- */
type LabTicket = { id: string; equipment: string; type: string; description: string; priority: string; status: string; createdAt: string };
type BedsideRec = { id: string; patientName: string; unit: string; bed: string; exam: string; result: string; createdAt: string };
type DelayRec = { id: string; patientName: string; exam: string; unit: string; bed: string; delayH: number; impact: string; prioritized?: boolean };
type ReagentOut = { id: string; reagent: string; exam: string; qty: number; unitCost: number; total: number; createdAt: string };
function IntegracaoLabModule({ patients, onNotice, onGoTab }: { patients: Patient[]; onNotice: (m: string) => void; onGoTab: (t: string) => void }) {
  const [tab, setTab] = useState("Chamados de manutenção");
  const [tickets, setTickets] = useState<LabTicket[]>([
    { id: "tk-1", equipment: "Autoclave A-03", type: "Preventiva", description: "Preventiva próxima do prazo — verificar vedação.", priority: "Alta", status: "Em atendimento", createdAt: "12/06/2026, 08:10" },
    { id: "tk-2", equipment: "Centrífuga C-05", type: "Corretiva", description: "Vibração acima do padrão em rotação alta.", priority: "Média", status: "Aberto", createdAt: "12/06/2026, 09:40" },
  ]);
  const [ticketForm, setTicketForm] = useState({ equipment: "Analisador L-01", type: "Corretiva", description: "", priority: "Alta" });
  const [bedside, setBedside] = useState<BedsideRec[]>([
    { id: "bs-1", patientName: "Rosa Maria Ferreira", unit: "Enfermaria", bed: "Leito 04", exam: "Glicemia em jejum", result: "132 mg/dL", createdAt: "12/06/2026, 09:15" },
    { id: "bs-2", patientName: "Maria Aparecida Silva", unit: "UTI", bed: "Leito 02", exam: "Potássio", result: "4,1 mmol/L", createdAt: "12/06/2026, 10:02" },
  ]);
  const [bedForm, setBedForm] = useState({ patientId: patients[0]?.id || "p1", unit: "Enfermaria", bed: "Leito 04", exam: "Glicemia em jejum", result: "" });
  const [delays, setDelays] = useState<DelayRec[]>([
    { id: "dl-1", patientName: "Rosa Maria Ferreira", exam: "Creatinina", unit: "Enfermaria", bed: "Leito 04", delayH: 9, impact: "+1 dia de permanência", prioritized: false },
    { id: "dl-2", patientName: "Maria Aparecida Silva", exam: "Hemoglobina glicada", unit: "UTI", bed: "Leito 02", delayH: 14, impact: "+1 dia de permanência", prioritized: false },
    { id: "dl-3", patientName: "Carlos Eduardo Oliveira", exam: "Colesterol total e frações", unit: "Enfermaria", bed: "Leito 07", delayH: 5, impact: "+8 horas de permanência", prioritized: false },
  ]);
  const [originFilter, setOriginFilter] = useState("Todas");
  const [baixas, setBaixas] = useState<ReagentOut[]>([
    { id: "bx-1", reagent: "Reagente Glicose", exam: "Glicemia em jejum", qty: 42, unitCost: 3.2, total: 134.4, createdAt: "12/06/2026, 08:30" },
    { id: "bx-2", reagent: "Reagente Hemograma", exam: "Hemograma completo", qty: 58, unitCost: 4.1, total: 237.8, createdAt: "12/06/2026, 09:10" },
  ]);
  const [baixaForm, setBaixaForm] = useState({ reagent: "Reagente Glicose", exam: "Glicemia em jejum", qty: "10", unitCost: "3,20" });
  const inputCls = "w-full rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-sm outline-none";
  const labelCls = "block text-sm font-bold";
  useEffect(() => { let alive = true; (async () => { try { const d: any = await api("records.list", { collection: "gottcured_lab_integracao" }); if (!alive || !d?.records?.length) return; const tk: LabTicket[] = []; const bs: BedsideRec[] = []; const bx: ReagentOut[] = []; const pri = new Set<string>(); for (const r of d.records) { const v = r.value || {}; if (v.kind === "ticket") tk.push(v.ticket); if (v.kind === "bedside") bs.push(v.bedside); if (v.kind === "baixa") bx.push(v.baixa); if (v.kind === "priorizado" && v.delayId) pri.add(v.delayId); } if (tk.length) setTickets(prev => [...tk, ...prev]); if (bs.length) setBedside(prev => [...bs, ...prev]); if (bx.length) setBaixas(prev => [...bx, ...prev]); if (pri.size) setDelays(prev => prev.map(x => pri.has(x.id) ? { ...x, prioritized: true } : x)); } catch { } })(); return () => { alive = false; }; }, []);
  async function createTicket() { if (!ticketForm.description.trim()) { onNotice("Descreva o problema do equipamento antes de abrir o chamado."); return; } const t: LabTicket = { id: `tk-${Date.now()}`, equipment: ticketForm.equipment, type: ticketForm.type, description: ticketForm.description.trim(), priority: ticketForm.priority, status: "Aberto", createdAt: new Date().toLocaleString("pt-BR") }; setTickets(prev => [t, ...prev]); setTicketForm(prev => ({ ...prev, description: "" })); try { await api("records.create", { collection: "gottcured_lab_integracao", value: { kind: "ticket", ticket: t, createdAt: new Date().toISOString() }, idempotency_key: `gottcured-lab-integ-ticket-${t.id}` }); onNotice(`Chamado aberto para ${t.equipment} — ${t.type} · prioridade ${t.priority}. O chamado aparece na lista abaixo e no fluxo de manutenção da Clínica.`); } catch { onNotice(`Chamado aberto para ${t.equipment} nesta sessão. A sincronização será tentada novamente.`); } }
  async function advanceTicket(t: LabTicket) { const next = t.status === "Aberto" ? "Em atendimento" : t.status === "Em atendimento" ? "Concluído" : "Concluído"; setTickets(prev => prev.map(x => x.id === t.id ? { ...x, status: next } : x)); try { await api("records.create", { collection: "gottcured_lab_integracao", value: { kind: "ticket_status", ticketId: t.id, status: next, createdAt: new Date().toISOString() }, idempotency_key: `gottcured-lab-integ-status-${t.id}-${next}` }); } catch { } onNotice(`Chamado de ${t.equipment}: ${next}.`); }
  async function registerBedside() { const p = patients.find(x => x.id === bedForm.patientId) || patients[0]; if (!p) { onNotice("Selecione um paciente internado."); return; } if (!bedForm.result.trim()) { onNotice("Informe o resultado obtido no leito."); return; } const rec: BedsideRec = { id: `bs-${Date.now()}`, patientName: p.name, unit: bedForm.unit, bed: bedForm.bed.trim() || "Leito —", exam: bedForm.exam, result: bedForm.result.trim(), createdAt: new Date().toLocaleString("pt-BR") }; setBedside(prev => [rec, ...prev]); setBedForm(prev => ({ ...prev, result: "" })); try { await api("records.create", { collection: "gottcured_lab_integracao", value: { kind: "bedside", bedside: rec, createdAt: new Date().toISOString() }, idempotency_key: `gottcured-lab-integ-bed-${rec.id}` }); onNotice(`Resultado no leito registrado: ${rec.exam} — ${rec.result} · ${rec.patientName} · ${rec.unit} — ${rec.bed}.`); } catch { onNotice(`Resultado no leito registrado nesta sessão para ${rec.patientName}.`); } }
  async function prioritizeDelay(d: DelayRec) { setDelays(prev => prev.map(x => x.id === d.id ? { ...x, prioritized: true } : x)); try { await api("records.create", { collection: "gottcured_lab_integracao", value: { kind: "priorizado", delayId: d.id, createdAt: new Date().toISOString() }, idempotency_key: `gottcured-lab-integ-prio-${d.id}` }); } catch { } onNotice(`${d.exam} de ${d.patientName} priorizado — entra no início da fila de análise.`); }
  async function darBaixa() { const qty = Number(String(baixaForm.qty).replace(",", ".")); const unit = Number(String(baixaForm.unitCost).replace(",", ".")); if (!qty || qty <= 0 || !unit || unit <= 0) { onNotice("Informe quantidade e custo unitário maiores que zero."); return; } const total = Math.round(qty * unit * 100) / 100; const rec: ReagentOut = { id: `bx-${Date.now()}`, reagent: baixaForm.reagent, exam: baixaForm.exam, qty, unitCost: unit, total, createdAt: new Date().toLocaleString("pt-BR") }; setBaixas(prev => [rec, ...prev]); try { await api("records.create", { collection: "gottcured_lab_integracao", value: { kind: "baixa", baixa: rec, createdAt: new Date().toISOString() }, idempotency_key: `gottcured-lab-integ-baixa-${rec.id}` }); onNotice(`Baixa registrada: ${rec.reagent} — ${money(rec.total)}. Custo lançado automaticamente no Financeiro do Laboratório (custo por exame).`); } catch { onNotice(`Baixa registrada nesta sessão: ${money(total)}. A sincronização com o Financeiro será tentada novamente.`); } }
  const originOrders = useMemo(() => {
    const derived = patients.flatMap(p => (p.orders || []).map(o => ({ id: o.id, patientName: p.name, exam: o.name, origin: "Consulta" as const, status: o.status, date: o.date })));
    const retorno: typeof derived = [
      { id: "ret-1", patientName: "Fernanda Lima Almeida", exam: "Hemograma completo", origin: "Retorno", status: "Solicitado", date: "10/06/2026" },
      { id: "ret-2", patientName: "Carlos Eduardo Oliveira", exam: "Colesterol total e frações", origin: "Retorno", status: "Solicitado", date: "09/06/2026" },
      { id: "ret-3", patientName: "Maria Aparecida Silva", exam: "Glicemia em jejum", origin: "Retorno", status: "Resultado disponível", date: "10/06/2026" },
      { id: "ret-4", patientName: "Rosa Maria Ferreira", exam: "Creatinina", origin: "Clínica", status: "Solicitado", date: "11/06/2026" },
    ];
    return [...retorno, ...derived];
  }, [patients]);
  const originFiltered = originOrders.filter(o => originFilter === "Todas" || o.origin === originFilter);
  const custoPorExame = useMemo(() => { const m = new Map<string, { exam: string; qty: number; total: number }>(); for (const b of baixas) { const cur = m.get(b.exam) || { exam: b.exam, qty: 0, total: 0 }; cur.qty += b.qty; cur.total += b.total; m.set(b.exam, cur); } return Array.from(m.values()); }, [baixas]);
  const totalBaixas = baixas.reduce((s, b) => s + b.total, 0);
  const exec = [{ name: "Laboratório", producao: 29840, custo: 312000, receita: 486000 }, { name: "Clínica", producao: 2950, custo: 198000, receita: 386000 }];
  const execTotal = { producao: exec.reduce((s, x) => s + x.producao, 0), custo: exec.reduce((s, x) => s + x.custo, 0), receita: exec.reduce((s, x) => s + x.receita, 0) };
  const TABS = ["Chamados de manutenção", "Internados e leito", "Atrasos e permanência", "Origem dos pedidos", "Custo no Financeiro", "Dashboard Executivo"];
  return <div>
    <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">{TABS.map(t => <button key={t} onClick={() => setTab(t)} className={`pill shrink-0 px-3.5 py-2 text-[13px] font-semibold ${tab === t ? "chip-active" : ""}`}>{t}</button>)}</div>
    {tab === "Chamados de manutenção" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Chamado aberto no Laboratório entra no mesmo fluxo de manutenção usado pela Clínica — tipo, descrição e prioridade ficam registrados na lista.</p>
      <div className="soft mt-3 p-4"><h4 className="font-extrabold">Abrir chamado</h4><div className="mt-3 grid gap-2 sm:grid-cols-2"><label className={labelCls}>Equipamento<select value={ticketForm.equipment} onChange={e => setTicketForm({ ...ticketForm, equipment: e.target.value })} className={`${inputCls} mt-1`}><option>Analisador L-01</option><option>Analisador L-02</option><option>Centrífuga C-05</option><option>Autoclave A-03</option><option>Ultrassom U-02</option></select></label><label className={labelCls}>Tipo<select value={ticketForm.type} onChange={e => setTicketForm({ ...ticketForm, type: e.target.value })} className={`${inputCls} mt-1`}><option>Corretiva</option><option>Preventiva</option><option>Calibração</option><option>Verificação</option></select></label><label className={labelCls}>Prioridade<select value={ticketForm.priority} onChange={e => setTicketForm({ ...ticketForm, priority: e.target.value })} className={`${inputCls} mt-1`}><option>Alta</option><option>Média</option><option>Baixa</option></select></label><label className={`${labelCls} sm:col-span-2`}>Descrição<textarea value={ticketForm.description} onChange={e => setTicketForm({ ...ticketForm, description: e.target.value })} rows={2} className={`${inputCls} mt-1`} placeholder="Descreva o problema, o sintoma e o impacto nos exames…" /></label></div><button onClick={createTicket} className="mt-3 rounded-full bg-[var(--primary)] px-5 py-2.5 text-sm font-bold text-white">Abrir chamado</button></div>
      <div className="mt-4 space-y-2">{tickets.map(t => <article key={t.id} className="soft flex flex-wrap items-center justify-between gap-3 p-4"><div><p className="font-bold text-sm">{t.equipment} · {t.type}</p><p className="mt-1 text-sm text-[var(--muted)]">{t.description} · {t.createdAt}</p></div><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-[#FFF0C5] px-2.5 py-1 text-[11px] font-bold text-[#7A5600]">Prioridade {t.priority}</span><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${t.status === "Concluído" ? "bg-[#D9EEDD] text-[#1E5B2A]" : "bg-[var(--primary-soft)] text-[var(--primary)]"}`}>{t.status}</span>{t.status !== "Concluído" && <button onClick={() => advanceTicket(t)} className="rounded-full bg-[var(--primary)] px-3 py-1.5 text-xs font-bold text-white">{t.status === "Aberto" ? "Iniciar atendimento" : "Concluir chamado"}</button>}</div></article>)}</div></div>}
    {tab === "Internados e leito" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Pedidos de pacientes internados com unidade e leito. O resultado registrado no leito fica vinculado ao pedido e à unidade.</p>
      <div className="soft mt-3 p-4"><h4 className="font-extrabold">Registrar no leito</h4><div className="mt-3 grid gap-2 sm:grid-cols-3"><label className={labelCls}>Paciente<select value={bedForm.patientId} onChange={e => setBedForm({ ...bedForm, patientId: e.target.value })} className={`${inputCls} mt-1`}>{patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label className={labelCls}>Unidade<select value={bedForm.unit} onChange={e => setBedForm({ ...bedForm, unit: e.target.value })} className={`${inputCls} mt-1`}><option>Enfermaria</option><option>UTI</option><option>Emergência</option></select></label><label className={labelCls}>Leito<input value={bedForm.bed} onChange={e => setBedForm({ ...bedForm, bed: e.target.value })} className={`${inputCls} mt-1`} /></label><label className={labelCls}>Exame<select value={bedForm.exam} onChange={e => setBedForm({ ...bedForm, exam: e.target.value })} className={`${inputCls} mt-1`}><option>Glicemia em jejum</option><option>Potássio</option><option>Creatinina</option><option>Hemoglobina glicada</option></select></label><label className={labelCls}>Resultado<input value={bedForm.result} onChange={e => setBedForm({ ...bedForm, result: e.target.value })} placeholder="Ex.: 132 mg/dL" className={`${inputCls} mt-1`} /></label></div><button onClick={registerBedside} className="mt-3 rounded-full bg-[var(--primary)] px-5 py-2.5 text-sm font-bold text-white">Registrar no leito</button></div>
      <div className="mt-4 space-y-2">{bedside.map(b => <article key={b.id} className="soft p-4"><div className="flex flex-wrap justify-between gap-2"><p className="font-bold">{b.patientName} · {b.unit} — {b.bed}</p><span className="rounded-full bg-[var(--primary-soft)] px-2.5 py-1 text-[11px] font-bold text-[var(--primary)]">Resultado no leito</span></div><p className="mt-1 text-sm text-[var(--muted)]">{b.exam} · <strong className="text-[var(--ink)]">{b.result}</strong> · {b.createdAt}</p></article>)}</div></div>}
    {tab === "Atrasos e permanência" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Resultado atrasado segura decisão clínica e prolonga a permanência. Priorizar o exame coloca o pedido no início da fila de análise.</p><div className="mt-3 overflow-x-auto"><table className="w-full min-w-[640px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Paciente / leito</th><th className="py-2 pr-3">Exame</th><th className="py-2 pr-3">Atraso</th><th className="py-2 pr-3">Impacto estimado</th><th className="py-2">Ação</th></tr></thead><tbody>{delays.map(d => <tr key={d.id} className="border-t border-[var(--line)]"><td className="py-3 pr-3 font-bold">{d.patientName}<span className="block text-[12px] font-normal text-[var(--muted)]">{d.unit} — {d.bed}</span></td><td className="py-3 pr-3">{d.exam}</td><td className="py-3 pr-3 font-bold text-[#8B2626]">{d.delayH} h</td><td className="py-3 pr-3">{d.impact}</td><td className="py-3">{d.prioritized ? <span className="rounded-full bg-[#D9EEDD] px-2.5 py-1 text-[11px] font-bold text-[#1E5B2A]">✓ Priorizado</span> : <button onClick={() => prioritizeDelay(d)} className="rounded-full bg-[var(--primary)] px-3 py-1.5 text-xs font-bold text-white">Priorizar exame</button>}</td></tr>)}</tbody></table></div><p className="mt-3 text-sm text-[var(--muted)]">Total estimado: <strong>+{delays.reduce((s, d) => s + d.delayH, 0)} h de atraso</strong> nos pedidos listados.</p></div>}
    {tab === "Origem dos pedidos" && <div className="mt-4"><div className="flex flex-wrap gap-2"><label className="text-sm font-bold">Filtrar por origem<select value={originFilter} onChange={e => setOriginFilter(e.target.value)} className="ml-2 rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-sm"><option>Todas</option><option>Consulta</option><option>Retorno</option><option>Clínica</option></select></label><p className="text-sm text-[var(--muted)]">{originFiltered.length} pedido(s) com a origem selecionada.</p></div><div className="mt-3 space-y-2">{originFiltered.map(o => <article key={o.id} className="soft flex flex-wrap items-center justify-between gap-3 p-4"><div><p className="font-bold text-sm">{o.exam} · {o.patientName}</p><p className="mt-1 text-[13px] text-[var(--muted)]">{o.date} · Status: {o.status}</p></div><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${o.origin === "Consulta" ? "bg-[var(--primary-soft)] text-[var(--primary)]" : o.origin === "Retorno" ? "bg-[#FFF0C5] text-[#7A5600]" : "bg-[#E0EAFB] text-[#1D4E8A]"}`}>{o.origin}</span></article>)}{!originFiltered.length && <p className="text-sm text-[var(--muted)]">Nenhum pedido com essa origem.</p>}</div></div>}
    {tab === "Custo no Financeiro" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">A baixa de reagente gera custo automaticamente no Financeiro do Laboratório, por exame. Use “Ver no Financeiro” para abrir Finanças do Laboratório.</p>
      <div className="soft mt-3 p-4"><h4 className="font-extrabold">Dar baixa de reagente</h4><div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><label className={labelCls}>Reagente<select value={baixaForm.reagent} onChange={e => setBaixaForm({ ...baixaForm, reagent: e.target.value })} className={`${inputCls} mt-1`}><option>Reagente Glicose</option><option>Reagente Hemograma</option><option>Reagente Colesterol</option><option>Reagente TSH</option></select></label><label className={labelCls}>Exame<select value={baixaForm.exam} onChange={e => setBaixaForm({ ...baixaForm, exam: e.target.value })} className={`${inputCls} mt-1`}><option>Glicemia em jejum</option><option>Hemograma completo</option><option>Colesterol total e frações</option><option>TSH</option></select></label><label className={labelCls}>Quantidade<input type="number" min={1} value={baixaForm.qty} onChange={e => setBaixaForm({ ...baixaForm, qty: e.target.value })} className={`${inputCls} mt-1`} /></label><label className={labelCls}>Custo unitário (R$)<input value={baixaForm.unitCost} onChange={e => setBaixaForm({ ...baixaForm, unitCost: e.target.value })} className={`${inputCls} mt-1`} /></label></div><div className="mt-3 flex flex-wrap gap-2"><button onClick={darBaixa} className="rounded-full bg-[var(--primary)] px-5 py-2.5 text-sm font-bold text-white">Dar baixa e lançar no Financeiro</button><button onClick={() => { onGoTab("Finanças do Laboratório"); onNotice("Financeiro do Laboratório aberto — custo por exame com as baixas de reagente."); }} className="pill px-4 py-2.5 text-sm font-bold">Ver no Financeiro →</button></div></div>
      <div className="mt-4 overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Exame</th><th className="py-2 pr-3">Qtd. baixada</th><th className="py-2 pr-3">Custo total</th><th className="py-2">Custo médio / unidade</th></tr></thead><tbody>{custoPorExame.map(c => <tr key={c.exam} className="border-t border-[var(--line)]"><td className="py-3 pr-3 font-bold">{c.exam}</td><td className="py-3 pr-3">{c.qty}</td><td className="py-3 pr-3 font-bold">{money(c.total)}</td><td className="py-3">{money(c.total / Math.max(1, c.qty))}</td></tr>)}</tbody></table></div><p className="mt-3 text-sm">Total lançado no Financeiro: <strong>{money(totalBaixas)}</strong> · {baixas.length} baixa(s) registradas.</p></div>}
    {tab === "Dashboard Executivo" && <div className="mt-4"><h4 className="font-extrabold">Dashboard Executivo — visão consolidada</h4><p className="mt-1 text-sm text-[var(--muted)]">Produção, custo e receita do Laboratório + Clínica lado a lado, com total do hospital. Valores do mês (Junho/2026).</p><div className="mt-4 grid gap-3 md:grid-cols-3">{[...exec, { name: "Total do hospital", producao: execTotal.producao, custo: execTotal.custo, receita: execTotal.receita }].map(s => <article key={s.name} className="soft p-4"><h5 className="font-extrabold">{s.name}</h5><p className="mt-3 text-sm">Produção <strong className="float-right">{s.producao.toLocaleString("pt-BR")}</strong></p><p className="mt-1 text-sm">Custo <strong className="float-right">{money(s.custo)}</strong></p><p className="mt-1 text-sm">Receita <strong className="float-right">{money(s.receita)}</strong></p><p className="mt-2 border-t border-[var(--line)] pt-2 text-sm">Margem <strong className="float-right text-[var(--ok)]">{money(s.receita - s.custo)} · {Math.round((s.receita - s.custo) / s.receita * 100)}%</strong></p></article>)}</div><div className="mt-4 h-[260px]"><ResponsiveContainer><BarChart data={exec}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="name" tick={{ fill: "var(--muted)", fontSize: 12 }} /><YAxis tick={{ fill: "var(--muted)", fontSize: 12 }} /><Tooltip contentStyle={tipStyle} /><Bar dataKey="receita" fill="#0F5F5C" radius={[7, 7, 0, 0]} name="Receita (R$)" /><Bar dataKey="custo" fill="#E4A11B" radius={[7, 7, 0, 0]} name="Custo (R$)" /></BarChart></ResponsiveContainer></div></div>}
  </div>;
}

/* ---------- SEGURANÇA E CONFORMIDADE — LABORATÓRIO ---------- */
type AuditEvent = { id: string; when: string; type: string; patientName: string; exam: string; user: string; before: string; after: string };
type SignedReport = { id: string; patientName: string; exam: string; signedAt: string; hash: string; code: string; cert: string; version: number; copies: number };
function SegurancaLabModule({ patients, onNotice }: { patients: Patient[]; onNotice: (m: string) => void }) {
  const [tab, setTab] = useState("Trilha de auditoria");
  const [audits, setAudits] = useState<AuditEvent[]>([
    { id: "au-1", when: "12/06/2026, 10:32", type: "Resultado validado", patientName: "Maria Aparecida Silva", exam: "Glicemia em jejum", user: "Dra. Ana Paula — Clínica Geral", before: "Resultado: pendente de validação", after: "Resultado: 112 mg/dL — validado" },
    { id: "au-2", when: "12/06/2026, 09:48", type: "Laudo retificado", patientName: "Carlos Eduardo Oliveira", exam: "Colesterol total e frações", user: "Dr. Roberto — Cardiologia", before: "Laudo v1: LDL 98 mg/dL", after: "Laudo v2: LDL 102 mg/dL — unidade corrigida" },
    { id: "au-3", when: "12/06/2026, 09:20", type: "Pedido criado", patientName: "Fernanda Lima Almeida", exam: "Hemograma completo", user: "Téc. Juliana — Coleta", before: "Sem pedido", after: "Pedido LAB-2026-1041 — Prioritário" },
    { id: "au-4", when: "12/06/2026, 08:55", type: "Acesso a resultado", patientName: "Rosa Maria Ferreira", exam: "Creatinina", user: "Enf. Ricardo — Clínica", before: "Resultado não acessado", after: "Resultado acessado para conferência no leito" },
    { id: "au-5", when: "11/06/2026, 16:40", type: "2ª via emitida", patientName: "João Pedro Santos", exam: "Hemograma completo", user: "Recepção — Laboratório", before: "1 via emitida", after: "2ª via emitida — motivo: paciente perdeu a 1ª via" },
  ]);
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState("Todos");
  const [reports, setReports] = useState<SignedReport[]>([
    { id: "la-1", patientName: "Maria Aparecida Silva", exam: "Glicemia em jejum", signedAt: "12/06/2026, 10:32", hash: "SHA-256 · 9f3a…c41d", code: "GOT-2026-1041-A", cert: "ICP-Brasil · Certificado A3 — Dra. Ana Paula", version: 2, copies: 1 },
    { id: "la-2", patientName: "Carlos Eduardo Oliveira", exam: "Colesterol total e frações", signedAt: "12/06/2026, 09:48", hash: "SHA-256 · 71bd…e902", code: "GOT-2026-1042-B", cert: "ICP-Brasil · Certificado A3 — Dr. Roberto", version: 2, copies: 0 },
    { id: "la-3", patientName: "Fernanda Lima Almeida", exam: "Hemograma completo", signedAt: "12/06/2026, 09:20", hash: "SHA-256 · a08c…5f17", code: "GOT-2026-1043-C", cert: "ICP-Brasil · Certificado A1 — Dra. Juliana", version: 1, copies: 2 },
    { id: "la-4", patientName: "Rosa Maria Ferreira", exam: "Creatinina", signedAt: "11/06/2026, 17:05", hash: "SHA-256 · d44e…881a", code: "GOT-2026-1040-D", cert: "ICP-Brasil · Certificado A3 — Dra. Ana Paula", version: 1, copies: 1 },
  ]);
  const [verifiedId, setVerifiedId] = useState<string | null>(null);
  const [accessForm, setAccessForm] = useState({ patientId: patients[0]?.id || "p1", exam: "Glicemia em jejum", user: "Enf. Ricardo — Clínica" });
  const [rectForm, setRectForm] = useState({ reportId: "la-1", reason: "", newText: "" });
  const inputCls = "w-full rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-sm outline-none";
  const labelCls = "block text-sm font-bold";
  useEffect(() => { let alive = true; (async () => { try { const d: any = await api("records.list", { collection: "gottcured_lab_seguranca" }); if (!alive || !d?.records?.length) return; const evs: AuditEvent[] = []; for (const r of d.records) { const v = r.value || {}; if (v.kind === "audit" && v.event) evs.push(v.event); } if (evs.length) setAudits(prev => [...evs, ...prev]); } catch { } })(); return () => { alive = false; }; }, []);
  async function logAudit(event: AuditEvent) { setAudits(prev => [event, ...prev]); try { await api("records.create", { collection: "gottcured_lab_seguranca", value: { kind: "audit", event, createdAt: new Date().toISOString() }, idempotency_key: `gottcured-lab-seg-${event.id}` }); } catch { } }
  async function registerAccess() { const p = patients.find(x => x.id === accessForm.patientId) || patients[0]; if (!p) return; const ev: AuditEvent = { id: `au-${Date.now()}`, when: new Date().toLocaleString("pt-BR"), type: "Acesso a resultado", patientName: p.name, exam: accessForm.exam, user: accessForm.user, before: "Resultado não acessado nesta sessão", after: `Resultado acessado por ${accessForm.user}` }; await logAudit(ev); onNotice(`Acesso registrado na trilha de auditoria: ${p.name} — ${accessForm.exam}.`); }
  async function emitCopy(r: SignedReport) { const next = { ...r, copies: r.copies + 1 }; setReports(prev => prev.map(x => x.id === r.id ? next : x)); const ev: AuditEvent = { id: `au-${Date.now()}`, when: new Date().toLocaleString("pt-BR"), type: "2ª via emitida", patientName: r.patientName, exam: r.exam, user: "Recepção — Laboratório", before: `${r.copies} via(s) emitida(s)`, after: `${r.copies + 1} via(s) emitida(s) — 2ª via` }; await logAudit(ev); onNotice(`2ª via emitida para ${r.patientName} — ${r.exam}. Evento registrado na auditoria.`); }
  async function rectify() { const r = reports.find(x => x.id === rectForm.reportId); if (!r || !rectForm.reason.trim() || !rectForm.newText.trim()) { onNotice("Selecione o laudo e informe o motivo e o novo texto da retificação."); return; } const next = { ...r, version: r.version + 1 }; setReports(prev => prev.map(x => x.id === r.id ? next : x)); const ev: AuditEvent = { id: `au-${Date.now()}`, when: new Date().toLocaleString("pt-BR"), type: "Laudo retificado", patientName: r.patientName, exam: r.exam, user: "Dra. Ana Paula — Clínica Geral", before: `Laudo v${r.version}`, after: `Laudo v${r.version + 1}: ${rectForm.newText.trim()} — motivo: ${rectForm.reason.trim()}` }; await logAudit(ev); setRectForm({ ...rectForm, reason: "", newText: "" }); onNotice(`Laudo retificado: ${r.exam} passou para v${r.version + 1}. O laudo original foi mantido na trilha.`); }
  const filtered = audits.filter(a => (typeFilter === "Todos" || a.type === typeFilter) && (!search.trim() || (a.patientName + a.exam + a.user + a.type).toLowerCase().includes(search.toLowerCase())));
  return <div>
    <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">{["Trilha de auditoria", "Assinatura digital"].map(t => <button key={t} onClick={() => setTab(t)} className={`pill shrink-0 px-3.5 py-2 text-[13px] font-semibold ${tab === t ? "chip-active" : ""}`}>{t}</button>)}</div>
    {tab === "Trilha de auditoria" && <div className="mt-4"><div className="flex flex-wrap gap-2"><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar por paciente, exame ou usuário…" className={`${inputCls} min-w-[220px] flex-1`} aria-label="Buscar na auditoria" /><select value={typeFilter} onChange={e => setTypeFilter(e.target.value)} className="rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-sm"><option>Todos</option><option>Pedido criado</option><option>Resultado validado</option><option>Laudo retificado</option><option>Acesso a resultado</option><option>2ª via emitida</option></select></div>
      <div className="soft mt-3 p-4"><h4 className="font-extrabold">Registrar acesso a resultado</h4><div className="mt-3 grid gap-2 sm:grid-cols-3"><label className={labelCls}>Paciente<select value={accessForm.patientId} onChange={e => setAccessForm({ ...accessForm, patientId: e.target.value })} className={`${inputCls} mt-1`}>{patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label className={labelCls}>Exame<input value={accessForm.exam} onChange={e => setAccessForm({ ...accessForm, exam: e.target.value })} className={`${inputCls} mt-1`} /></label><label className={labelCls}>Quem acessou<input value={accessForm.user} onChange={e => setAccessForm({ ...accessForm, user: e.target.value })} className={`${inputCls} mt-1`} /></label></div><button onClick={registerAccess} className="mt-3 rounded-full bg-[var(--primary)] px-5 py-2.5 text-sm font-bold text-white">Registrar acesso</button></div>
      <p className="mt-3 text-[13px] text-[var(--muted)]">{filtered.length} evento(s) na trilha — ordem cronológica, com quem, quando e o que mudou (antes / depois).</p><div className="mt-3 space-y-2">{filtered.map(a => <article key={a.id} className="soft p-4"><div className="flex flex-wrap justify-between gap-2"><p className="font-bold text-sm">{a.type} — {a.exam}</p><span className="text-[12px] text-[var(--muted)]">{a.when}</span></div><p className="mt-1 text-sm text-[var(--muted)]">{a.patientName} · {a.user}</p><p className="mt-2 text-sm"><strong>Antes:</strong> {a.before}</p><p className="text-sm"><strong>Depois:</strong> {a.after}</p></article>)}{!filtered.length && <p className="text-sm text-[var(--muted)]">Nenhum evento com esses filtros.</p>}</div></div>}
    {tab === "Assinatura digital" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Cada laudo assinado carrega selo de validade jurídica, hash e código de verificação. A verificação é simulada: confere o código e o hash registrados no laudo.</p>
      <div className="soft mt-3 p-4"><h4 className="font-extrabold">Retificar laudo assinado</h4><div className="mt-3 grid gap-2 sm:grid-cols-3"><label className={labelCls}>Laudo<select value={rectForm.reportId} onChange={e => setRectForm({ ...rectForm, reportId: e.target.value })} className={`${inputCls} mt-1`}>{reports.map(r => <option key={r.id} value={r.id}>{r.patientName} — {r.exam} (v{r.version})</option>)}</select></label><label className={labelCls}>Motivo<input value={rectForm.reason} onChange={e => setRectForm({ ...rectForm, reason: e.target.value })} className={`${inputCls} mt-1`} placeholder="Motivo da retificação" /></label><label className={labelCls}>Novo texto<input value={rectForm.newText} onChange={e => setRectForm({ ...rectForm, newText: e.target.value })} className={`${inputCls} mt-1`} placeholder="Novo texto corrigido" /></label></div><button onClick={rectify} className="mt-3 rounded-full bg-[var(--primary)] px-5 py-2.5 text-sm font-bold text-white">Retificar laudo</button></div>
      <div className="mt-4 space-y-3">{reports.map(r => <article key={r.id} className="soft p-4"><div className="flex flex-wrap justify-between gap-2"><div><p className="font-bold">{r.patientName} · {r.exam}</p><p className="mt-1 text-sm text-[var(--muted)]">Assinado em {r.signedAt} · Versão {r.version} · {r.copies} via(s)</p></div><span className="h-fit rounded-full bg-[var(--primary-soft)] px-3 py-1.5 text-[12px] font-bold text-[var(--primary)]">✓ Assinatura digital com validade jurídica</span></div><p className="mt-2 text-sm">Hash: <strong>{r.hash}</strong> · Código de verificação: <strong>{r.code}</strong></p><p className="mt-1 text-sm text-[var(--muted)]">Certificado: {r.cert}</p><div className="mt-3 flex flex-wrap gap-2"><button onClick={() => { setVerifiedId(r.id); onNotice(`Autenticidade verificada (simulação): ${r.code} corresponde ao laudo de ${r.patientName}.`); }} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Verificar autenticidade</button><button onClick={() => emitCopy(r)} className="pill px-4 py-2 text-[13px] font-bold">Emitir 2ª via</button></div>{verifiedId === r.id && <p className="mt-3 rounded-xl bg-[#D9EEDD] px-3 py-2 text-sm font-bold text-[#1E5B2A]">✓ Autenticidade confirmada (simulação) — código {r.code} · hash {r.hash} · certificado {r.cert} · laudo íntegro, sem alteração após a assinatura.</p>}</article>)}</div></div>}
  </div>;
}

/* ---------- RELATÓRIOS E VISUALIZAÇÃO — LABORATÓRIO ---------- */
function RelatoriosLabModule({ onNotice }: { onNotice: (m: string) => void }) {
  const [tab, setTab] = useState("Dashboard");
  const [periodo, setPeriodo] = useState("Últimos 30 dias");
  const [area, setArea] = useState("Todas");
  const [exame, setExame] = useState("Todos");
  const [equipamento, setEquipamento] = useState("Todos");
  const [convenio, setConvenio] = useState("Todos");
  const [setor, setSetor] = useState("Todos");
  const [trendMode, setTrendMode] = useState("Diária");
  const [heatCell, setHeatCell] = useState<{ day: string; hour: string; value: number } | null>(null);
  const [exports, setExports] = useState<{ id: string; name: string; format: string; when: string }[]>([]);
  const inputCls = "w-full rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-sm outline-none";
  const labelCls = "block text-sm font-bold";
  const periodFactor = periodo === "Hoje" ? 0.043 : periodo === "Últimos 7 dias" ? 0.24 : periodo === "Junho/2026" ? 1 : 1;
  const areaFactor = area === "Todas" ? 1 : area === "Hematologia" ? 0.28 : area === "Bioquímica" ? 0.23 : 0.12;
  const setorFactor = setor === "Todos" ? 1 : setor === "Clínica" ? 0.58 : setor === "Internação" ? 0.26 : 0.16;
  const convFactor = convenio === "Todos" ? 1 : convenio === "Unimed" ? 0.34 : convenio === "Amil" ? 0.22 : convenio === "Bradesco" ? 0.18 : convenio === "SUS" ? 0.16 : 0.10;
  const f = periodFactor * areaFactor * setorFactor * (convenio === "Todos" ? 1 : convFactor);
  const exames = Math.round(29840 * f);
  const receita = Math.round(486000 * f);
  const tat = area === "Bioquímica" ? "4h 48min" : area === "Hematologia" ? "6h 12min" : "9h 36min";
  const filterLabel = `Período: ${periodo} · Área: ${area} · Exame: ${exame} · Equipamento: ${equipamento} · Convênio: ${convenio} · Setor: ${setor}`;
  useEffect(() => { let alive = true; (async () => { try { const d: any = await api("records.list", { collection: "gottcured_lab_relatorios" }); if (!alive || !d?.records?.length) return; const ex: { id: string; name: string; format: string; when: string }[] = []; for (const r of d.records) { const v = r.value || {}; if (v.kind === "exportacao") ex.push({ id: String(r.id), name: v.name, format: v.format, when: v.when }); } if (ex.length) setExports(ex); } catch { } })(); return () => { alive = false; }; }, []);
  async function exportReport(name: string, format: "PDF" | "Planilha") { const rec = { id: `exp-${Date.now()}`, name, format, when: new Date().toLocaleString("pt-BR") }; setExports(prev => [rec, ...prev]); try { await api("records.create", { collection: "gottcured_lab_relatorios", value: { kind: "exportacao", name, format, when: rec.when, filters: filterLabel, createdAt: new Date().toISOString() }, idempotency_key: `gottcured-lab-exp-${rec.id}` }); onNotice(`Exportação registrada: ${name} — ${format}. ${filterLabel}. O arquivo é gerado com nome, período e filtros aplicados.`); } catch { onNotice(`Exportação preparada (simulação): ${name} — ${format}. ${filterLabel}.`); } }
  const trendDaily = [{ d: "02/06", v: 1180 }, { d: "03/06", v: 1242 }, { d: "04/06", v: 1210 }, { d: "05/06", v: 1318 }, { d: "08/06", v: 1284 }, { d: "09/06", v: 1268 }, { d: "10/06", v: 1332 }, { d: "11/06", v: 1296 }, { d: "12/06", v: 1284 }].map(x => ({ ...x, v: Math.max(1, Math.round(x.v * (area === "Todas" ? 1 : areaFactor) * setorFactor)) }));
  const trendMonthly = [{ d: "Jan", v: 26840 }, { d: "Fev", v: 27420 }, { d: "Mar", v: 29180 }, { d: "Abr", v: 28460 }, { d: "Mai", v: 30620 }, { d: "Jun", v: 29840 }].map(x => ({ ...x, v: Math.max(1, Math.round(x.v * (area === "Todas" ? 1 : areaFactor) * setorFactor)) }));
  const trendAnnual = [{ d: "2022", v: 284000 }, { d: "2023", v: 312000 }, { d: "2024", v: 338000 }, { d: "2025", v: 356000 }, { d: "2026", v: 372000 }].map(x => ({ ...x, v: Math.max(1, Math.round(x.v * (area === "Todas" ? 1 : areaFactor) * setorFactor)) }));
  const trendData = trendMode === "Diária" ? trendDaily : trendMode === "Mensal" ? trendMonthly : trendAnnual;
  const days = ["2ª-feira", "3ª-feira", "4ª-feira", "5ª-feira", "6ª-feira", "Sábado", "Domingo"];
  const hours = ["7h–8h", "8h–9h", "9h–10h", "10h–11h", "11h–12h", "12h–14h"];
  const heat: Record<string, number> = {}; days.forEach((d, di) => hours.forEach((h, hi) => { heat[`${d}|${h}`] = Math.round((di === 0 && hi === 2 ? 182 : di === 5 ? 42 : 68 + di * 6 + hi * 18) * (area === "Todas" ? 1 : areaFactor)); }));
  const prodByArea = [{ area: "Hematologia", exames: 8420, receita: 142000, custo: 98000 }, { area: "Bioquímica", exames: 6980, receita: 118000, custo: 76000 }, { area: "Hormonal", exames: 3320, receita: 86000, custo: 54000 }, { area: "Imunologia", exames: 2740, receita: 64000, custo: 42000 }, { area: "Urinálise", exames: 2980, receita: 38000, custo: 24000 }].filter(r => area === "Todas" || r.area === area).map(r => ({ ...r, exames: Math.max(1, Math.round(r.exames * f / Math.max(1, periodFactor) * periodFactor)), receita: Math.round(r.receita * f), custo: Math.round(r.custo * f) }));
  const amostras = [{ tipo: "Coletadas", qtd: 31240 }, { tipo: "Recebidas", qtd: 30980 }, { tipo: "Descartadas", qtd: 184 }, { tipo: "Recolectas", qtd: 742 }].map(r => ({ ...r, qtd: Math.max(1, Math.round(r.qtd * f)) }));
  const lotes = [{ lote: "LOTE-GLI-042", reagente: "Reagente Glicose", pacientes: 342, resultados: 342, custo: 1094 }, { lote: "LOTE-HEM-118", reagente: "Reagente Hemograma", pacientes: 486, resultados: 486, custo: 1992 }, { lote: "LOTE-TSH-031", reagente: "Reagente TSH", pacientes: 128, resultados: 128, custo: 896 }];
  const TABS = ["Dashboard", "Tendência", "Mapa de calor", "Produção", "Amostras", "Rastreabilidade", "Anual 2026"];
  const exportButtons = (name: string) => <div className="flex flex-wrap gap-2"><button onClick={() => exportReport(name, "PDF")} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Exportar PDF</button><button onClick={() => exportReport(name, "Planilha")} className="pill px-4 py-2 text-[13px] font-bold">Exportar Planilha</button></div>;
  return <div>
    <div className="rounded-2xl bg-[var(--primary-soft)] px-4 py-3 text-sm font-bold text-[var(--primary)]">Filtros globais — afetam KPIs, gráficos e todos os relatórios abaixo.</div>
    <div className="mt-3 grid gap-2 sm:grid-cols-3 lg:grid-cols-6"><label className={labelCls}>Período<select value={periodo} onChange={e => setPeriodo(e.target.value)} className={`${inputCls} mt-1`}><option>Hoje</option><option>Últimos 7 dias</option><option>Últimos 30 dias</option><option>Junho/2026</option></select></label><label className={labelCls}>Área<select value={area} onChange={e => setArea(e.target.value)} className={`${inputCls} mt-1`}><option>Todas</option><option>Hematologia</option><option>Bioquímica</option><option>Hormonal</option><option>Imunologia</option></select></label><label className={labelCls}>Exame<select value={exame} onChange={e => setExame(e.target.value)} className={`${inputCls} mt-1`}><option>Todos</option><option>Hemograma completo</option><option>Glicemia em jejum</option><option>TSH</option><option>Colesterol total e frações</option></select></label><label className={labelCls}>Equipamento<select value={equipamento} onChange={e => setEquipamento(e.target.value)} className={`${inputCls} mt-1`}><option>Todos</option><option>Analisador L-01</option><option>Analisador L-02</option><option>Centrífuga C-05</option><option>Autoclave A-03</option></select></label><label className={labelCls}>Convênio<select value={convenio} onChange={e => setConvenio(e.target.value)} className={`${inputCls} mt-1`}><option>Todos</option><option>Particular</option><option>Unimed</option><option>Amil</option><option>Bradesco</option><option>SUS</option></select></label><label className={labelCls}>Setor solicitante<select value={setor} onChange={e => setSetor(e.target.value)} className={`${inputCls} mt-1`}><option>Todos</option><option>Clínica</option><option>Internação</option><option>Externo</option></select></label></div>
    <p className="mt-2 text-[13px] text-[var(--muted)]">{filterLabel}</p>
    <div className="mt-4 flex gap-2 overflow-x-auto pb-1 no-scrollbar">{TABS.map(t => <button key={t} onClick={() => setTab(t)} className={`pill shrink-0 px-3.5 py-2 text-[13px] font-semibold ${tab === t ? "chip-active" : ""}`}>{t}</button>)}</div>
    {tab === "Dashboard" && <div className="mt-4"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><div className="soft p-4"><p className="text-xs text-[var(--muted)]">Exames</p><p className="kpi-num mt-1">{exames.toLocaleString("pt-BR")}</p><p className="mt-1 text-[13px] text-[var(--muted)]">No período filtrado.</p></div><div className="soft p-4"><p className="text-xs text-[var(--muted)]">TAT médio</p><p className="kpi-num mt-1">{tat}</p><p className="mt-1 text-[13px] text-[var(--muted)]">Tempo de liberação.</p></div><div className="soft p-4"><p className="text-xs text-[var(--muted)]">% no prazo</p><p className="kpi-num mt-1">94,2%</p><p className="mt-1 text-[13px] text-[var(--muted)]">Meta: 95%.</p></div><div className="soft p-4"><p className="text-xs text-[var(--muted)]">Receita</p><p className="kpi-num mt-1">{money(receita)}</p><p className="mt-1 text-[13px] text-[var(--muted)]">No período filtrado.</p></div><div className="soft p-4"><p className="text-xs text-[var(--muted)]">Recolectas</p><p className="kpi-num mt-1">2,4%</p><p className="mt-1 text-[13px] text-[var(--muted)]">Meta: &lt; 3%.</p></div><div className="soft p-4"><p className="text-xs text-[var(--muted)]">Satisfação</p><p className="kpi-num mt-1">4,7 / 5</p><p className="mt-1 text-[13px] text-[var(--muted)]">Pesquisa pós-atendimento.</p></div></div>{exportButtons("Dashboard setorial do Laboratório")}</div>}
    {tab === "Tendência" && <div className="mt-4"><div className="flex gap-2">{["Diária", "Mensal", "Anual"].map(m => <button key={m} onClick={() => setTrendMode(m)} className={`pill px-4 py-2 text-[13px] font-bold ${trendMode === m ? "chip-active" : ""}`}>{m}</button>)}</div><div className="mt-3 h-[280px]"><ResponsiveContainer><LineChart data={trendData}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="d" tick={{ fill: "var(--muted)", fontSize: 12 }} /><YAxis tick={{ fill: "var(--muted)", fontSize: 12 }} /><Tooltip contentStyle={tipStyle} /><Line type="monotone" dataKey="v" stroke="#0F5F5C" strokeWidth={2.5} name="Exames" /></LineChart></ResponsiveContainer></div><p className="mt-2 text-sm text-[var(--muted)]">Tendência {trendMode.toLowerCase()} de exames — reage aos filtros globais acima.</p>{exportButtons(`Tendência ${trendMode} — Laboratório`)}</div>}
    {tab === "Mapa de calor" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">Coletas por dia da semana × horário. Clique numa célula para ver o detalhe.</p><div className="mt-3 overflow-x-auto"><table className="w-full min-w-[560px] text-center text-sm"><thead><tr><th className="py-2 text-left">Dia \ Hora</th>{hours.map(h => <th key={h} className="py-2">{h}</th>)}</tr></thead><tbody>{days.map(d => <tr key={d} className="border-t border-[var(--line)]"><td className="py-2 text-left font-bold">{d}</td>{hours.map(h => { const v = heat[`${d}|${h}`]; const hot = v >= 150; return <td key={h} className="py-1"><button onClick={() => { setHeatCell({ day: d, hour: h, value: v }); onNotice(`Mapa de calor: ${d} · ${h} — ${v} coletas.`); }} className={`w-full rounded-lg px-1 py-2 text-[13px] font-bold ${hot ? "bg-[#C83E3E] text-white" : v >= 100 ? "bg-[#E4A11B] text-white" : "bg-[var(--primary-soft)] text-[var(--primary)]"}`}>{v}</button></td>; })}</tr>)}</tbody></table></div>{heatCell && <div className="soft mt-3 p-4"><p className="font-extrabold">Detalhe — {heatCell.day} · {heatCell.hour}</p><p className="mt-1 text-sm text-[var(--muted)]">{heatCell.value} coletas previstas/realizadas · {heatCell.value >= 150 ? "Pico — reforçar coleta e recepção." : heatCell.value >= 100 ? "Movimento alto." : "Movimento moderado."} · Filtros: {filterLabel}</p></div>}{exportButtons("Mapa de calor de coletas")}</div>}
    {tab === "Produção" && <div className="mt-4"><h4 className="font-extrabold">Relatório de Produção</h4><div className="mt-3 h-[240px]"><ResponsiveContainer><BarChart data={prodByArea}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="area" tick={{ fill: "var(--muted)", fontSize: 12 }} /><YAxis tick={{ fill: "var(--muted)", fontSize: 12 }} /><Tooltip contentStyle={tipStyle} /><Bar dataKey="exames" fill="#0F5F5C" radius={[7, 7, 0, 0]} name="Exames" /></BarChart></ResponsiveContainer></div><div className="mt-3 overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Área</th><th className="py-2 pr-3">Exames</th><th className="py-2 pr-3">Receita</th><th className="py-2">Custo</th></tr></thead><tbody>{prodByArea.map(r => <tr key={r.area} className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">{r.area}</td><td className="py-2 pr-3">{r.exames.toLocaleString("pt-BR")}</td><td className="py-2 pr-3">{money(r.receita)}</td><td className="py-2">{money(r.custo)}</td></tr>)}</tbody></table></div><div className="mt-3">{exportButtons("Relatório de Produção — Laboratório")}</div></div>}
    {tab === "Amostras" && <div className="mt-4"><h4 className="font-extrabold">Relatório de Amostras</h4><div className="mt-3 h-[240px]"><ResponsiveContainer><BarChart data={amostras}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="tipo" tick={{ fill: "var(--muted)", fontSize: 12 }} /><YAxis tick={{ fill: "var(--muted)", fontSize: 12 }} /><Tooltip contentStyle={tipStyle} /><Bar dataKey="qtd" fill="#2C8D84" radius={[7, 7, 0, 0]} name="Amostras" /></BarChart></ResponsiveContainer></div><div className="mt-3 overflow-x-auto"><table className="w-full min-w-[420px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Etapa</th><th className="py-2">Quantidade</th></tr></thead><tbody>{amostras.map(r => <tr key={r.tipo} className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">{r.tipo}</td><td className="py-2">{r.qtd.toLocaleString("pt-BR")}</td></tr>)}</tbody></table></div><div className="mt-3">{exportButtons("Relatório de Amostras — Laboratório")}</div></div>}
    {tab === "Rastreabilidade" && <div className="mt-4"><h4 className="font-extrabold">Relatório de Rastreabilidade — por lote</h4><div className="mt-3 h-[240px]"><ResponsiveContainer><BarChart data={lotes}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="lote" tick={{ fill: "var(--muted)", fontSize: 11 }} /><YAxis tick={{ fill: "var(--muted)", fontSize: 12 }} /><Tooltip contentStyle={tipStyle} /><Bar dataKey="pacientes" fill="#0F5F5C" radius={[7, 7, 0, 0]} name="Pacientes" /></BarChart></ResponsiveContainer></div><div className="mt-3 overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Lote</th><th className="py-2 pr-3">Reagente</th><th className="py-2 pr-3">Pacientes</th><th className="py-2 pr-3">Resultados</th><th className="py-2">Custo</th></tr></thead><tbody>{lotes.map(r => <tr key={r.lote} className="border-t border-[var(--line)]"><td className="py-2 pr-3 font-bold">{r.lote}</td><td className="py-2 pr-3">{r.reagente}</td><td className="py-2 pr-3">{r.pacientes}</td><td className="py-2 pr-3">{r.resultados}</td><td className="py-2">{money(r.custo)}</td></tr>)}</tbody></table></div><div className="mt-3">{exportButtons("Relatório de Rastreabilidade — Laboratório")}</div></div>}
    {tab === "Anual 2026" && <div className="mt-4"><h4 className="font-extrabold">Relatório Anual de Gestão 2026 — Laboratório</h4><div className="mt-3 grid gap-3 sm:grid-cols-3"><div className="soft p-4 text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">Exames no ano</p><p className="mt-1 text-[24px] font-extrabold">372 mil</p></div><div className="soft p-4 text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">Receita</p><p className="mt-1 text-[24px] font-extrabold">R$ 5,8 mi</p></div><div className="soft p-4 text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">Custos</p><p className="mt-1 text-[24px] font-extrabold">R$ 3,7 mi</p></div><div className="soft p-4 text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">Margem</p><p className="mt-1 text-[24px] font-extrabold">36%</p></div><div className="soft p-4 text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">TAT médio</p><p className="mt-1 text-[24px] font-extrabold">9h 36min</p></div><div className="soft p-4 text-center"><p className="text-[11px] font-bold uppercase text-[var(--muted)]">Satisfação</p><p className="mt-1 text-[24px] font-extrabold">4,7 / 5</p></div></div><div className="mt-4 grid gap-3 md:grid-cols-2"><div className="soft p-4"><h5 className="font-extrabold">Destaques de 2026</h5><ul className="mt-2 list-disc space-y-1 pl-5 text-sm leading-6"><li>Volume cresceu 4,5% em relação a 2025, com pico em campanhas de check-up.</li><li>% no prazo subiu para 94,2% após priorização da fila de urgências.</li><li>Recolectas mantidas em 2,4%, abaixo da meta de 3%.</li></ul></div><div className="soft p-4"><h5 className="font-extrabold">Pontos de atenção — próximo ano</h5><ul className="mt-2 list-disc space-y-1 pl-5 text-sm leading-6"><li>Renovar contrato de reagentes e revisar ponto de reposição de Glicose.</li><li>Reduzir TAT de Hemograma para 3h no pico da manhã.</li><li>Ampliar coleta domiciliar e resultado no leito para internação.</li></ul></div></div><div className="mt-3">{exportButtons("Relatório Anual de Gestão 2026 — Laboratório")}</div></div>}
    {exports.length > 0 && <div className="mt-5"><h4 className="font-extrabold">Exportações registradas ({exports.length})</h4><div className="mt-2 space-y-1">{exports.map(e => <p key={e.id} className="soft p-3 text-sm"><strong>{e.name}</strong> · {e.format} · {e.when}</p>)}</div></div>}
  </div>;
}
export default function App() {


  const [theme, setTheme] = useState<"light" | "dark">("light");
  const [view, setView] = useState<View>({ kind: "home" });
  const [query, setQuery] = useState("");
  const [homeQuery, setHomeQuery] = useState("");
  const [filter, setFilter] = useState("Todos");
  const [alerts, setAlerts] = useState(INITIAL_ALERTS);
  const [readIds, setReadIds] = useState<Set<string>>(new Set());
  const [snoozed, setSnoozed] = useState<Set<string>>(new Set());
  const [recordMap, setRecordMap] = useState<Record<string, string>>({});
  const [bellOpen, setBellOpen] = useState(false);
  const [severity, setSeverity] = useState("Todas");
  const [sectorFilter, setSectorFilter] = useState("Todos");
  const [alertSearch, setAlertSearch] = useState("");
  const [alertGroup, setAlertGroup] = useState<"todos" | "previsoes">("todos");
  const [alertKindFilter, setAlertKindFilter] = useState("Todos");
  const [ignoredIds, setIgnoredIds] = useState<Set<string>>(new Set());
  const [resolvedIds, setResolvedIds] = useState<Set<string>>(new Set());
  const [predictiveDone, setPredictiveDone] = useState<Set<string>>(new Set());
  const [predictiveChoice, setPredictiveChoice] = useState<Record<string, string>>({});
  const [toast, setToast] = useState("");
  const [notice, setNotice] = useState("");
  const [searchHistory, setSearchHistory] = useState<string[]>([]);
  const [profileRecordId, setProfileRecordId] = useState<string | null>(null);
  const [historySaving, setHistorySaving] = useState(true);
  const [patients, setPatients] = useState<Patient[]>(SEED_PATIENTS);
  const [selectedPatientId, setSelectedPatientId] = useState<string | null>(null);

  async function saveProfile(patch: { historySaving?: boolean }) {
    const value = { historySaving: patch.historySaving !== undefined ? patch.historySaving : historySaving, updatedAt: new Date().toISOString() };
    try {
      if (profileRecordId) await api("records.replace", { collection: "gottcured_profile", id: profileRecordId, value });
      else { const created: any = await api("records.create", { collection: "gottcured_profile", value, idempotency_key: "gottcured-profile-main" }); if (created?.id) setProfileRecordId(created.id); }
      if (patch.historySaving !== undefined) setHistorySaving(patch.historySaving);
    } catch {
      if (patch.historySaving !== undefined) setHistorySaving(patch.historySaving);
      setNotice("Preferência aplicada nesta sessão. A sincronização será tentada novamente.");
    }
  }
  const [saving, setSaving] = useState(false);
  const [aiCycle, setAiCycle] = useState(0);
  const [preventiva, setPreventiva] = useState(72);
  const [equipe, setEquipe] = useState(9);
  const [investimento, setInvestimento] = useState(120);
  const [sectorTab, setSectorTab] = useState("Visão geral");
  const toastTimer = useRef<number | null>(null);

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const data: any = await api("records.list", { collection: "gottcured_profile" });
        if (!alive || !data?.records?.length) return;
        const v = data.records[0].value || {};
        setProfileRecordId(data.records[0].id);
        if (typeof v.historySaving === "boolean") setHistorySaving(v.historySaving);
      } catch { }
    })();
    return () => { alive = false; };
  }, []);

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const data: any = await api("records.list", { collection: "gottcured_alert_state" });
        if (!alive || !data?.records) return;
        const read = new Set<string>(); const snooze = new Set<string>(); const map: Record<string, string> = {};
        for (const r of data.records) { const v = r.value || {}; if (v.alertId) { map[v.alertId] = r.id; if (v.status === "read") read.add(v.alertId); if (v.status === "snoozed") snooze.add(v.alertId); if (v.status === "ignored") setIgnoredIds(prev => new Set(prev).add(v.alertId)); if (v.status === "resolved") setResolvedIds(prev => new Set(prev).add(v.alertId)); if (v.status === "done") setPredictiveDone(prev => new Set(prev).add(v.alertId)); } }
        setReadIds(read); setSnoozed(snooze); setRecordMap(map);
      } catch { }
    })();
    return () => { alive = false; };
  }, []);

  // Carrega pacientes salvos e mescla com os exemplos (sem duplicar)
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const data: any = await api("records.list", { collection: "gottcured_patients" });
        if (!alive || !data?.records?.length) return;
        setPatients(prev => {
          const byId = new Map(prev.map(p => [p.id, p]));
          for (const r of data.records) {
            const v = r.value || {};
            if (!v.id || !v.name) continue;
            const existing = byId.get(v.id);
            byId.set(v.id, { ...(existing || {}), ...v, recordId: r.id } as Patient);
          }
          return Array.from(byId.values());
        });
      } catch { }
    })();
    return () => { alive = false; };
  }, []);

  async function addPatient(p: Patient) {
    try {
      const created: any = await api("records.create", { collection: "gottcured_patients", value: { ...p, createdAt: new Date().toISOString() }, idempotency_key: `gottcured-patient-${p.id}` });
      setPatients(prev => [...prev, { ...p, recordId: created?.id }]);
      setNotice(`Paciente ${p.name} cadastrado com sucesso.`);
    } catch {
      setPatients(prev => [...prev, p]);
      setNotice(`Paciente ${p.name} cadastrado nesta sessão. A sincronização será tentada novamente.`);
    }
  }
  async function updatePatient(p: Patient) {
    setPatients(prev => prev.map(x => x.id === p.id ? p : x));
    try {
      if (p.recordId) await api("records.replace", { collection: "gottcured_patients", id: p.recordId, value: { ...p, recordId: undefined } });
      else {
        const created: any = await api("records.create", { collection: "gottcured_patients", value: { ...p, recordId: undefined }, idempotency_key: `gottcured-patient-${p.id}` });
        if (created?.id) setPatients(prev => prev.map(x => x.id === p.id ? { ...x, recordId: created.id } : x));
      }
    } catch { }
  }

  useEffect(() => {
    const t = window.setTimeout(() => { setAlerts((p) => p.some((a) => a.id === "a9") ? p : [{ id: "a9", title: "Reagente do analisador abaixo do nível ideal", sector: "Laboratório", severity: "Alto", time: "agora", detail: "Nível de reagente abaixo do ideal. Reposição programada antes da próxima leva de exames.", equipment: "Analisador L-01" }, ...p]); setToast("Novo alerta: reagente do analisador abaixo do nível ideal."); }, 14000);
    return () => window.clearTimeout(t);
  }, []);
  useEffect(() => { if (!toast) return; const t = window.setTimeout(() => setToast(""), 6000); return () => window.clearTimeout(t); }, [toast]);

  const unread = alerts.filter((a) => !readIds.has(a.id) && !snoozed.has(a.id)).length;

  async function persistAlert(alertId: string, status: "read" | "snoozed" | "open" | "ignored" | "resolved" | "done") {
    setSaving(true);
    try {
      const value = { alertId, status, updatedAt: new Date().toISOString() };
      const existing = recordMap[alertId];
      if (existing) await api("records.replace", { collection: "gottcured_alert_state", id: existing, value });
      else {
        const created: any = await api("records.create", { collection: "gottcured_alert_state", value, idempotency_key: `gottcured-alert-${alertId}` });
        if (created?.id) setRecordMap((m) => ({ ...m, [alertId]: created.id }));
      }
      setNotice(status === "read" ? "Alerta marcado como lido." : status === "snoozed" ? "Alerta adiado para o próximo turno." : status === "ignored" ? "Previsão ignorada." : status === "resolved" ? "Previsão marcada como resolvida." : status === "done" ? "Ação da previsão registrada como feita." : "Alerta reaberto.");
    } catch { setNotice("Alteração aplicada nesta sessão. A sincronização será tentada novamente."); }
    setSaving(false);
  }
  function markRead(id: string) { setReadIds((s) => new Set(s).add(id)); setSnoozed((s) => { const n = new Set(s); n.delete(id); return n; }); persistAlert(id, "read"); }
  function snooze(id: string) { setSnoozed((s) => new Set(s).add(id)); persistAlert(id, "snoozed"); }
  async function markAll() {
    setSaving(true);
    const rows = alerts.filter((a) => !readIds.has(a.id)).map((a) => ({ alertId: a.id, status: "read" as const, updatedAt: new Date().toISOString() }));
    let saved = 0; let error: string | null = null;
    try { for (const row of rows) { const existing = recordMap[row.alertId]; if (existing) await api("records.replace", { collection: "gottcured_alert_state", id: existing, value: row }); else { const created: any = await api("records.create", { collection: "gottcured_alert_state", value: row, idempotency_key: `gottcured-alert-${row.alertId}` }); if (created?.id) setRecordMap((m) => ({ ...m, [row.alertId]: created.id })); } saved += 1; } } catch (e) { error = e instanceof Error ? e.message : String(e); }
    let reloadError: string | null = null;
    try { const data: any = await api("records.list", { collection: "gottcured_alert_state" }); const read = new Set<string>(); const map: Record<string, string> = {}; for (const r of data.records || []) { if (r.value?.status === "read" && r.value?.alertId) read.add(r.value.alertId); if (r.value?.alertId) map[r.value.alertId] = r.id; } setReadIds(read); setRecordMap(map); } catch (e) { reloadError = e instanceof Error ? e.message : String(e); }
    setSaving(false);
    setNotice(error || reloadError ? `Salvos: ${saved}. Restantes: ${rows.length - saved}. ${error || reloadError}` : `Todos os ${saved} alertas marcados como lidos.`);
    if (!error && !reloadError) setReadIds(new Set(alerts.map((a) => a.id)));
  }

  function doSearch(q: string) { const value = q.trim(); if (!value) return; setQuery(value); if (historySaving) setSearchHistory((p) => [value, ...p.filter((h) => h.toLowerCase() !== value.toLowerCase())].slice(0, 5)); setView({ kind: "results", query: value }); window.scrollTo({ top: 0 }); }
  function goSector(id: string) { setView({ kind: "sector", id }); setSectorTab("Visão geral"); setBellOpen(false); window.scrollTo({ top: 0 }); }
  function goHome() { setView({ kind: "home" }); setBellOpen(false); setHomeQuery(""); window.scrollTo({ top: 0 }); }
  function openPatient(id: string) { setSelectedPatientId(id); setSectorTab("Cadastro de Pacientes"); setView({ kind: "sector", id: "clinica" }); setBellOpen(false); window.scrollTo({ top: 0 }); }

  const results = useMemo(() => {
    if (view.kind !== "results") return [];
    const q = view.query.toLowerCase();
    const pool = [
      { cat: "Setores", title: "Clínica — consultas, agendamentos e satisfação", url: "gottcured.com.br / clinica", desc: "312 consultas no dia, absenteísmo de 7,1% e satisfação de 4,7 de 5. Fila de 18 pessoas aguardando.", sector: "clinica" },
      { cat: "Equipamentos", title: "Ultrassom U-02 — calibração e histórico", url: "gottcured.com.br / equipamentos / ultrassom-u-02", desc: "Calibração próxima do prazo. Verificação programada antes do pico de consultas da Clínica.", sector: "clinica" },
      { cat: "Agendamentos", title: "Agendamentos da Clínica e absenteísmo", url: "gottcured.com.br / clinica / agendamentos", desc: "298 agendamentos para amanhã. Confirmação reforçada para reduzir faltas.", sector: "clinica" },
      { cat: "Chamados", title: "Chamados da Clínica e tempo de resposta", url: "gottcured.com.br / chamados / clinica", desc: "7 chamados abertos, com baixa complexidade. Maior concentração em calibração e fluxo.", sector: "clinica" },
      { cat: "Setores", title: "Laboratório — exames, paradas e reagendados", url: "gottcured.com.br / laboratorio", desc: "1.284 exames no dia, 18 reagendados e 2 equipamentos parados. Autoclave A-03 com preventiva em 48 horas.", sector: "laboratorio" },
      { cat: "Equipamentos", title: "Autoclave A-03 — preventiva e histórico", url: "gottcured.com.br / equipamentos / autoclave-a-03", desc: "Preventiva em 48 horas. Kit de vedação já reservado para a próxima janela.", sector: "laboratorio" },
      { cat: "Chamados", title: "Chamados do Laboratório e tempo de resposta", url: "gottcured.com.br / chamados / laboratorio", desc: "18 chamados abertos. Maior concentração em vedação, calibração e reagente.", sector: "laboratorio" },
      { cat: "Agendamentos", title: "Exames do Laboratório e remanejamento", url: "gottcured.com.br / laboratorio / exames", desc: "Tempo médio de 42 minutos. Remanejamento da tarde feito com antecedência.", sector: "laboratorio" },
      { cat: "Finanças", title: "Finanças do Laboratório — receita, margem e prejuízo por exame", url: "gottcured.com.br / laboratorio / financas", desc: "Receita, custo e margem por exame, exames com prejuízo, exames enviados a laboratório de apoio, repetição, faturamento por convênio e valor agregado ao hospital.", sector: "laboratorio" },
    ];
    const scored = pool.map((r) => ({ ...r, score: ["clinica", "consulta", "agendamento", "laboratorio", "exame", "reagend", "chamados", "autoclave", "ultrassom"].filter((k) => q.includes(k) && (r.title + r.desc + r.cat).toLowerCase().includes(k)).length }));
    const matched = scored.filter((r) => r.score > 0 || q.length < 3 || (r.title + r.desc).toLowerCase().includes(q)).sort((a, b) => b.score - a.score);
    const base = matched.length ? matched : pool;
    return filter === "Todos" ? base : base.filter((r) => r.cat === filter);
  }, [view, filter]);

  const matchedPatients = useMemo(() => {
    if (view.kind !== "results") return [];
    const q = norm(view.query);
    if (q.includes("paciente")) return patients;
    return patients.filter(p => norm(p.name).includes(q) || (q.length >= 3 && norm(p.name).split(" ").some(w => w.startsWith(q))) || onlyDigits(p.cpf).includes(onlyDigits(view.query)) || norm(p.insurance).includes(q));
  }, [view, patients]);

  const predictiveActive = PREDICTIVE_ALERTS.filter((a) => !ignoredIds.has(a.id) && !resolvedIds.has(a.id));
  const predictiveVisible = predictiveActive.filter((a) => (alertKindFilter === "Todos" || (alertKindFilter === "Urgentes" && (a.level === "Alto" || a.probability >= 80)) || (alertKindFilter === "Críticos" && a.probability >= 85 && a.level === "Alto") || alertKindFilter === "Previsões") && (alertSearch.trim() === "" || (a.title + a.detail + a.reason + a.category).toLowerCase().includes(alertSearch.toLowerCase())));
  function goToClinicaTab(tab: string, patientId?: string) { if (patientId) setSelectedPatientId(patientId); setSectorTab(tab); setView({ kind: "sector", id: "clinica" }); setBellOpen(false); window.scrollTo({ top: 0 }); }
  function markPredictiveDone(a: PredictiveAlert, msg: string) { setPredictiveDone((s) => new Set(s).add(a.id)); persistAlert(a.id, "done"); setNotice(msg); }
  function handlePredictiveAction(a: PredictiveAlert) {
    const choice = predictiveChoice[a.id] || a.actionOptions?.[0] || a.actionLabel;
    if (a.id === "p-ret-1") { setNotice("Retorno de pré-natal aberto em Acompanhamento e Continuidade — confirme a data com a paciente."); goToClinicaTab("Acompanhamento e Continuidade", a.patientId); return; }
    if (a.id === "p-ret-2") { setNotice("Solicitação de exame aberta em Prescrição e Solicitações — confirme Hemoglobina glicada."); goToClinicaTab("Prescrição e Solicitações", a.patientId); return; }
    if (a.id === "p-rec-1") { setNotice("Receita prevista aberta em Finanças da Clínica."); goToClinicaTab("Finanças da Clínica"); return; }
    if (a.id === "p-rec-2" || a.id === "p-cons-1" || a.id === "p-cons-2") { if (a.id.startsWith("p-cons")) { markPredictiveDone(a, `Compra solicitada: ${a.title}. Verifique o pedido em Controle de Insumos.`); goToClinicaTab("Controle de Insumos"); return; } setNotice("Custo previsto de insumos aberto em Controle de Insumos."); goToClinicaTab("Controle de Insumos"); return; }
    if (a.id === "p-var-1" && a.patientId) { setNotice(`Paciente aberto: ${a.title}.`); openPatient(a.patientId); return; }
    if (a.id === "p-var-2") { setNotice("Padrão de atendimento aberto em Equipe e Produtividade."); goToClinicaTab("Equipe e Produtividade"); return; }
    if (a.id === "p-eleg-1") { setNotice("Programas de Crônicos e Prevenção abertos em Acompanhamento e Continuidade — selecione o programa de Diabetes."); goToClinicaTab("Acompanhamento e Continuidade"); return; }
    if (a.id === "p-eleg-2") { markPredictiveDone(a, "Convite para Check-up anual registrado para Ana Beatriz Costa."); return; }
    markPredictiveDone(a, `Ação registrada: ${choice} — ${a.title}.`);
  }
  function ignorePredictive(a: PredictiveAlert) { setIgnoredIds((s) => new Set(s).add(a.id)); persistAlert(a.id, "ignored"); }
  function resolvePredictive(a: PredictiveAlert) { setResolvedIds((s) => new Set(s).add(a.id)); persistAlert(a.id, "resolved"); }
  const visibleAlerts = alertGroup === "previsoes" ? [] : alerts.filter((a) => (severity === "Todas" || a.severity === severity) && (sectorFilter === "Todos" || a.sector === sectorFilter) && (alertKindFilter === "Todos" || alertKindFilter === "Previsões" ? alertKindFilter === "Todos" : alertKindFilter === "Urgentes" ? (a.severity === "Alto" || a.severity === "Crítico") : (a.severity === "Crítico")) && (alertSearch.trim() === "" || (a.title + a.detail + a.equipment).toLowerCase().includes(alertSearch.toLowerCase())));

  const roi = useMemo(() => {
    const base = 228000; const gain = Math.round((preventiva - 60) * 2200 + (equipe - 7) * 9000 + (investimento - 80) * 320);
    return { economia: base + gain, disponibilidade: Math.min(99.2, 94.8 + preventiva * 0.025 + equipe * 0.12), custo: Math.max(760, 1280 - (preventiva - 60) * 4 - (investimento - 80) * 1.2) };
  }, [preventiva, equipe, investimento]);

  const sector = view.kind === "sector" ? SECTORS.find((s) => s.id === view.id) : undefined;
  const sectorSearch: { type: "all" } | { type: "single"; id: string } | null = view.kind === "results" ? (isAllSectorsQuery(view.query) ? { type: "all" } : (() => { const id = sectorIdForQuery(view.query); return id ? { type: "single", id } : null; })()) : null;
  const resultsAi = sectorSearch?.type === "single" ? pickSuggestions(SECTOR_DETAILS[sectorSearch.id].ai, aiCycle, 4) : pickSuggestions(GLOBAL_AI, aiCycle, 4);
  const singleAiTwo = sectorSearch?.type === "single" ? pickSuggestions(SECTOR_DETAILS[sectorSearch.id].ai, aiCycle, 2) : [];
  function handleAiSuggestion(s: AiSuggestion) { setNotice(`IA: ${s.title} — ${s.detail}`); goSector(s.sectorId); }
  const page = sector ? PAGE_DATA[sector.id] : null;
  const sectorTabs = sector ? (sector.id === "clinica" ? ["Visão geral", "Atendimento e Consulta", "Cadastro de Pacientes", "Prescrição e Solicitações", "Sugestões para o Gestor", "Relatórios e Visualização", "Controle de Insumos", "Acompanhamento e Continuidade", "Procedimentos e Estrutura", "Equipe e Produtividade", "Chamados", "Equipamentos", "Preventiva", "Disponibilidade", "Finanças da Clínica", "Financeiro", "Qualidade", "Agendamentos"] : ["Visão geral", "Modo IA", "Cadastro e Catálogo de Exames", "Pedido e Agendamento", "WhatsApp e Comunicação", "Pedidos e Exames", "Coleta e Amostras", "Análise e Resultados", "Entrega de Resultados", "Qualidade e Rastreabilidade", "Controle de Insumos e Reagentes", "Tempo e Produtividade", "Finanças do Laboratório", "Integração com Outros Módulos", "Segurança e Conformidade", "Relatórios e Visualização", "Chamados", "Equipamentos", "Preventiva", "Disponibilidade", "Financeiro", "Qualidade", "Exames"]) : [];
  const isLabQuery = view.kind === "results" && norm(view.query).includes("laboratorio");
  const summarySector = isLabQuery ? SECTORS[1] : SECTORS[0];

  return <div data-safe-area-inset-root data-theme={theme} style={{ boxSizing: "border-box", paddingTop: "var(--safe-area-inset-top)", minHeight: "100vh", color: "var(--ink)" }} className="mac-shell overflow-x-clip">
    {view.kind !== "home" && <Topbar theme={theme} onTheme={() => setTheme(theme === "dark" ? "light" : "dark")} query={query} setQuery={setQuery} onSearch={doSearch} onHome={goHome} unread={unread} onBell={() => setBellOpen((v) => !v)} onNotice={setNotice} historySaving={historySaving} onSaveProfile={saveProfile} onSearchQuery={doSearch} />}

    {view.kind === "home" && <main className="mx-auto flex min-h-[calc(100vh-var(--safe-area-inset-top))] w-full max-w-[1240px] flex-col px-4">
      <div className="flex items-center justify-between gap-2 pt-3"><span className="mac-traffic" aria-hidden="true"><i /><i /><i /></span><span className="flex items-center gap-2">
        <button onClick={() => setTheme(theme === "dark" ? "light" : "dark")} className="grid h-10 w-10 place-items-center rounded-full border border-[var(--line)] bg-[var(--surface)]" aria-label={theme === "dark" ? "Usar tema claro" : "Usar tema escuro"}>{theme === "dark" ? <Sun size={19} /> : <Moon size={19} />}</button>
        <button onClick={() => setBellOpen((v) => !v)} className="relative grid h-10 w-10 place-items-center rounded-full border border-[var(--line)] bg-[var(--surface)]" aria-label="Abrir alertas"><Bell size={19} />{unread > 0 && <span className="absolute -right-1 -top-1 grid h-5 min-w-5 place-items-center rounded-full bg-[#C83E3E] px-1 text-[11px] font-bold text-white">{unread}</span>}</button>
        <ProfileMenu onNotice={setNotice} historySaving={historySaving} onSaveProfile={saveProfile} onSearchQuery={doSearch} />
      </span></div>
      <div className="flex flex-1 flex-col items-center justify-center py-8">
        <img src={logoUrl} alt="GottCured" style={{ background: "transparent" }} className="logo-img w-[min(78vw,430px)] object-contain" />
        <form onSubmit={(e) => { e.preventDefault(); doSearch(homeQuery); }} className="mt-7 flex h-[56px] w-full max-w-[640px] items-center gap-2 rounded-2xl border border-[var(--line-soft)] bg-[var(--surface)] py-1 pl-5 pr-1.5 shadow-[var(--shadow)]">
          <Search size={20} className="shrink-0 text-[var(--muted)]" /><input value={homeQuery} onChange={(e) => setHomeQuery(e.target.value)} placeholder="Pesquise..." aria-label="Pesquise" className="w-full bg-transparent text-[17px] outline-none placeholder:text-[var(--muted-2)]" /><button className="h-11 shrink-0 rounded-xl bg-[var(--primary)] px-5 text-[15px] font-bold text-white">Buscar</button>
        </form>
      </div>
      <p className="pb-5 text-center text-[12px] text-[var(--muted-2)]">GottCured · Clínica e Laboratório · Dados fictícios para demonstração</p>
    </main>}

    {view.kind === "results" && <main className="mx-auto max-w-[900px] px-4 py-6 sm:px-5">
      {!(sectorSearch?.type === "single" && sectorSearch.id === "laboratorio") && <AiMode suggestions={resultsAi} alerts={alerts} onViewAlerts={() => setBellOpen(true)} onOpenSector={goSector} onNotice={setNotice} sectorId={sectorSearch?.type === "single" ? sectorSearch.id : undefined} />}
      <p className="mt-5 text-[13px] text-[var(--muted)]">{sectorSearch?.type === "all" ? "2 setores contratados" : sectorSearch?.type === "single" ? "1 setor encontrado" : `Cerca de ${results.length} resultados`} para <strong className="text-[var(--ink)]">“{view.query}”</strong></p>
      {!sectorSearch && <div className="mt-4 flex gap-2 overflow-x-auto pb-1 no-scrollbar">{["Todos", "Setores", "Equipamentos", "Chamados", "Agendamentos"].map((f) => <button key={f} onClick={() => setFilter(f)} className={`pill shrink-0 px-3.5 py-2 text-[13px] font-semibold ${filter === f ? "chip-active" : ""}`}>{f}</button>)}</div>}
      {sectorSearch && <div className="mt-4 space-y-3">{(sectorSearch.type === "all" ? [...SECTORS] : SECTORS.filter((s) => s.id === sectorSearch.id)).map((s) => <article key={s.id} className="card p-4 sm:p-5"><button onClick={() => goSector(s.id)} className="text-left"><p className="text-[12px] text-[var(--muted)]">gottcured.com.br / {s.id}</p><h3 className="mt-1 text-[18px] font-bold leading-snug text-[var(--primary)] hover:underline">{s.name} — {s.desc}</h3></button><div className="mt-3 flex flex-wrap gap-2">{s.kpis.map(([l, v]) => <span key={l} className="pill px-2.5 py-1 text-[12px] font-bold">{l}: {v}</span>)}</div><button onClick={() => goSector(s.id)} className="mt-3 text-[13px] font-bold text-[var(--primary)]">Abrir {s.name} →</button></article>)}</div>}
      {sectorSearch?.type === "single" && <div><h3 className="mt-6 text-[17px] font-extrabold">Métricas gerais do setor</h3><div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{SECTOR_DETAILS[sectorSearch.id].general.map((m) => <div key={m.label} className="card p-4"><p className="text-[12px] font-bold uppercase tracking-wide text-[var(--muted)]">{m.label}</p><p className="kpi-num mt-2">{m.value}</p><p className="mt-2 text-[13px] leading-5 text-[var(--muted)]">{m.note}</p></div>)}</div></div>}
      {!sectorSearch && <>
      <section className="card mt-5 overflow-hidden p-5 sm:p-6" aria-label="Resposta da IA"><div className="flex items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-full bg-[var(--primary)] text-white"><Activity size={17} /></span><div><h2 className="text-[16px] font-extrabold">IA</h2><p className="text-[12px] text-[var(--muted)]">Resumo operacional com base nos registros atuais</p></div></div>
        {isLabQuery ? <p className="mt-4 text-[16px] leading-7">Para <strong>“{view.query}”</strong>, o ponto mais sensível está no <strong>Laboratório</strong>: a Autoclave A-03 concentra o maior impacto em exames e disponibilidade. A recomendação é concluir a preventiva da autoclave, manter o remanejamento da tarde e revisar a verificação dos equipamentos com falha recorrente.</p> : <p className="mt-4 text-[16px] leading-7">Para <strong>“{view.query}”</strong>, o ponto mais sensível está na <strong>Clínica</strong>: o absenteísmo e a fila de espera concentram o maior impacto na agenda. A recomendação é reforçar a confirmação das consultas, priorizar a fila por horário marcado e antecipar a calibração do ultrassom.</p>}
        <div className="mt-4 grid gap-3 sm:grid-cols-3"><div className="soft p-3"><p className="text-xs text-[var(--muted)]">Previsão — próximos 7 dias</p><p className="mt-1 font-bold">{isLabQuery ? "Risco moderado de nova parada" : "Risco moderado de fila maior"}</p></div><div className="soft p-3"><p className="text-xs text-[var(--muted)]">Impacto estimado</p><p className="mt-1 font-bold">{isLabQuery ? "Até 18 exames afetados" : "Até 18 pessoas aguardando"}</p></div><div className="soft p-3"><p className="text-xs text-[var(--muted)]">Próxima ação</p><p className="mt-1 font-bold">{isLabQuery ? "Preventiva em 48 horas" : "Confirmação das consultas"}</p></div></div>
        <button onClick={() => goSector(summarySector.id)} className="mt-5 inline-flex items-center gap-1.5 rounded-full bg-[var(--primary)] px-4 py-2 text-sm font-bold text-white">Abrir {summarySector.name} <ArrowUpRight size={16} /></button>
      </section>
      <div className="mt-5 space-y-3">{results.map((r, i) => <article key={i} className="card p-4 sm:p-5"><button onClick={() => goSector(r.sector)} className="text-left"><p className="text-[12px] text-[var(--muted)]">{r.url}</p><h3 className="mt-1 text-[18px] font-bold leading-snug text-[var(--primary)] hover:underline">{r.title}</h3><p className="mt-1.5 text-[14px] leading-6 text-[var(--muted)]">{r.desc}</p></button><div className="mt-3 flex items-center gap-2 text-[12px]"><span className="pill px-2.5 py-1 font-bold">{r.cat}</span><button onClick={() => goSector(r.sector)} className="font-bold text-[var(--primary)]">Abrir setor →</button></div></article>)}</div>
      </>}
      <div className="mt-8 border-t border-[var(--line)] pt-5"><p className="mb-3 text-sm font-bold">Acesso rápido</p><div className="flex flex-wrap gap-2">{SECTORS.map((s) => <button key={s.id} onClick={() => goSector(s.id)} className="pill px-3 py-2 text-[13px] font-semibold">{s.name}</button>)}</div></div>
    </main>}

    {view.kind === "sector" && sector && page && <div className="mac-window"><main className="mac-content">
      <button onClick={goHome} className="mb-4 mt-4 inline-flex items-center gap-1.5 text-sm font-bold text-[var(--primary)]"><ArrowLeft size={16} /> Voltar para a página inicial</button>
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-[12px] font-bold uppercase tracking-[0.16em] text-[var(--muted)]">Página do setor</p><h1 className="h-display mt-1 font-extrabold">{sector.name}</h1><p className="mt-2 max-w-[680px] text-[15px] leading-6 text-[var(--muted)]">{sector.desc}. Dados atualizados hoje, com indicadores operacionais, equipamentos, chamados e impacto no atendimento.</p></div><div className="flex flex-wrap gap-2">{sector.id === "clinica" && <button onClick={() => setSectorTab("Cadastro de Pacientes")} className="inline-flex items-center gap-1.5 rounded-full bg-[var(--primary)] px-4 py-2.5 text-sm font-bold text-white"><Users size={16} /> Cadastro de Pacientes</button>}<button onClick={() => setBellOpen(true)} className="pill px-4 py-2.5 text-sm font-bold">Ver alertas · {unread}</button><button onClick={() => doSearch(sector.name)} className="rounded-full bg-[var(--primary)] px-4 py-2.5 text-sm font-bold text-white">Pesquisar neste setor</button></div></div>

      <div className="mt-5 flex gap-2 overflow-x-auto pb-1 no-scrollbar">{sectorTabs.map((t) => <button key={t} onClick={() => setSectorTab(t)} className={`pill shrink-0 px-3.5 py-2 text-[13px] font-semibold ${sectorTab === t ? "chip-active" : ""}`}>{t}</button>)}</div>

      {sectorTab === "Cadastro de Pacientes" && sector.id === "clinica" && <div className="mt-5"><Section title="Cadastro de Pacientes" sub="Cadastro completo, prevenção de duplicidade, prontuário, histórico, alertas clínicos, documentos, familiares e linha do tempo." icon={<Users size={19} />}><PatientsModule patients={patients} selectedId={selectedPatientId} onSelect={setSelectedPatientId} onAddPatient={addPatient} onUpdatePatient={updatePatient} onNotice={setNotice} /></Section></div>}
      {sectorTab === "Atendimento e Consulta" && sector.id === "clinica" && <div className="mt-5"><Section title="Atendimento e Consulta" sub="Painel do médico: pacientes do dia, chamada, consulta com cronômetro, resumo pré-consulta, telemedicina, equipe multiprofissional, encaminhamento, atestados, ausência e intercorrência." icon={<Stethoscope size={19} />}><AtendimentoModule patients={patients} onUpdatePatient={updatePatient} onNotice={setNotice} /></Section></div>}
      {sectorTab === "Sugestões para o Gestor" && sector.id === "clinica" && <div className="mt-5"><Section title="Sugestões para o Gestor e Apoio ao Profissional" sub="Painel diferencial da Clínica: resumo pré-consulta, exames por protocolo, alertas clínicos, busca ativa, agenda, gargalos, investimento, comparativo, simulador, resumo mensal e eficiência. Sugestões são apoio — a decisão é do médico / gestor." icon={<Sparkles size={19} />}><SugestoesGestorModule patients={patients} onUpdatePatient={updatePatient} onNotice={setNotice} onOpenPatient={openPatient} alerts={alerts} /></Section></div>}
      {sectorTab === "Prescrição e Solicitações" && sector.id === "clinica" && <div className="mt-5"><Section title="Prescrição e Solicitações" sub="Prescrição eletrônica com alertas de alergia, interação e duplicidade, receitas de controle, exames ao Laboratório, assinatura digital, envio por WhatsApp e acompanhamento." icon={<Pill size={19} />}><label className="block text-sm font-bold">Paciente<select value={selectedPatientId || patients[0]?.id || ""} onChange={(e) => setSelectedPatientId(e.target.value)} className="mt-1 w-full rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-sm outline-none">{patients.map(p => <option key={p.id} value={p.id}>{p.name} · {p.insurance}</option>)}</select></label>{(() => { const p = patients.find(x => x.id === selectedPatientId) || patients[0]; return p ? <div className="mt-4"><PrescricaoModule patient={p} onUpdatePatient={updatePatient} onNotice={setNotice} onOpenPatient={openPatient} /></div> : <p className="mt-4 text-sm text-[var(--muted)]">Selecione um paciente.</p>; })()}</Section></div>}
      {sectorTab === "Cadastro e Catálogo de Exames" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Cadastro e Catálogo de Exames" sub="Catálogo por área, valores de referência, preparo, perfis e pacotes, preços por convênio, exames internos × enviados e laboratórios de apoio — só no Laboratório." icon={<FlaskConical size={19} />}><CatalogoExamesModule patients={patients} onUpdatePatient={updatePatient} onNotice={setNotice} /></Section></div>}
      {sectorTab === "Pedido e Agendamento" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Pedido e Agendamento" sub="Registro de pedido, pedido digital, agendamento de coleta, verificação de convênio e elegibilidade, classificação de prioridade, remarcação e cancelamento — só no Laboratório." icon={<FlaskConical size={19} />}><PedidoAgendamentoModule patients={patients} onNotice={setNotice} /></Section></div>}
      {sectorTab === "WhatsApp e Comunicação" && sector.id === "laboratorio" && <div className="mt-5"><Section title="WhatsApp e Comunicação com o Paciente" sub="Conversa simulada, lembrete com preparo, confirmação de presença, fila de coleta, atualização de etapas, resultado, recoleta, orientações pós-coleta, pesquisa de satisfação, transferência para atendente humano e consentimento — só no Laboratório. Simulação: nada é enviado para fora do app." icon={<MessageSquare size={19} />}><WhatsAppLabModule patients={patients} onUpdatePatient={updatePatient} onNotice={setNotice} /></Section></div>}
      {sectorTab === "Pedidos e Exames" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Pedidos e Exames — Laboratório" sub="Pedidos enviados pela Clínica: pendentes, coleta, análise, resultado e avaliação. Resultados críticos ficam em destaque." icon={<FlaskConical size={19} />}><LabOrdersModule patients={patients} onUpdatePatient={updatePatient} onNotice={setNotice} onOpenPatient={openPatient} /></Section></div>}
      {sectorTab === "Coleta e Amostras" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Coleta e Amostras" sub="Etiquetas com código de barras, registro de coleta, rastreabilidade, recebimento, amostras registradas, nova coleta, transporte para laboratório de apoio e descarte controlado — só no Laboratório." icon={<FlaskConical size={19} />}><ColetaAmostrasModule patients={patients} onNotice={setNotice} /></Section></div>}
      {sectorTab === "Análise e Resultados" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Análise e Resultados" sub="Validação de resultados com confirmação dupla para críticos, comparação com anteriores, laudo padronizado com assinatura digital, histórico completo e resultados de internados na unidade e no leito — só no Laboratório." icon={<FlaskConical size={19} />}><AnaliseResultadosModule patients={patients} onNotice={setNotice} onCriticalAlert={(a) => { setAlerts((prev) => prev.some((x) => x.id === a.id) ? prev : [a, ...prev]); setNotice(`Alerta crítico enviado para Alertas da Clínica — ${a.title}.`); }} onOpenPatient={openPatient} /></Section></div>}
      {sectorTab === "Entrega de Resultados" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Entrega de Resultados" sub="Resultados prontos para entrega por canal, confirmação com data/hora e responsável, rastreabilidade de cada laudo e segunda via com selo, solicitante e motivo — só no Laboratório." icon={<FileText size={19} />}><EntregaResultadosModule patients={patients} onNotice={setNotice} /></Section></div>}
      {sectorTab === "Qualidade e Rastreabilidade" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Controle de Qualidade e Rastreabilidade" sub="Rastreabilidade por lote, controle de lotes e reagentes, controles diários com bloqueio automático em falha e ações corretivas registradas no histórico do lote — só no Laboratório." icon={<ShieldCheck size={19} />}><ControleQualidadeModule onNotice={setNotice} /></Section></div>}
      {sectorTab === "Tempo e Produtividade" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Tempo e Produtividade" sub="Tempos e TAT, volume e exames por hora, produtividade por profissional e equipamento, carga de trabalho, repetidos e recoletas, e fila de pendentes em tempo real — só no Laboratório." icon={<Clock3 size={19} />}><TempoProdutividadeModule onNotice={setNotice} onOpenPatient={openPatient} /></Section></div>}
      {sectorTab === "Finanças do Laboratório" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Finanças do Laboratório" sub="Receita, custo e margem por exame, exames com prejuízo, exames enviados a laboratório de apoio, custo de repetição, faturamento por convênio, receita perdida, receita prevista, ticket médio, orçamento, investimento e valor agregado ao hospital — só no Laboratório." icon={<DollarSign size={19} />}><FinancasLaboratorioModule onNotice={setNotice} /></Section></div>}
      {sectorTab === "Integração com Outros Módulos" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Integração com Outros Módulos" sub="Chamado de manutenção pelo laboratório, pedidos de internados e resultados no leito, impacto de atrasos na permanência, pedidos de consultas e retornos, custo de reagente no Financeiro e visão consolidada no Dashboard Executivo — só no Laboratório." icon={<Repeat size={19} />}><IntegracaoLabModule patients={patients} onNotice={setNotice} onGoTab={setSectorTab} /></Section></div>}
      {sectorTab === "Segurança e Conformidade" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Segurança e Conformidade" sub="Trilha de auditoria de pedidos, resultados, retificações e acessos, com antes/depois, e assinatura digital com validade jurídica dos laudos — só no Laboratório." icon={<ShieldCheck size={19} />}><SegurancaLabModule patients={patients} onNotice={setNotice} /></Section></div>}
      {sectorTab === "Relatórios e Visualização" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Relatórios e Visualização" sub="Dashboard setorial do Laboratório, filtros globais, tendência diária/mensal/anual, mapa de calor, relatórios prontos, exportação e relatório anual 2026 — só no Laboratório." icon={<TrendingUp size={19} />}><RelatoriosLabModule onNotice={setNotice} /></Section></div>}
      
      {sectorTab === "Visão geral" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Inteligência e Previsão" sub="Resumo das previsões do Laboratório — abra a seção completa para agir em cada previsão." icon={<Sparkles size={19} />}><div className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm leading-6">Volume previsto amanhã: <strong>312 exames (+18%)</strong> · Pico 2ª-feira 8h–10h (+42% coletas) · Ruptura prevista: Reagente Glicose em 6 dias · Risco de falha 78% — Analisador Bioquímica.</p><button onClick={() => setSectorTab("Inteligência e Previsão")} className="rounded-full bg-[var(--primary)] px-4 py-2.5 text-sm font-bold text-white">Abrir Inteligência e Previsão →</button></div></Section></div>}
      {sectorTab === "Controle de Insumos e Reagentes" && sector.id === "laboratorio" && <div className="mt-5"><Section title="Controle de Insumos e Reagentes" sub="Cadastro de reagentes, entrada e retirada por lote, vínculo com exame / equipamento / bancada / paciente, estoque em tempo real, validade e bloqueio, armazenamento, alertas, perdas, ponto de reposição, rastreabilidade e custo — só no Laboratório." icon={<FlaskConical size={19} />}><ControleInsumosLabModule patients={patients} onNotice={setNotice} onOpenPatient={openPatient} /></Section></div>}
      {sectorTab === "Controle de Insumos" && sector.id === "clinica" && <div className="mt-5"><Section title="Controle de Insumos" sub="Retirada por código de barras, vínculo com paciente/consulta/procedimento, kits com baixa automática, estoque por sala e armário, validade e lote, estoque mínimo, perdas, consumo sem registro, custo e tendência — só na Clínica." icon={<Package size={19} />}><InsumosClinicaModule patients={patients} onUpdatePatient={updatePatient} onNotice={setNotice} onOpenPatient={openPatient} /></Section></div>}
      {sectorTab === "Acompanhamento e Continuidade" && sector.id === "clinica" && <div className="mt-5"><Section title="Acompanhamento e Continuidade do Cuidado" sub="Programas de crônicos, linhas de cuidado, retornos, busca ativa, metas e adesão, vacinação, prevenção, pós-alta, questionários e plano compartilhado — só na Clínica." icon={<HeartPulse size={19} />}><ContinuityModule patients={patients} onNotice={setNotice} onOpenPatient={openPatient} /></Section></div>}
      {sectorTab === "Procedimentos e Estrutura" && sector.id === "clinica" && <div className="mt-5"><Section title="Procedimentos e Estrutura da Clínica" sub="Agenda de salas e equipamentos, registro de procedimentos, esterilização e rastreabilidade, limpeza, gestão de salas, equipamentos da Clínica, termos de consentimento e intercorrências — só na Clínica." icon={<BedDouble size={19} />}><ProcedimentosEstruturaModule patients={patients} onUpdatePatient={updatePatient} onNotice={setNotice} onOpenPatient={openPatient} /></Section></div>}
      {sectorTab === "Equipe e Produtividade" && sector.id === "clinica" && <div className="mt-5"><Section title="Equipe e Produtividade" sub="Cadastro de profissionais, escala semanal, produtividade, tempo médio de consulta, carga e ociosidade, metas, satisfação e repasse — só na Clínica." icon={<Users size={19} />}><EquipeProdutividadeModule onNotice={setNotice} /></Section></div>}
      {sectorTab === "Finanças da Clínica" && sector.id === "clinica" && <div className="mt-5"><Section title="Finanças da Clínica" sub="Receita, custo e margem, faturamento por convênio e glosas, pacotes e contas a receber, receita prevista e perdida, orçamento, patrimônio, ROI, valor agregado e custo de equipamento parado — só na Clínica." icon={<DollarSign size={19} />}><FinancasClinicaModule onNotice={setNotice} /></Section></div>}
      {sectorTab === "Relatórios e Visualização" && sector.id === "clinica" && <div className="mt-5"><Section title="Relatórios e Visualização" sub="Dashboard setorial da Clínica, filtros globais, tendência, mapa de calor, relatórios prontos, exportação e relatório anual 2026 — só na Clínica." icon={<TrendingUp size={19} />}><RelatoriosVisualizacaoModule patients={patients} onNotice={setNotice} /></Section></div>}
      {(sectorTab === "Visão geral" || sectorTab === "Chamados") && <div className="mt-5 space-y-5"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{sector.kpis.map(([l, v]) => <Kpi key={l} label={l} value={v} note="Indicador do dia, com base nos registros do setor." icon={<Activity size={15} />} />)}</div>
        {sector.id === "laboratorio" && sectorTab === "Visão geral" && <div className="card flex flex-wrap items-center justify-between gap-3 p-4"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]"><FlaskConical size={19} /></span><div><h3 className="font-extrabold">Cadastro e Catálogo de Exames</h3><p className="text-sm text-[var(--muted)]">Catálogo por área, valores de referência, preparo, pacotes, preços por convênio e laboratórios de apoio.</p></div></div><button onClick={() => setSectorTab("Cadastro e Catálogo de Exames")} className="rounded-full bg-[var(--primary)] px-4 py-2 text-sm font-bold text-white">Abrir Catálogo de Exames</button></div>}
        {sector.id === "laboratorio" && sectorTab === "Visão geral" && <div className="card flex flex-wrap items-center justify-between gap-3 p-4"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]"><Clock3 size={19} /></span><div><h3 className="font-extrabold">Tempo e Produtividade</h3><p className="text-sm text-[var(--muted)]">Coleta em 8 min · 94,2% dentro do prazo · 180 exames na fila · recoletas em 2,4% (meta &lt; 3%).</p></div></div><button onClick={() => setSectorTab("Tempo e Produtividade")} className="rounded-full bg-[var(--primary)] px-4 py-2 text-sm font-bold text-white">Abrir Tempo e Produtividade</button></div>}
        {sector.id === "laboratorio" && sectorTab === "Visão geral" && <div className="card flex flex-wrap items-center justify-between gap-3 p-4"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]"><FlaskConical size={19} /></span><div><h3 className="font-extrabold">Controle de Insumos e Reagentes</h3><p className="text-sm text-[var(--muted)]">Estoque por lote, validade e bloqueio, alertas de mínimo / ruptura e rastreabilidade do lote até o paciente.</p></div></div><button onClick={() => setSectorTab("Controle de Insumos e Reagentes")} className="rounded-full bg-[var(--primary)] px-4 py-2 text-sm font-bold text-white">Abrir Insumos e Reagentes</button></div>}
        {sector.id === "laboratorio" && sectorTab === "Visão geral" && <div className="card flex flex-wrap items-center justify-between gap-3 p-4"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]"><DollarSign size={19} /></span><div><h3 className="font-extrabold">Finanças do Laboratório</h3><p className="text-sm text-[var(--muted)]">Receita, margem e prejuízo por exame, exames enviados, repetição, convênios, receita perdida e prevista, ticket médio, orçamento, investimento e valor agregado.</p></div></div><button onClick={() => setSectorTab("Finanças do Laboratório")} className="rounded-full bg-[var(--primary)] px-4 py-2 text-sm font-bold text-white">Abrir Finanças do Laboratório</button></div>}
        {sector.id === "clinica" && sectorTab === "Visão geral" && <div className="card flex flex-wrap items-center justify-between gap-3 p-4"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]"><Users size={19} /></span><div><h3 className="font-extrabold">Cadastro de Pacientes</h3><p className="text-sm text-[var(--muted)]">{patients.length} pacientes cadastrados · Prontuário, histórico e alertas clínicos.</p></div></div><button onClick={() => setSectorTab("Cadastro de Pacientes")} className="rounded-full bg-[var(--primary)] px-4 py-2 text-sm font-bold text-white">Abrir Cadastro de Pacientes</button></div>}
        {sector.id === "clinica" && sectorTab === "Visão geral" && <div className="card flex flex-wrap items-center justify-between gap-3 p-4"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]"><BedDouble size={19} /></span><div><h3 className="font-extrabold">Procedimentos e Estrutura da Clínica</h3><p className="text-sm text-[var(--muted)]">Agenda de salas, procedimentos, esterilização, limpeza, salas, equipamentos, termos e intercorrências.</p></div></div><button onClick={() => setSectorTab("Procedimentos e Estrutura")} className="rounded-full bg-[var(--primary)] px-4 py-2 text-sm font-bold text-white">Abrir Procedimentos e Estrutura</button></div>}
        {sector.id === "clinica" && sectorTab === "Visão geral" && <div className="card flex flex-wrap items-center justify-between gap-3 p-4"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]"><Users size={19} /></span><div><h3 className="font-extrabold">Equipe e Produtividade</h3><p className="text-sm text-[var(--muted)]">Profissionais, escala semanal, produtividade, tempo médio, carga, metas, satisfação e repasse.</p></div></div><button onClick={() => setSectorTab("Equipe e Produtividade")} className="rounded-full bg-[var(--primary)] px-4 py-2 text-sm font-bold text-white">Abrir Equipe e Produtividade</button></div>}
        {sector.id === "clinica" && sectorTab === "Visão geral" && <div className="card flex flex-wrap items-center justify-between gap-3 p-4"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]"><DollarSign size={19} /></span><div><h3 className="font-extrabold">Finanças da Clínica</h3><p className="text-sm text-[var(--muted)]">Receita, margem, glosas, pacotes, contas a receber, orçamento, ROI e equipamento parado.</p></div></div><button onClick={() => setSectorTab("Finanças da Clínica")} className="rounded-full bg-[var(--primary)] px-4 py-2 text-sm font-bold text-white">Abrir Finanças da Clínica</button></div>}
        {sector.id === "clinica" && sectorTab === "Visão geral" && <div className="card flex flex-wrap items-center justify-between gap-3 p-4"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[var(--primary-soft)] text-[var(--primary)]"><TrendingUp size={19} /></span><div><h3 className="font-extrabold">Relatórios e Visualização</h3><p className="text-sm text-[var(--muted)]">Dashboard setorial, filtros globais, tendência, mapa de calor, relatórios prontos, exportação e relatório anual 2026.</p></div></div><button onClick={() => setSectorTab("Relatórios e Visualização")} className="rounded-full bg-[var(--primary)] px-4 py-2 text-sm font-bold text-white">Abrir Relatórios e Visualização</button></div>}
        <Section title="Chamados — abertura, complexidade e tempo" sub="Acompanhamento por complexidade, tempo médio, SLA e reabertura." icon={<Wrench size={19} />}><div className="grid gap-4 lg:grid-cols-2"><ChartCard title={sector.id === "clinica" ? "Consultas e chamados da semana" : "Chamados x exames da semana"}><div className="h-[240px]"><ResponsiveContainer><BarChart data={page.chamadosSemana}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="d" tick={{ fill: "var(--muted)", fontSize: 12 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "var(--muted)", fontSize: 12 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={tipStyle} /><Bar dataKey="v" fill="#0F5F5C" radius={[7, 7, 0, 0]} /></BarChart></ResponsiveContainer></div></ChartCard><div className="grid grid-cols-2 gap-3"><div className="soft p-4"><p className="text-xs text-[var(--muted)]">Tempo médio de atendimento</p><p className="mt-1 text-2xl font-extrabold">{sector.id === "clinica" ? "1,8 h" : "6,4 h"}</p></div><div className="soft p-4"><p className="text-xs text-[var(--muted)]">Tempo médio de reparo</p><p className="mt-1 text-2xl font-extrabold">{sector.id === "clinica" ? "3,2 h" : "11,8 h"}</p></div><div className="soft p-4"><p className="text-xs text-[var(--muted)]">Reabertos</p><p className="mt-1 text-2xl font-extrabold">{sector.id === "clinica" ? "2,1%" : "4,8%"}</p></div><div className="soft p-4"><p className="text-xs text-[var(--muted)]">Complexidade alta</p><p className="mt-1 text-2xl font-extrabold">{sector.id === "clinica" ? "12%" : "31%"}</p></div></div></div><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2 pr-3">Chamado</th><th className="py-2 pr-3">Equipamento</th><th className="py-2 pr-3">Complexidade</th><th className="py-2 pr-3">SLA</th><th className="py-2">Status</th></tr></thead><tbody>{page.chamados.map((r: string[]) => <tr key={r[0] + r[1]} className="border-t border-[var(--line)]"><td className="py-3 pr-3 font-bold">{r[0]}</td><td className="py-3 pr-3">{r[1]}</td><td className="py-3 pr-3">{r[2]}</td><td className="py-3 pr-3">{r[3]}</td><td className="py-3">{r[4]}</td></tr>)}</tbody></table></div></Section>
      </div>}
      {(sectorTab === "Visão geral" || sectorTab === "Equipamentos") && <div className="mt-5"><Section title="Equipamentos" sub="Equipamentos em atenção e histórico de ocorrências." icon={<Wrench size={19} />}><div className="grid gap-4 lg:grid-cols-2"><ChartCard title="Causas"><div className="h-[220px]"><ResponsiveContainer><PieChart><Pie data={page.causas} dataKey="value" nameKey="name" innerRadius={52} outerRadius={88} paddingAngle={2}>{page.causas.map((_: any, i: number) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}</Pie><Tooltip contentStyle={tipStyle} /></PieChart></ResponsiveContainer></div><div className="mt-2 flex flex-wrap gap-2">{page.causas.map((c: any, i: number) => <span key={c.name} className="pill px-2.5 py-1 text-xs"><i className="mr-1 inline-block h-2 w-2 rounded-full" style={{ background: COLORS[i % COLORS.length] }} />{c.name} · {c.value}%</span>)}</div></ChartCard><div className="soft p-4"><h3 className="font-bold">Equipamentos em atenção</h3><ul className="mt-3 space-y-3 text-sm">{page.equipamentos.map(([n, d]: string[]) => <li key={n} className="flex justify-between gap-3 border-b border-[var(--line)] pb-3"><span className="font-bold">{n}</span><span className="text-right text-[var(--muted)]">{d}</span></li>)}</ul><p className="mt-3 text-sm text-[var(--muted)]">Reincidência sugere causa raiz não resolvida. Revisão do procedimento e da peça aplicada.</p></div></div></Section></div>}
      {(sectorTab === "Visão geral" || sectorTab === "Preventiva") && <div className="mt-5"><Section title="Preventiva" sub="Calendário, percentual no prazo, previsão de falha, intervalo ideal e peças em estoque." icon={<CalendarClock size={19} />}><div className="grid gap-4 lg:grid-cols-[1.2fr_.8fr]"><div><div className="grid grid-cols-2 gap-3"><div className="soft p-4"><p className="text-xs text-[var(--muted)]">Preventivas no prazo</p><p className="mt-1 text-2xl font-extrabold">{sector.id === "clinica" ? "84%" : "72%"}</p></div><div className="soft p-4"><p className="text-xs text-[var(--muted)]">Previsão de falha · 30 dias</p><p className="mt-1 text-2xl font-extrabold">{sector.id === "clinica" ? "2 equip." : "6 equip."}</p></div></div><div className="mt-3 space-y-2">{page.preventiva.map(([d, t]: string[]) => <div key={t} className="soft flex items-center justify-between gap-3 p-3"><span className="font-bold">{t}</span><span className="shrink-0 text-sm text-[var(--muted)]">{d}</span></div>)}</div></div><div className="soft p-4"><h3 className="font-bold">Intervalo ideal e estoque</h3><ul className="mt-3 space-y-3 text-sm leading-6 text-[var(--muted)]">{sector.id === "clinica" ? <><li><strong className="text-[var(--ink)]">Ultrassom:</strong> intervalo de 90 dias, com verificação intermediária de sensor.</li><li><strong className="text-[var(--ink)]">Salas:</strong> 60 dias. Verificação de equipamentos a cada início de turno.</li><li><strong className="text-[var(--ink)]">Monitor:</strong> 45 dias. Teste de bateria incluído na checagem.</li></> : <><li><strong className="text-[var(--ink)]">Autoclave:</strong> intervalo de 45 dias, com verificação intermediária de vedação.</li><li><strong className="text-[var(--ink)]">Centrífuga:</strong> 60 dias. Verificação de balanceamento a cada janela.</li><li><strong className="text-[var(--ink)]">Analisador:</strong> 30 dias. Reagente com cobertura controlada.</li></>}</ul><p className="mt-3 rounded-xl bg-[var(--primary-soft)] p-3 text-sm font-semibold">Peças críticas com cobertura média de 18 dias.</p></div></div></Section></div>}
      {(sectorTab === "Visão geral" || sectorTab === "Disponibilidade") && <div className="mt-5"><Section title="Disponibilidade e produtividade" sub="Disponibilidade, tempo parado, backup e produtividade do setor." icon={<Activity size={19} />}><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Kpi label="Disponibilidade" value={sector.id === "clinica" ? "98,1%" : "95,4%"} note="Meta: 97%. Desvio concentrado nos equipamentos em atenção." icon={<Activity size={15} />} /><Kpi label="Tempo parado" value={sector.id === "clinica" ? "18 h" : "142 h"} note="No mês · parte ligada a espera de verificação." icon={<Clock3 size={15} />} /><Kpi label="Backup disponível" value={sector.id === "clinica" ? "4 / 4" : "9 / 11"} note="Equipamentos de reserva prontos para uso." icon={<ShieldCheck size={15} />} /><Kpi label="Carga por turno" value={sector.id === "clinica" ? "312" : "1.284"} note={sector.id === "clinica" ? "Consultas por dia." : "Exames por dia."} icon={<Wrench size={15} />} /></div><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[520px] text-left text-sm"><thead><tr className="text-[var(--muted)]"><th className="py-2">Turno</th><th className="py-2">Atendimentos</th><th className="py-2">Disponibilidade</th><th className="py-2">Foco</th></tr></thead><tbody>{(sector.id === "clinica" ? [["Manhã", "142", "98,4%", "Consultas"], ["Tarde", "128", "97,8%", "Consultas"], ["Noite", "42", "98,1%", "Retorno"]] : [["Manhã", "512", "96,1%", "Exames"], ["Tarde", "486", "95,8%", "Exames"], ["Noite", "286", "95,4%", "Exames"]]).map((r: string[]) => <tr key={r[0]} className="border-t border-[var(--line)]"><td className="py-3 font-bold">{r[0]}</td><td className="py-3">{r[1]}</td><td className="py-3">{r[2]}</td><td className="py-3">{r[3]}</td></tr>)}</tbody></table></div></Section></div>}
      {(sectorTab === "Visão geral" || sectorTab === "Financeiro") && <div className="mt-5"><Section title="Financeiro básico" sub="Custo por chamado, custo do mês, economia e previsão do setor." icon={<DollarSign size={19} />}><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Kpi label="Custo por chamado" value={page.financeiro.custoChamado} note="Média do trimestre, com peças e mão de obra." icon={<DollarSign size={15} />} /><Kpi label="Custo do mês" value={page.financeiro.custoMes} note="Custo total do setor no mês." icon={<Clock3 size={15} />} /><Kpi label="Economia interna" value={page.financeiro.economia} note="Economia com reparos e revisão de fluxo." icon={<TrendingUp size={15} />} /><Kpi label="Retorno" value={page.financeiro.roi} note="Economia comparada ao custo de terceirização." icon={<TrendingUp size={15} />} /></div><div className="mt-4 grid gap-4 lg:grid-cols-2"><ChartCard title="Previsão de gastos"><div className="h-[220px]"><ResponsiveContainer><AreaChart data={[{ m: "Jul", v: 128 }, { m: "Ago", v: 142 }, { m: "Set", v: 135 }, { m: "Out", v: 152 }, { m: "Nov", v: 148 }, { m: "Dez", v: 164 }]}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="m" tick={{ fill: "var(--muted)", fontSize: 12 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "var(--muted)", fontSize: 12 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={tipStyle} formatter={(v: any) => [`R$ ${v} mil`, "Previsão"]} /><Area type="monotone" dataKey="v" stroke="#0F5F5C" fill="#0F5F5C" fillOpacity={0.16} strokeWidth={2.5} /></AreaChart></ResponsiveContainer></div></ChartCard><div className="soft p-4"><h3 className="font-bold">Decisão do setor</h3><p className="mt-2 text-sm leading-6 text-[var(--muted)]">{sector.id === "clinica" ? "Priorizar a confirmação das consultas e a calibração do ultrassom. Manter a fila organizada por horário marcado." : "Priorizar a preventiva da autoclave e o remanejamento dos exames. Manter o kit de vedação reservado."}</p><div className="mt-3 space-y-2 text-sm"><p className="flex justify-between"><span>Preventivas no prazo</span><strong>{sector.id === "clinica" ? "84%" : "72%"}</strong></p><p className="flex justify-between"><span>SLA no prazo</span><strong>{sector.id === "clinica" ? "95%" : "89%"}</strong></p></div><p className="mt-3 rounded-xl bg-[var(--primary-soft)] p-3 text-sm font-semibold">Recomendação: agir na janela atual evita parada e remanejamento maior na semana.</p></div></div></Section></div>}
      {(sectorTab === "Visão geral" || sectorTab === "Qualidade") && <div className="mt-5"><Section title="Qualidade" sub="Indicadores de qualidade e satisfação do setor." icon={<ShieldCheck size={19} />}><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{page.qualidade.map(([l, v, n]: string[]) => <Kpi key={l} label={l} value={v} note={n} icon={<ShieldCheck size={15} />} />)}</div></Section></div>}
      {(sectorTab === "Visão geral" || sectorTab === "Agendamentos" || sectorTab === "Exames") && <div className="mt-5"><Section title={sector.id === "clinica" ? "Agendamentos" : "Exames"} sub={sector.id === "clinica" ? "Consultas, agendamentos, fila e satisfação." : "Exames, paradas, reagendados e tempo médio."} icon={<CalendarClock size={19} />}><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{page.agenda.map(([l, v, n]: string[]) => <Kpi key={l} label={l} value={v} note={n} icon={<CalendarClock size={15} />} />)}</div><div className="mt-4 soft p-4"><h3 className="font-bold">Simulação de cenários</h3><p className="text-sm text-[var(--muted)]">Ajuste as alavancas para estimar economia, disponibilidade e custo por chamado.</p>{[["Preventivas no prazo", preventiva, setPreventiva, "%", 40, 95], ["Equipe em campo", equipe, setEquipe, "", 5, 14], ["Investimento mensal", investimento, setInvestimento, " mil", 60, 220]].map(([label, val, setter, suffix, min, max]: any) => <label key={label} className="mt-4 block"><span className="flex justify-between text-sm font-bold"><span>{label}</span><span>{val}{suffix}</span></span><input type="range" min={min} max={max} value={val} onChange={(e) => setter(Number(e.target.value))} className="mt-2 w-full accent-[#0F5F5C]" /></label>)}<div className="mt-4 grid grid-cols-3 gap-2 text-center"><div className="rounded-xl bg-[var(--surface)] p-3"><p className="text-[11px] text-[var(--muted)]">Economia</p><p className="font-extrabold">{money(roi.economia)}</p></div><div className="rounded-xl bg-[var(--surface)] p-3"><p className="text-[11px] text-[var(--muted)]">Disponibilidade</p><p className="font-extrabold">{roi.disponibilidade.toFixed(1)}%</p></div><div className="rounded-xl bg-[var(--surface)] p-3"><p className="text-[11px] text-[var(--muted)]">Custo / chamado</p><p className="font-extrabold">{money(roi.custo)}</p></div></div></div></Section></div>}
      <p className="mt-8 pb-4 text-center text-xs text-[var(--muted-2)]">GottCured · Clínica e Laboratório · Dados fictícios para demonstração</p>
    </main></div>}

    {bellOpen && <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/35 p-3 pt-[calc(var(--safe-area-inset-top)+12px)]" onClick={() => setBellOpen(false)}><div className="card max-h-[86vh] w-full max-w-[680px] overflow-hidden shadow-[var(--shadow)]" onClick={(e) => e.stopPropagation()}><div className="flex items-start justify-between gap-3 border-b border-[var(--line)] p-4"><div><h2 className="text-xl font-extrabold">Alertas</h2><p className="mt-1 text-sm text-[var(--muted)]">{unread} não lidos · {alerts.length + predictiveActive.length} no total · {predictiveActive.length} previsões da IA</p></div><div className="flex gap-2"><button disabled={saving} onClick={markAll} className="pill px-3 py-2 text-[13px] font-bold disabled:opacity-50">{saving ? "Salvando…" : "Marcar todos como lidos"}</button><button onClick={() => setBellOpen(false)} className="grid h-9 w-9 place-items-center rounded-full border border-[var(--line)]" aria-label="Fechar alertas"><X size={18} /></button></div></div><div className="grid gap-2 border-b border-[var(--line)] p-4 sm:grid-cols-3"><input value={alertSearch} onChange={(e) => setAlertSearch(e.target.value)} placeholder="Buscar alerta…" className="rounded-full border border-[var(--line)] bg-[var(--surface)] px-3 py-2 text-sm outline-none" /><select value={severity} onChange={(e) => setSeverity(e.target.value)} className="rounded-full border border-[var(--line)] bg-[var(--surface)] px-3 py-2 text-sm"><option>Todas</option><option>Crítico</option><option>Alto</option><option>Médio</option></select><select value={sectorFilter} onChange={(e) => setSectorFilter(e.target.value)} className="rounded-full border border-[var(--line)] bg-[var(--surface)] px-3 py-2 text-sm"><option>Todos</option>{Array.from(new Set(alerts.map((a) => a.sector))).map((s) => <option key={s}>{s}</option>)}</select></div><div className="border-b border-[var(--line)] px-4 pb-3 pt-1"><div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar" role="tablist" aria-label="Grupos de alertas"><button onClick={() => setAlertGroup("todos")} className={`pill shrink-0 px-3.5 py-2 text-[13px] font-semibold ${alertGroup === "todos" ? "chip-active" : ""}`}>Todos</button><button onClick={() => setAlertGroup("previsoes")} className={`pill shrink-0 px-3.5 py-2 text-[13px] font-semibold ${alertGroup === "previsoes" ? "chip-active" : ""}`}>Previsões da IA · {predictiveActive.length}</button></div><div className="mt-1 flex gap-2 overflow-x-auto pb-1 no-scrollbar" aria-label="Filtros de alertas">{["Todos", "Urgentes", "Previsões", "Críticos"].map((f) => <button key={f} onClick={() => setAlertKindFilter(f)} className={`pill shrink-0 px-3 py-1.5 text-[12px] font-semibold ${alertKindFilter === f ? "chip-active" : ""}`}>{f}</button>)}</div>{alertGroup === "previsoes" && <p className="mt-1 text-[13px] text-[var(--muted)]">Previsões da IA — Clínica · cada previsão mostra probabilidade, motivo e ação sugerida.</p>}<div className={`mt-2 space-y-2 overflow-y-auto pr-0.5 ${alertGroup === "previsoes" ? "max-h-[46vh]" : "max-h-[26vh]"}`}>{predictiveVisible.map((a) => <article key={a.id} className="rounded-2xl border border-[var(--line)] bg-[var(--surface-3)] p-3"><div className="flex flex-wrap items-center justify-between gap-2"><span className="rounded-full bg-[var(--primary-soft)] px-2.5 py-1 text-[11px] font-bold text-[var(--primary)]">{a.category}</span><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${a.level === "Alto" ? "bg-[#F8DEDC] text-[#8B2626]" : a.level === "Médio" ? "bg-[#FFF0C5] text-[#7A5600]" : "bg-[var(--primary-soft)] text-[var(--primary)]"}`}>Nível {a.level} · {a.probability}%</span></div><h3 className="mt-2 text-[14px] font-extrabold leading-snug">{a.title}</h3><p className="mt-1 text-[13px] leading-5 text-[var(--muted)]">{a.detail}</p><p className="mt-1 text-[13px] leading-5"><strong>Motivo:</strong> {a.reason}</p><div className="mt-2 h-2 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{ width: `${a.probability}%` }} /></div>{predictiveDone.has(a.id) && <p className="mt-2 text-[12px] font-bold text-[var(--ok)]">✓ Ação feita</p>}{a.actionOptions && <label className="mt-2 block text-[12px] font-bold">Ação sugerida<select value={predictiveChoice[a.id] || a.actionOptions[0]} onChange={(e) => setPredictiveChoice((p) => ({ ...p, [a.id]: e.target.value }))} className="mt-1 w-full rounded-full border border-[var(--line)] bg-[var(--surface)] px-3 py-2 text-[13px]">{a.actionOptions.map((o) => <option key={o}>{o}</option>)}</select></label>}<div className="mt-2 flex flex-wrap gap-2"><button onClick={() => handlePredictiveAction(a)} className="rounded-full bg-[var(--primary)] px-3 py-1.5 text-[12px] font-bold text-white">{a.actionLabel}</button><button onClick={() => ignorePredictive(a)} className="pill px-3 py-1.5 text-[12px] font-bold">Ignorar</button><button onClick={() => resolvePredictive(a)} className="pill px-3 py-1.5 text-[12px] font-bold">Marcar como resolvido</button></div></article>)}{predictiveVisible.length === 0 && <p className="p-2 text-sm text-[var(--muted)]">Nenhuma previsão com esses filtros.</p>}</div></div><div className={`overflow-y-auto p-3 ${alertGroup === "todos" ? "max-h-[28vh]" : "max-h-[52vh]"}`}>{visibleAlerts.map((a) => <article key={a.id} className="mb-2 rounded-2xl border border-[var(--line)] p-4"><div className="flex flex-wrap items-center justify-between gap-2"><span className={`rounded-full px-2.5 py-1 text-xs font-bold ${a.severity === "Crítico" ? "bg-[#F8DEDC] text-[#8B2626]" : a.severity === "Alto" ? "bg-[#FFF0C5] text-[#7A5600]" : "bg-[var(--primary-soft)] text-[var(--primary)]"}`}>{a.severity}</span><span className="text-xs text-[var(--muted)]">{a.sector} · {a.time} · {readIds.has(a.id) ? "Lido" : snoozed.has(a.id) ? "Adiado" : "Não lido"}</span></div><h3 className="mt-2 font-extrabold">{a.title}</h3><p className="mt-1 text-sm leading-6 text-[var(--muted)]">{a.detail}</p><p className="mt-1 text-xs font-bold">{a.equipment}</p><div className="mt-3 flex flex-wrap gap-2">{[["Ver equipamento", () => { setBellOpen(false); goSector(a.sector === "Laboratório" ? "laboratorio" : "clinica"); }], ["Abrir chamado", () => setNotice(`Chamado criado para ${a.equipment}. A equipe foi notificada.`)], ["Adiar", () => snooze(a.id)], ["Marcar como lido", () => markRead(a.id)]].map(([label, fn]: any) => <button key={label} onClick={fn} className="pill px-3 py-1.5 text-[12px] font-bold">{label}</button>)}</div></article>)}{visibleAlerts.length === 0 && alertGroup !== "previsoes" && <p className="p-4 text-center text-sm text-[var(--muted)]">Nenhum alerta com esses filtros.</p>}</div></div></div>}
    {toast && <div className="fixed bottom-4 left-1/2 z-[60] w-[calc(100%-2rem)] max-w-[560px] -translate-x-1/2 rounded-2xl bg-[var(--ink)] px-4 py-3 text-sm font-semibold text-[var(--bg)] shadow-xl">{toast}</div>}
    {notice && <div className="fixed bottom-4 left-1/2 z-[60] flex w-[calc(100%-2rem)] max-w-[620px] -translate-x-1/2 items-center justify-between gap-3 rounded-2xl bg-[var(--surface)] px-4 py-3 text-sm font-semibold shadow-xl ring-1 ring-[var(--line)]"><span>{notice}</span><button onClick={() => setNotice("")} className="shrink-0 rounded-full px-2 py-1 text-[var(--primary)]">Fechar</button></div>}
  </div>;
}
